.3:a:checkmk:checkmk:2.5.0:b2:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:b3:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p1:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p2:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p3:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p4:*:*:*:*:*:*"]', 4.8, 4.8, null, 'MEDIUM', null, '["CWE-79"]', 'Stored cross-site scripting in the service discovery active check output in Checkmk <2.5.0p5, <2.4.0p31, <2.3.0p48, and all 2.2.0 versions allows an administrator who can configure active or custom checks to inject malicious HTML or JavaScript into check output that executes in the browser of an admin or a user with host read permissions when they run the check on the service discovery page.', 'CVE-2026-9549', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9522', 'NVD', '2026-06-02 16:16:45', '2026-06-02 20:54:12', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9522', '["cpe:2.3:a:devolutions:devolutions_server:*:*:*:*:*:*:*:*"]', null, 5.4, null, 'MEDIUM', null, '["CWE-284"]', 'Improper access control in the PAM account discovery feature in Devolutions Server 2026.1.19 and earlier allows an authenticated user without administrative privileges to delete network discovery scan configurations.', 'CVE-2026-9522', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9490', 'NVD', '2026-05-25 08:16:26', '2026-06-04 19:52:49', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9490', '["cpe:2.3:a:acer:care_center:*:*:*:*:*:*:*:*"]', 6.8, 5.5, null, 'MEDIUM', null, '["CWE-269"]', 'A security vulnerability has been identified in Acer Care Center where the ACCSvc service creates a Named Pipe with a weak Security Descriptor. This vulnerability allows an authenticated local user to connect and send a specially crafted message (message type 0x03) to the pipe, causing the service to crash with exit code 1067 (ERROR_PROCESS_ABORTED). To mitigate this potential local service disruption, Acer requires users to update the software to the latest version.', 'CVE-2026-9490', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9312', 'NVD', '2026-05-27 00:16:39', '2026-06-02 18:31:15', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9312', '["cpe:2.3:a:github:enterprise_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:github:enterprise_server:3.21.1:rc1:*:*:*:*:*:*"]', 9.2, 8.2, null, 'CRITICAL', null, '["CWE-918"]', 'A server-side request forgery (SSRF) vulnerability was identified in GitHub Enterprise Server that allowed an unauthenticated attacker to send crafted requests to internal services by exploiting insufficient input validation in an upload endpoint. By injecting path traversal content into request parameters, an attacker could bypass the intended request flow and redirect internal API calls, potentially accessing internal services and exposing sensitive credentials. This vulnerability affected all versions of GitHub Enterprise Server prior to 3.22 and was fixed in versions 3.16.20, 3.17.17, 3.18.11, 3.19.8, 3.20.4, and 3.21.1. This vulnerability was reported via the GitHub Bug Bounty program.', 'CVE-2026-9312', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9309', 'NVD', '2026-06-01 13:16:33', '2026-06-03 20:02:29', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9309', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:*:iphone_os:*:*"]', null, 5.4, null, 'MEDIUM', null, '["CWE-79"]', 'Firefox for iOS Reader View did not properly escape HTML tags in JSON-LD metadata. A malicious page could inject markup that changed Reader View behavior and leaked sensitive URL parameters. These parameters could then be used to access internal pages, potentially resulting in arbitrary JavaScript execution in an internal origin. This vulnerability was fixed in Firefox for iOS 151.2.', 'CVE-2026-9309', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9308', 'NVD', '2026-06-01 13:16:33', '2026-06-03 20:02:52', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9308', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:*:iphone_os:*:*"]', null, 5.4, null, 'MEDIUM', null, '["CWE-79"]', 'Firefox for iOS Reader View replaced page content in its HTML template before replacing other internal placeholders. A malicious page could include a placeholder string that was later substituted with JSON-LD data, potentially resulting in arbitrary JavaScript execution. This vulnerability was fixed in Firefox for iOS 151.2.', 'CVE-2026-9308', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9251', 'NVD', '2026-05-22 16:16:26', '2026-05-22 18:31:40', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9251', '["cpe:2.3:a:devolutions:devolutions_server:*:*:*:*:*:*:*:*"]', null, 5.4, null, 'MEDIUM', null, '["CWE-862"]', 'Missing authorization in the entry status management feature in Devolutions Server allows a non-administrator authenticated user to bypass the administrator-enforced Pending Approval flow and gain access to an entry\'s data via a crafted status change request.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9249', 'NVD', '2026-05-22 16:16:25', '2026-05-22 19:01:28', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9249', '["cpe:2.3:a:devolutions:devolutions_server:*:*:*:*:*:*:*:*"]', null, 3.1, null, 'LOW', null, '["CWE-620"]', 'Unverified password change in Devolutions Server allows an attacker to change a user\'s password without providing the previous one via a crafted password change request.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9248', 'NVD', '2026-05-22 16:16:25', '2026-05-22 19:02:36', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9248', '["cpe:2.3:a:devolutions:devolutions_server:*:*:*:*:*:*:*:*"]', null, 2.6, null, 'LOW', null, '["CWE-639"]', 'Authorization bypass in the entry duplication feature in Devolutions Server allows an authenticated user with write access to any vault to copy documentation and attachments from an entry in a vault they cannot access via a crafted save request.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9247', 'NVD', '2026-05-22 16:16:25', '2026-05-22 19:03:21', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9247', '["cpe:2.3:a:devolutions:devolutions_server:*:*:*:*:*:*:*:*"]', null, 2.4, null, 'LOW', null, '["CWE-778"]', 'Insufficient logging in the entry export feature in Devolutions Server allows an authenticated user with export permissions to export a sealed entry without triggering the unseal notification to administrators via a crafted export request.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9246', 'NVD', '2026-05-22 16:16:25', '2026-05-22 19:04:04', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9246', '["cpe:2.3:a:devolutions:devolutions_server:*:*:*:*:*:*:*:*"]', null, 4.3, null, 'MEDIUM', null, '["CWE-862"]', 'Improper access control in the entry documentation and attachment features in Devolutions Server allows an authenticated user with vault read access to retrieve the documentation and attachments of sealed entries via a crafted API request.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9245', 'NVD', '2026-05-22 16:16:25', '2026-05-22 19:05:13', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9245', '["cpe:2.3:a:devolutions:devolutions_server:*:*:*:*:*:*:*:*"]', null, 5, null, 'MEDIUM', null, '["CWE-601"]', 'Improper input validation in the external authentication provider flow in Devolutions Server allows an unauthenticated remote attacker to redirect victims to an attacker-controlled domain via a crafted login link.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9224', 'NVD', '2026-05-22 16:16:25', '2026-05-22 18:58:08', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9224', '["cpe:2.3:a:devolutions:devolutions_server:*:*:*:*:*:*:*:*"]', null, 4.3, null, 'MEDIUM', null, '["CWE-862"]', 'Missing authorization in the user profile update feature in Devolutions Server allows an authenticated Active Directory user to modify their own profile attributes via a crafted API request.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9223', 'NVD', '2026-05-22 16:16:24', '2026-05-22 18:57:23', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9223', '["cpe:2.3:a:devolutions:devolutions_server:*:*:*:*:*:*:*:*"]', null, 4.3, null, 'MEDIUM', null, '["CWE-284"]', 'Missing authorization in the vault import feature in Devolutions Server  2026.1.16.0 and earlier allows a low-privileged authenticated user to create new vaults via a crafted import request.', 'CVE-2026-9223', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9170', 'NVD', '2026-05-26 18:16:57', '2026-05-27 19:16:25', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9170', '["cpe:2.3:a:ibm:http_server:8.5.0.0:*:*:*:*:*:*:*", "cpe:2.3:a:ibm:http_server:9.0.0.0:*:*:*:*:*:*:*"]', null, 9.8, null, 'CRITICAL', null, '["CWE-94"]', 'IBM HTTP Server 8.5, and 9.0', 'CVE-2026-9170', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9150', 'NVD', '2026-05-20 23:16:36', '2026-06-02 18:57:51', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9150', '["cpe:2.3:a:opensuse:libsolv:*:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:hardened_images:-:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:openshift_container_platform:4.0:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:satellite:6.0:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:update_infrastructure:4:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:10.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:7.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:8.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:9.0:*:*:*:*:*:*:*"]', null, 6.5, null, 'MEDIUM', null, '["CWE-121"]', 'A flaw was found in libsolv. This stack-based buffer overflow vulnerability occurs in libsolv\'s Debian metadata parser when processing specially crafted Debian repository metadata. An attacker could exploit this by providing malicious SHA384 or SHA512 checksum tags, leading to memory corruption and a denial of service (DoS) in the affected system.', 'CVE-2026-9150', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9149', 'NVD', '2026-05-21 00:16:35', '2026-06-02 01:21:26', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9149', '["cpe:2.3:a:opensuse:libsolv:*:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:hardened_images:-:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:openshift_container_platform:4.0:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:satellite:6.0:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:update_infrastructure:4:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:10.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:7.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:8.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:9.0:*:*:*:*:*:*:*"]', null, 6.5, null, 'MEDIUM', null, '["CWE-122"]', 'A flaw was found in libsolv. This heap buffer overflow vulnerability occurs when a victim processes a specially crafted `.solv` file containing negative size values in the `repo_add_solv` function. This leads to an undersized memory allocation and a subsequent out-of-bounds write. An attacker could exploit this to cause a denial of service (DoS).', 'CVE-2026-9149', null);
