INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9082', 'NVD', '2026-05-20 20:16:41', '2026-05-22 19:38:04', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9082', '["cpe:2.3:a:drupal:drupal:*:*:*:*:*:*:*:*"]', null, 9.8, null, 'CRITICAL', null, '["CWE-89"]', 'Improper Neutralization of Special Elements used in an SQL Command (\'SQL Injection\') vulnerability in Drupal Drupal core allows SQL Injection.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9078', 'NVD', '2026-05-25 15:16:22', '2026-05-28 20:20:06', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9078', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:*:iphone_os:*:*"]', null, 5.4, null, 'MEDIUM', null, '["CWE-451"]', 'Firefox for iOS displayed specially crafted right-to-left (RTL) and internationalized domain names (IDNs) incorrectly in link preview UI surfaces. A crafted RTL hostname could visually reorder portions of the displayed domain, causing attacker-controlled sites to appear as trusted origins. This vulnerability was fixed in Firefox for iOS 151.1.', 'CVE-2026-9078', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9064', 'NVD', '2026-05-20 10:16:28', '2026-06-02 19:01:58', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9064', '["cpe:2.3:a:redhat:directory_server:11.0:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:directory_server:12.0:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:directory_server:13.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:389_directory_server:-:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:10.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:6.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:7.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:8.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:9.0:*:*:*:*:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-770"]', 'A flaw was found in 389-ds-base. The get_ldapmessage_controls_ext() function in the LDAP server does not enforce an upper bound on the number of controls per LDAP message. A remote, unauthenticated attacker can send a specially crafted LDAP request containing hundreds of thousands of minimal controls within the default maximum BER message size (2 MB), causing excessive CPU consumption and heap allocation on the server. Under concurrent exploitation, this leads to significant latency degradation, worker thread starvation, or out-of-memory termination, resulting in a denial of service.', 'CVE-2026-9064', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9047', 'NVD', '2026-05-22 16:16:23', '2026-05-22 18:55:11', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9047', '["cpe:2.3:a:devolutions:devolutions_server:*:*:*:*:*:*:*:*"]', null, 7.6, null, 'HIGH', null, '["CWE-305"]', 'Improper handling of factor key state in the multi-factor authentication management feature in Devolutions Server allows an attacker with knowledge of a user\'s password to bypass the user\'s multi-factor authentication after the user reconfigures their factors.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-9035', 'NVD', '2026-05-27 14:17:38', '2026-06-05 18:57:10', 'https://nvd.nist.gov/vuln/detail/CVE-2026-9035', '["cpe:2.3:a:ibm:aspera_high-speed_transfer_endpoint:*:*:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_endpoint:4.4.7:-:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_endpoint:4.4.7:fixpack1:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_server:4.4.7:-:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_server:4.4.7:fixpack1:*:*:*:*:*:*"]', null, 6.5, null, 'MEDIUM', null, '["CWE-22"]', 'IBM Aspera High-Speed Transfer Endpoint 3.7.4 through 4.4.7 Fix Pack 1 and IBM Aspera High-Speed Transfer Server 3.7.4 through 4.4.7 Fix Pack 1 and IBM Aspera High-Speed Transfer Endpoint are affected by a potential arbitrary file read in the asperahttpd component. An authenticated user may be able to take advantage of this vulnerability to access files in the server’s local storage that they should not have access to.', 'CVE-2026-9035', null);
