.3:a:checkmk:checkmk:2.5.0:b2:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:b3:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p1:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p2:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p3:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p4:*:*:*:*:*:*"]', 8.5, 5.4, null, 'HIGH', null, '["CWE-79"]', 'Improper neutralization of HTML-encoded characters in the URL validation function in Checkmk <2.5.0p5, <2.4.0p31, <2.3.0p48, and all 2.2.0 versions allows an authenticated user to bypass URL validation and inject malicious URLs such as javascript: URIs, resulting in cross-site scripting when another user interacts with the crafted link.', 'CVE-2026-8833', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8752', 'NVD', '2026-05-17 12:16:43', '2026-05-19 17:44:01', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8752', '["cpe:2.3:a:h2o:h2o:*:*:*:*:*:*:*:*"]', 5.5, 5.3, 5, 'MEDIUM', null, '["CWE-266", "CWE-284"]', 'A weakness has been identified in h2oai h2o-3 up to 7402. This vulnerability affects the function exec of the file h2o-core/src/main/java/water/rapids/ast/prims/misc/AstSetProperty.java of the component Rapids setproperty Primitive Handler. Executing a manipulation can lead to improper access controls. The attack may be performed from remote. The exploit has been made available to the public and could be used for attacks. The vendor was contacted early about this disclosure but did not respond in any way.', 'CVE-2026-8752', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8751', 'NVD', '2026-05-17 12:16:42', '2026-05-19 17:46:04', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8751', '["cpe:2.3:a:h2o:h2o:*:*:*:*:*:*:*:*"]', 5.5, 7.3, 7.5, 'MEDIUM', null, '["CWE-20", "CWE-502"]', 'A security flaw has been discovered in h2oai h2o-3 up to 7402. This affects the function importBinaryModel of the file h2o-core/src/main/java/hex/Model.java of the component JAR Handler. Performing a manipulation results in deserialization. The attack is possible to be carried out remotely. The exploit has been released to the public and may be used for attacks. The vendor was contacted early about this disclosure but did not respond in any way.', 'CVE-2026-8751', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8750', 'NVD', '2026-05-17 11:16:35', '2026-05-19 18:22:34', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8750', '["cpe:2.3:a:h2o:h2o:*:*:*:*:*:*:*:*"]', 5.5, 5.3, 5, 'MEDIUM', null, '["CWE-200", "CWE-284"]', 'A vulnerability was identified in h2oai h2o-3 up to 7402. Affected by this issue is the function importFiles of the file h2o-core/src/main/java/water/persist/PersistNFS.java of the component ImportFile API. Such manipulation leads to information disclosure. The attack can be executed remotely. The exploit is publicly available and might be used. The vendor was contacted early about this disclosure but did not respond in any way.', 'CVE-2026-8750', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8746', 'NVD', '2026-05-17 11:16:35', '2026-05-18 21:16:41', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8746', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-119", "CWE-416"]', 'A security flaw has been discovered in Open5GS up to 2.7.7. Affected by this issue is the function discover_handler in the library /lib/sbi/nghttp2-server.c of the component NRF. The manipulation results in use after free. The attack can be launched remotely. The exploit has been released to the public and may be used for attacks. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8746', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8745', 'NVD', '2026-05-17 10:16:36', '2026-05-18 18:34:20', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8745', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability was identified in Open5GS up to 2.7.7. Affected by this vulnerability is the function ogs_timer_add in the library /src/ausf/nausf-handler.c of the component AUSF. The manipulation leads to denial of service. The attack can be initiated remotely. The exploit is publicly available and might be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8745', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8744', 'NVD', '2026-05-17 10:16:36', '2026-05-18 18:34:40', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8744', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability was determined in Open5GS up to 2.7.7. Affected is the function ogs_sbi_subscription_data_add/ogs_sbi_nf_service_add in the library /lib/sbi/context.c of the component NRF. Executing a manipulation can lead to denial of service. It is possible to launch the attack remotely. The exploit has been publicly disclosed and may be utilized. This patch is called 819db11a08b9736a3576c4f99ceb28f7eb99523a. A patch should be applied to remediate this issue.', 'CVE-2026-8744', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8743', 'NVD', '2026-05-17 10:16:35', '2026-05-19 01:35:11', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8743', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 6.3, 6.5, 'LOW', null, '["CWE-266", "CWE-285"]', 'A vulnerability was found in Open5GS up to 2.7.6. This impacts the function ran_ue_find_by_amf_ue_ngap_id of the file src/amf/context.c of the component AMF/MME. Performing a manipulation results in improper authorization. It is possible to initiate the attack remotely. The exploit has been made public and could be used. The patch is named 5746b8576cfceec18ed87eb7d8cf11b1fb4cd8b1. It is suggested to install a patch to address this issue.', 'CVE-2026-8743', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8731', 'NVD', '2026-05-17 05:16:16', '2026-05-18 18:35:31', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8731', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability has been found in Open5GS up to 2.7.7. Affected is the function ogs_sbi_client_add in the library /lib/sbi/client.c of the component NRF. The manipulation of the argument client_pool leads to denial of service. It is possible to initiate the attack remotely. The exploit has been disclosed to the public and may be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8731', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8730', 'NVD', '2026-05-17 05:16:16', '2026-05-19 01:32:44', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8730', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A flaw has been found in Open5GS up to 2.7.6. This impacts the function ogs_sbi_nf_instance_set_id in the library /lib/sbi/context.c of the component NRF. Executing a manipulation of the argument nfInstanceId can lead to denial of service. The attack may be performed from remote. The exploit has been published and may be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8730', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8729', 'NVD', '2026-05-17 05:16:16', '2026-05-18 18:35:21', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8729', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability was detected in Open5GS up to 2.7.7. This affects an unknown function in the library /lib/sbi/message.c of the component NRF. Performing a manipulation of the argument service-names/snssais results in denial of service. The attack is possible to be carried out remotely. The exploit is now public and may be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8729', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8728', 'NVD', '2026-05-17 04:16:58', '2026-05-18 18:35:07', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8728', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A security vulnerability has been detected in Open5GS up to 2.7.7. The impacted element is the function ogs_sbi_discovery_option_parse_plmn_list in the library /lib/sbi/conv.c of the component NRF. Such manipulation of the argument target-plmn-list leads to denial of service. The attack can be executed remotely. The exploit has been disclosed publicly and may be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8728', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8711', 'NVD', '2026-05-19 15:16:33', '2026-06-04 13:29:57', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8711', '["cpe:2.3:a:f5:njs:*:*:*:*:*:*:*:*"]', 9.2, 8.1, null, 'CRITICAL', null, '["CWE-122"]', 'NGINX JavaScript has a vulnerability when the js_fetch_proxy directive is configured with at least one client-controlled NGINX variable (for example, $http_*, $arg_*, $cookie_*) and a location invoking the ngx.fetch() operation from NGINX JavaScript. An unauthenticated attacker can exploit this vulnerability by sending crafted HTTP requests. This may cause a heap buffer overflow in the NGINX worker process leading to a restart. Additionally, attackers can execute code on systems with Address Space Layout Randomization (ASLR) disabled or when the attacker can bypass ASLR. 
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8706', 'NVD', '2026-05-19 16:16:22', '2026-05-20 14:23:35', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8706', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:*:iphone_os:*:*"]', null, 6.5, null, 'MEDIUM', null, '["CWE-200", "CWE-306"]', 'Firefox for iOS hosted Reader mode on an unauthenticated local web server, allowing another application on the same device to request arbitrary URLs and receive the response rendered with the signed-in user\'s cookies. This vulnerability was fixed in Firefox for iOS 151.0.', 'CVE-2026-8706', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8696', 'NVD', '2026-05-15 21:16:39', '2026-05-19 14:16:49', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8696', '["cpe:2.3:a:radare:radare2:*:*:*:*:*:*:*:*"]', 8.7, 7.5, null, 'HIGH', null, '["CWE-416"]', 'radare2 6.1.5 contains a use-after-free vulnerability in the gdbr_pids_list() function within the GDB client core that allows remote attackers to cause a denial of service or potentially execute arbitrary code by sending malformed thread information responses. Attackers can trigger the vulnerability by causing qsThreadInfo to fail after qfThreadInfo successfully allocates RDebugPid structures, resulting in double-free memory corruption when the error path attempts to clean up the list.', 'CVE-2026-8696', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8695', 'NVD', '2026-05-15 17:16:49', '2026-05-18 18:38:29', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8695', '["cpe:2.3:a:radare:radare2:*:*:*:*:*:*:*:*"]', 8.7, 7.5, null, 'HIGH', null, '["CWE-416"]', 'radare2 6.1.5 contains a use-after-free vulnerability in the gdbr_threads_list() function that allows remote attackers to trigger memory corruption by sending a valid qfThreadInfo response followed by a malformed qsThreadInfo response. Attackers can exploit this vulnerability through GDB remote debugging to cause a denial of service or potentially achieve code execution by manipulating thread list processing.', 'CVE-2026-8695', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8632', 'NVD', '2026-05-20 21:16:18', '2026-05-21 18:58:59', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8632', '["cpe:2.3:a:hp:linux_imaging_and_printing:*:*:*:*:*:*:*:*"]', 8.5, 7.8, null, 'HIGH', null, '["CWE-77"]', 'A potential security vulnerability has been identified in the HP Linux Imaging and Printing Software. This potential vulnerability may allow escalation of privileges and/or arbitrary code execution via operating system command injection.', 'CVE-2026-8632', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8631', 'NVD', '2026-05-20 21:16:18', '2026-05-21 18:58:41', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8631', '["cpe:2.3:a:hp:linux_imaging_and_printing:*:*:*:*:*:*:*:*"]', 9.3, 9.8, null, 'CRITICAL', null, '["CWE-122", "CWE-190"]', 'A potential security vulnerability has been identified in the HP Linux Imaging and Printing Software. This potential vulnerability may allow escalation of privileges and/or arbitrary code execution via an integer overflow in the hpcups processing path when handling crafted print data.', 'CVE-2026-8631', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8606', 'NVD', '2026-05-27 00:16:37', '2026-06-01 18:33:07', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8606', '["cpe:2.3:a:github:enterprise_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:github:enterprise_server:3.21.0:*:*:*:*:*:*:*"]', 7, 5.9, null, 'HIGH', null, '["CWE-918"]', 'A Server-Side Request Forgery (SSRF) vulnerability was identified in GitHub Enterprise Server that allowed an attacker to cause the server to issue HTTP requests to internal services via the security advisories package lookup feature. By directing requests to an internal management service and measuring response timing, an attacker could infer the values of sensitive environment variables, including signing secrets and private keys. Exploitation required GitHub Packages to be enabled; on instances not running in private mode the vulnerability was exploitable without authentication, otherwise any authenticated user could exploit it. This vulnerability affected all versions of GitHub Enterprise Server prior to 3.21.1 and was fixed in versions 3.20.3, 3.19.7, 3.18.10, 3.17.16, and 3.16.19. This vulnerability was reported via the GitHub Bug Bounty program.', 'CVE-2026-8606', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8605', 'NVD', '2026-05-19 18:16:32', '2026-05-21 17:16:07', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8605', '["cpe:2.3:a:scadabr:scadabr:1.2:*:*:*:*:*:*:*"]', 5.1, 9.8, null, 'MEDIUM', null, '["CWE-798"]', 'In ScadaBR version 1.2.0, a Use of Hard-Coded Credentials vulnerability could allow an attacker to access the SCADA system as admin.', 'CVE-2026-8605', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8604', 'NVD', '2026-05-19 18:16:32', '2026-05-21 17:16:54', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8604', '["cpe:2.3:a:scadabr:scadabr:1.2:*:*:*:*:*:*:*"]', 8.6, 8.8, null, 'HIGH', null, '["CWE-352"]', 'In ScadaBR version 1.2.0, a CSRF vulnerability could allow an attacker to trigger any authenticated action through a victim\'s session by luring any logged-in user to a malicious webpage.', 'CVE-2026-8604', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8603', 'NVD', '2026-05-19 18:16:31', '2026-05-21 17:17:31', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8603', '["cpe:2.3:a:scadabr:scadabr:1.2:*:*:*:*:*:*:*"]', 8.7, 9.8, null, 'HIGH', null, '["CWE-78"]', 'In ScadaBR version 1.2.0, an OS Command Injection vulnerability could allow an attacker to execute commands as root on the SCADA system.', 'CVE-2026-8603', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8602', 'NVD', '2026-05-19 18:16:31', '2026-05-21 17:19:21', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8602', '["cpe:2.3:a:scadabr:scadabr:1.2:*:*:*:*:*:*:*"]', 8.8, 9.1, null, 'HIGH', null, '["CWE-306"]', 'In ScadaBR version 1.2.0, a Missing Authentication for Critical Function vulnerability could allow an unauthenticated attacker to send a HTTP GET requests to the SCADA system and inject arbitrary sensor readings.', 'CVE-2026-8602', null);
