INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8435', 'NVD', '2026-05-21 22:16:52', '2026-05-22 19:15:13', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8435', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 6.5, null, 'LOW', null, '["CWE-352", "CWE-1275"]', 'Concrete CMS 9 before 9.5.0 is vulnerable to Cross Site Request Forgery (CSRF) at concrete/controllers/backend/file approveVersion(). The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:P/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8435', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8434', 'NVD', '2026-05-21 22:16:51', '2026-05-26 17:59:46', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8434', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 8.8, null, 'LOW', null, '["CWE-352", "CWE-1275"]', 'Concrete CMS 9 before 9.5.0 is vulnerable to Cross Site Request Forgery (CSRF) at concrete/controllers/backend/file rescanMultiple(). The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:P/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8434', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8433', 'NVD', '2026-05-21 22:16:51', '2026-05-26 18:19:12', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8433', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 8.8, null, 'LOW', null, '["CWE-352", "CWE-1275"]', 'Concrete CMS 9 before 9.5.0 is vulnerable to Cross Site Request Forgery (CSRF) at concrete/controllers/backend/file rescan(). The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:P/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8433', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8432', 'NVD', '2026-05-21 22:16:51', '2026-05-26 18:46:09', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8432', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 8.8, null, 'LOW', null, '["CWE-352", "CWE-1275"]', 'Concrete CMS 9 before 9.5.0 is vulnerable to Cross Site Request Forgery (CSRF) at concrete/controllers/backend/file star(). The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:P/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8432', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8428', 'NVD', '2026-05-21 21:16:34', '2026-05-26 14:57:02', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8428', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 7.5, 8.8, null, 'HIGH', null, '["CWE-352", "CWE-829"]', 'Concrete CMS 9.5.0 and below emits a CSRF token in the local_available_update.php view ($token->output(\'do_update\')) but the corresponding do_update() method in concrete/controllers/single_page/dashboard/system/update/update.php never calls $this->token->validate(\'do_update\'). The form is rendered as a POST form, meaning the token reaches the browser, but because the controller discards it without verification, an attacker can craft a cross-site POST that triggers a core CMS update to an attacker-specified version string.  In order to be vulnerable, theictim must be passing canUpgrade()anda valid update version must be present under DIR_CORE_UPDATES. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 7.5 with vector CVSS:4.0/AV:N/AC:H/AT:P/PR:N/UI:A/VC:H/VI:H/VA:H/SC:N/SI:N/SA:N. Thanks https://github.com/maru1009 for reporting.', 'CVE-2026-8428', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8427', 'NVD', '2026-05-21 22:16:51', '2026-05-26 18:49:19', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8427', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 8.8, null, 'LOW', null, '["CWE-352", "CWE-1275"]', 'Concrete CMS 9 before 9.5.0 is vulnerable to Cross Site Request Forgery (CSRF) at concrete/controllers/backend/file removeFavoriteFolder($id). The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:P/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8427', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8426', 'NVD', '2026-05-21 21:16:34', '2026-05-26 14:57:35', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8426', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 7.5, 8.8, null, 'HIGH', null, '["CWE-352", "CWE-829"]', 'Concrete CMS 9.5.0 and below does not validate a CSRF token before processing requests to /dashboard/extend/update/prepare_remote_upgrade/<remoteMPID>. An attacker who controls the remote package returned for a known marketplace item ID can overwrite the package PHP on disk and force its upgrade() method to execute in a single browser navigation. This results in remote code execution as the web server user.   In order to be vulnerable, the victim must be passing canInstallPackages, victim site must be connected to the Concrete marketplace; and the attacker controls the package returned for a marketplace item ID already installed on the victim site. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 7.5 with vector CVSS:4.0/AV:N/AC:H/AT:P/PR:N/UI:A/VC:H/VI:H/VA:H/SC:N/SI:N/SA:N. Thanks https://github.com/maru1009 for reporting.', 'CVE-2026-8426', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8421', 'NVD', '2026-05-21 21:16:34', '2026-05-26 14:57:19', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8421', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 7.5, 8.8, null, 'HIGH', null, '["CWE-352"]', 'Concrete CMS 9.5.0 and below contains a CSRF vulnerability in the install_package() method of concrete/controllers/single_page/dashboard/extend/install.php.  An attacker who can cause an authenticated administrator to visit a crafted page,  and who has placed or caused a package to be present under DIR_PACKAGES/<handle>/, can force the installation of that package without any CSRF protection. Package installation executes the package controller\'s install() method as the web server user, enabling remote code execution.  In order to be vulnerable, the victim must be passing canInstallPackages. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 7.5 with vector CVSS:4.0/AV:N/AC:H/AT:P/PR:N/UI:A/VC:H/VI:H/VA:H/SC:N/SI:N/SA:N. Thanks  https://github.com/maru1009  for reporting.', 'CVE-2026-8421', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8417', 'NVD', '2026-05-21 21:16:33', '2026-05-26 14:57:48', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8417', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 7.5, 8.8, null, 'HIGH', null, '["CWE-352"]', 'Concrete CMS 9.5.0 and below does not validate a CSRF token before processing requests to /dashboard/extend/update/do_update/<pkgHandle>. The do_update() method in concrete/controllers/single_page/dashboard/extend/update.php checks only canInstallPackages() before executing upgradeCoreData() and upgrade() on the named package\'s controller. Because the endpoint is a state-changing GET route with no token enforcement, an attacker can force an authenticated administrator to trigger a package upgrade via a single cross-site navigation.In order to be vulnerable, the victim must be passing canInstallPackages() and and a target package must already be already installed. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 7.5 with vector CVSS:4.0/AV:N/AC:H/AT:P/PR:N/UI:A/VC:H/VI:H/VA:H/SC:N/SI:N/SA:N. Thanks  https://github.com/maru1009  for reporting.', 'CVE-2026-8417', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8416', 'NVD', '2026-05-21 22:16:51', '2026-05-26 18:55:36', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8416', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 8.8, null, 'LOW', null, '["CWE-352", "CWE-1275"]', 'Concrete CMS 9 before 9.5.0 is vulnerable to Cross Site Request Forgery (CSRF) at concrete/controllers/backend/file addFavoriteFolder($id). The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:P/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8416', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8415', 'NVD', '2026-05-21 22:16:51', '2026-05-26 18:58:27', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8415', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 8.8, null, 'LOW', null, '["CWE-352", "CWE-1275"]', 'Concrete CMS 9 before 9.5.0 is vulnerable to Cross Site Request Forgery (CSRF) at concrete/controllers/dialog/express/association/reorder. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:P/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8415', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8414', 'NVD', '2026-05-21 22:16:51', '2026-05-26 18:59:58', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8414', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 8.8, null, 'LOW', null, '["CWE-352", "CWE-1275"]', 'Concrete CMS 9 before 9.5.0 is vulnerable to Cross Site Request Forgery (CSRF) at concrete/controllers/dialog/event/duplicate. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:P/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8414', null);
