INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8410', 'NVD', '2026-05-21 22:16:50', '2026-05-26 18:31:39', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8410', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 8.8, null, 'LOW', null, '["CWE-352", "CWE-1275"]', 'Concrete CMS 9 before 9.5.0 is vulnerable to Cross Site Request Forgery (CSRF) at concrete/controllers/dialog/logs/bulk/delete.  The The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:P/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8410', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8409', 'NVD', '2026-05-21 22:16:50', '2026-05-26 18:32:36', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8409', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 8.8, null, 'LOW', null, '["CWE-352", "CWE-1275"]', 'Concrete CMS 9 before 9.5.0 is vulnerable to Cross Site Request Forgery (CSRF) at concrete/controllers/dialog/logs/delete.  The The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:P/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8409', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8407', 'NVD', '2026-05-12 17:16:22', '2026-05-26 12:32:46', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8407', '["cpe:2.3:a:devolutions:devolutions_server:*:*:*:*:*:*:*:*"]', null, 4.3, null, 'MEDIUM', null, '["CWE-862"]', 'Missing authorization in the PAM module in Devolutions Server allows an authenticated user with a PAM license but no additional permissions to obtain OTP secret keys and recovery codes via crafted requests to PAM API endpoints.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8401', 'NVD', '2026-05-12 15:16:20', '2026-05-19 18:16:31', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8401', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*"]', null, 9.8, null, 'CRITICAL', null, '["CWE-693"]', 'Sandbox escape in the Profile Backup component. This vulnerability was fixed in Firefox 150.0.3, Firefox ESR 115.36, Firefox ESR 140.11, and Thunderbird 140.11.', 'CVE-2026-8401', null);
