INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8390', 'NVD', '2026-05-12 14:17:12', '2026-05-14 18:53:56', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8390', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*"]', null, 7.3, null, 'HIGH', null, '["CWE-416"]', 'Use-after-free in the JavaScript: WebAssembly component. This vulnerability was fixed in Firefox 150.0.3.', 'CVE-2026-8390', null);
