INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8388', 'NVD', '2026-05-12 14:17:11', '2026-05-19 18:16:31', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8388', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*"]', null, 6.5, null, 'MEDIUM', null, '["CWE-119"]', 'Incorrect boundary conditions in the JavaScript Engine: JIT component. This vulnerability was fixed in Firefox 150.0.3, Firefox ESR 115.36, Firefox ESR 140.11, and Thunderbird 140.11.', 'CVE-2026-8388', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8353', 'NVD', '2026-05-22 15:16:26', '2026-05-22 19:17:13', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8353', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.1, 4.8, null, 'LOW', null, '["CWE-79"]', 'Concrete CMS version 9.0 to 9.5.0 is vulnerable to Stored XSS via page name in the Atomik theme. A rogue editor can inject arbitrary JavaScript that executes in the context of any authenticated user visiting the affected account pages. This can lead to session hijacking, credential theft, malicious actions performed on behalf of users, and potential privilege escalation. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.1 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:H/UI:N/VC:L/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8353', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8350', 'NVD', '2026-05-21 21:16:33', '2026-05-26 17:42:10', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8350', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 7.5, 8.8, null, 'HIGH', null, '["CWE-863"]', 'Concrete CMS 9.5.0 and below is vulnerable to missing authorization in the bulk_user_assignment.php which can lead to privilege escalation to Administrative Group. Any authenticated user with access to the bulk user assignment dashboard page can add any user email to any group and can remove legitimate admins. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 7.5 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:H/UI:N/VC:H/VI:H/VA:H/SC:N/SI:N/SA:N. Thanks Vincent55 for reporting.', 'CVE-2026-8350', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8347', 'NVD', '2026-05-22 15:16:26', '2026-05-22 19:16:34', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8347', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 4.3, null, 'LOW', null, '["CWE-639"]', 'Concrete CMS 9.5.0 and below is vulnerable to IDOR + wrong-authorization-level in the Express association Reorder dialog.  This can cause Cross-entity state tampering with view-only permission on one entry. To be affected, a website has to be using express and relying on express entity ordering. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:L/UI:N/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Winston Crooker for reporting.', 'CVE-2026-8347', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8340', 'NVD', '2026-05-22 15:16:26', '2026-05-26 14:55:32', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8340', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 4.3, null, 'LOW', null, '["CWE-352"]', 'Concrete CMS 9.5.0 and below is vulnerable to CSRF via Backend\\File::approveVersion. Victim with edit_file_contents permission is CSRF\'d into publishing an attacker-chosen previously-uploaded version (downgrade to an older version of a file, or activation of a co-editor\'s unpublished version). The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:P/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Winston Crooker for reporting.', 'CVE-2026-8340', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8337', 'NVD', '2026-05-21 22:16:50', '2026-05-26 17:13:07', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8337', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 6.3, 5.3, null, 'MEDIUM', null, '["CWE-565", "CWE-639"]', 'Concrete CMS 9.5.0 and below is vulnerable to IDOR in surveys. To be vulnerable, a site would have to be configured in such a way that both public and private surveys are present on the site. An unauthenticated attacker can vote in the restricted survey by submitting the restricted optionID through the public survey’s endpoint. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 6.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:N/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks  Zer0daySec https://github.com/Zee99y  for reporting', 'CVE-2026-8337', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8336', 'NVD', '2026-05-13 04:17:42', '2026-05-18 12:54:59', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8336', '["cpe:2.3:a:mongodb:mongodb:*:*:*:*:*:*:*:*"]', 7.7, 7.5, null, 'HIGH', null, '["CWE-416"]', 'After invoking $_internalJsEmit, which is not intended to be directly accessible, or mapreduce command’s map function in a certain way, an authenticated user can subsequently crash mongod when the server-side JavaScript engine (through $where, $function, mapreduce reduce stage, etc.) is used also in a specific way, resulting in a post-authentication denial-of-service.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8327', 'NVD', '2026-05-21 22:16:50', '2026-05-26 17:18:10', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8327', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 5.3, 4.3, null, 'MEDIUM', null, '["CWE-269", "CWE-620", "CWE-915"]', 'Concrete CMS below 9.5.0 and below is vulnerable to password change without reauthorization and session-hardening bypass. The user-profile edit controller passes the entire raw POST array to UserInfo::update() without field whitelisting resulting in password change without requiring the current password  and also resulting in registered users able to disable the per-user-IP-pinning in the session validator which is meant to detect hijacking.  The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 5.3 with vector CVSS:4.0/AV:N/AC:L/AT:N/PR:L/UI:N/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks 0x4c616e for reporting.', 'CVE-2026-8327', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8292', 'NVD', '2026-05-11 16:17:43', '2026-05-14 18:19:20', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8292', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A security vulnerability has been detected in Open5GS up to 2.7.7. The affected element is the function yuarel_parse in the library /lib/sbi/conv.c of the component NRF. Such manipulation of the argument hnrf-uri leads to denial of service. The attack may be performed from remote. The exploit has been disclosed publicly and may be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8292', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8291', 'NVD', '2026-05-11 16:17:43', '2026-05-14 18:19:11', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8291', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A weakness has been identified in Open5GS up to 2.7.7. Impacted is the function ogs_nnrf_nfm_handle_nf_profile of the file lib/sbi/nnrf-handler.c of the component NRF. This manipulation causes denial of service. The attack is possible to be carried out remotely. The exploit has been made available to the public and could be used for attacks. The pull request to fix this issue awaits acceptance.', 'CVE-2026-8291', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8290', 'NVD', '2026-05-11 14:16:34', '2026-05-13 16:11:05', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8290', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A security flaw has been discovered in Open5GS up to 2.7.7. This issue affects the function smf_nsmf_handle_update_data_in_vsmf of the file /src/smf/nsmf-handler.c of the component SMF. The manipulation results in denial of service. The attack can be executed remotely. The exploit has been released to the public and may be used for attacks. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8290', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8289', 'NVD', '2026-05-11 14:16:34', '2026-05-12 17:18:09', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8289', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability was identified in Open5GS up to 2.7.7. This vulnerability affects the function smf_nsmf_handle_update_data_in_vsmf of the file /src/smf/nsmf-handler.c of the component SMF. The manipulation of the argument qosFlowProfile leads to denial of service. Remote exploitation of the attack is possible. The exploit is publicly available and might be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8289', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8288', 'NVD', '2026-05-11 13:16:12', '2026-05-12 17:18:17', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8288', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability was determined in Open5GS up to 2.7.7. This affects the function gsm_handle_pdu_session_modification_qos_flow_descriptions of the file src/smf/gsm-handler.c of the component SMF. Executing a manipulation of the argument n1SmMsg can lead to denial of service. The attack may be launched remotely. The exploit has been publicly disclosed and may be utilized. The pull request to fix this issue awaits acceptance.', 'CVE-2026-8288', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8270', 'NVD', '2026-05-11 05:16:15', '2026-05-12 17:19:37', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8270', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability was determined in Open5GS up to 2.7.7. The affected element is the function ogs_nas_parse_qos_rules of the component SMF. Executing a manipulation can lead to denial of service. The attack can be executed remotely. The exploit has been publicly disclosed and may be utilized. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8270', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8269', 'NVD', '2026-05-11 05:16:15', '2026-05-12 17:20:15', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8269', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability was found in Open5GS up to 2.7.7. Impacted is the function smf_nsmf_handle_create_sm_context of the component SMF. Performing a manipulation results in denial of service. Remote exploitation of the attack is possible. The exploit has been made public and could be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8269', null);
