INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8257', 'NVD', '2026-05-11 02:16:27', '2026-05-21 17:59:57', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8257', '["cpe:2.3:a:webassembly:binaryen:*:*:*:*:*:*:*:*"]', 1.9, 3.3, 1.7, 'LOW', null, '["CWE-617"]', 'A vulnerability was detected in WebAssembly Binaryen up to 117. This issue affects the function IRBuilder::makeBrOn of the file src/wasm/wasm-ir-builder.cpp of the component BrOn Parser. Performing a manipulation results in reachable assertion. The attack needs to be approached locally. The exploit is now public and may be used. The patch is named 1251efbc1ea471c1311d2726b2bbe061ff2a291c. It is suggested to install a patch to address this issue.', 'CVE-2026-8257', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8252', 'NVD', '2026-05-11 00:16:33', '2026-05-12 17:34:50', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8252', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404", "CWE-476"]', 'A vulnerability was determined in Open5GS up to 2.7.7. Affected is the function smf_nsmf_handle_create_data_in_hsmf of the component SMF. Executing a manipulation can lead to null pointer dereference. The attack may be performed from remote. The exploit has been publicly disclosed and may be utilized. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8252', null);
