INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8249', 'NVD', '2026-05-10 23:16:27', '2026-05-13 16:10:49', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8249', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A flaw has been found in Open5GS up to 2.7.7. The impacted element is the function update_authorized_pcc_rule_and_qos of the file /src/smf/npcf-handler.c of the component SMF. This manipulation causes denial of service. Remote exploitation of the attack is possible. The exploit has been published and may be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8249', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8248', 'NVD', '2026-05-10 23:16:27', '2026-05-12 17:35:25', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8248', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability was detected in Open5GS up to 2.7.7. The affected element is the function update_authorized_pcc_rule_and_qos of the file /src/smf/npcf-handler.c of the component SMF. The manipulation results in denial of service. The attack may be launched remotely. The exploit is now public and may be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8248', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8245', 'NVD', '2026-05-21 22:16:50', '2026-05-26 17:19:42', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8245', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 6, 5.4, null, 'MEDIUM', null, '["CWE-83"]', 'Concrete CMS 9.5.0 and below is vulnerable to Reflected XSS in Legacy Pagination via HTML attribute injection. Concrete\\Core\\Legacy\\Pagination builds pagination links by raw-interpolating its $URL field into href="" (<a href="{$linkURL}" …>). Any authenticated admin or report viewer with access to `/dashboard/reports/forms/legacy` who clicks the crafted URL fires the payload in their session. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 6.0 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:P/VC:H/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Yonatan Drori (Tenzai) for reporting', 'CVE-2026-8245', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8240', 'NVD', '2026-05-21 22:16:50', '2026-05-26 17:24:12', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8240', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 6.3, 5.3, null, 'MEDIUM', null, '["CWE-284"]', 'Concrete CMS 9.5.0 and below is vulnerable to unauthenticated page metadata disclosure across every page with a configured summary template, revealing the existence of private, draft, and restricted pages while leaking title, path, description, and author information. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 6.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:N/VC:L/VI:N/VA:N/SC:N/SI:N/SA:N. Thanks Winston Crooker for reporting.', 'CVE-2026-8240', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8239', 'NVD', '2026-05-21 22:16:50', '2026-05-26 17:25:49', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8239', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 6.3, 5.3, null, 'MEDIUM', null, '["CWE-862"]', 'Concrete CMS 9.5.0 and below is vulnerable to IDOR. The \'/ccm/frontend/conversations/get_rating\' endpoint confirms existence and returns rating score for any message by ID. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 6.3 with Vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:N/VC:L/VI:N/VA:N/SC:N/SI:N/SA:N. Thanks Tristan Madani for reporting.', 'CVE-2026-8239', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8238', 'NVD', '2026-05-21 22:16:49', '2026-05-26 17:29:23', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8238', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 6.3, 5.3, null, 'MEDIUM', null, '["CWE-862"]', 'Concrete CMS 9.5.0 and below is vulnerable to IDOR. The \'/ccm/frontend/conversations/message_page\' endpoint returns the full content of any conversation message. An unauthenticated attacker can enumerate all conversation messages, including messages from restricted pages, member-only areas, and the moderation queue. File attachments with download URLs are also exposed. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 6.3 with Vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:N/VC:L/VI:N/VA:N/SC:N/SI:N/SA:N. Thanks Tristan Madani for reporting.', 'CVE-2026-8238', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8237', 'NVD', '2026-05-21 22:16:49', '2026-05-26 17:34:33', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8237', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 6.3, 5.3, null, 'MEDIUM', null, '["CWE-862"]', 'Concrete CMS 9.5.0 and below is vulnerable to IDOR. The `/ccm/frontend/conversations/message_detail` endpoint returns the full content of any conversation message. An unauthenticated attacker can enumerate all conversation messages, including messages from restricted pages, member-only areas, and the moderation queue. File attachments with download URLs are also exposed. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 6.3 with Vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:N/VC:L/VI:N/VA:N/SC:N/SI:N/SA:N. Thanks Eldudareeno for reporting.', 'CVE-2026-8237', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8236', 'NVD', '2026-05-21 22:16:49', '2026-05-26 17:37:28', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8236', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 6.3, 4.3, null, 'MEDIUM', null, '["CWE-862"]', 'Concrete CMS 9.5.0 and below is vulnerable to IDOR combined with a missing authentication gate. The endpoint /ccm/system/dialogs/file/usage/{fID} accepts an integer file ID in the URL and returns internal site structure data (page IDs, versions, URL paths) to anyone who sends a GET request. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 6.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:N/VC:L/VI:N/VA:N/SC:N/SI:N/SA:N. Thanks Winston Crooker for reporting.', 'CVE-2026-8236', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8226', 'NVD', '2026-05-10 05:16:12', '2026-05-12 17:38:05', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8226', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 5.5, 5.3, 5, 'MEDIUM', null, '["CWE-404"]', 'A security flaw has been discovered in Open5GS up to 2.7.7. This vulnerability affects the function ogs_pcc_rule_install_flow_from_media in the library /lib/proto/types.c. The manipulation results in denial of service. The attack can be launched remotely. The exploit has been released to the public and may be used for attacks. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8226', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8225', 'NVD', '2026-05-10 05:16:12', '2026-05-12 17:38:16', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8225', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 5.5, 5.3, 5, 'MEDIUM', null, '["CWE-404"]', 'A vulnerability was identified in Open5GS up to 2.7.7. This affects the function pcf_npcf_smpolicycontrol_handle_delete of the file src/pcf/sm-sm.c of the component delete Endpoint. The manipulation leads to denial of service. The attack can be initiated remotely. The exploit is publicly available and might be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8225', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8224', 'NVD', '2026-05-10 03:16:09', '2026-05-12 17:48:59', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8224', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 5.5, 5.3, 5, 'MEDIUM', null, '["CWE-404"]', 'A vulnerability was determined in Open5GS up to 2.7.7. Affected by this issue is the function pcf_sess_set_ipv6prefix of the file /src/pcf/context.c of the component PCF. Executing a manipulation of the argument SmPolicyContextData.ipv6AddressPrefix can lead to denial of service. It is possible to launch the attack remotely. The exploit has been publicly disclosed and may be utilized. The vendor was contacted early about this disclosure but did not respond in any way.', 'CVE-2026-8224', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8223', 'NVD', '2026-05-10 03:16:08', '2026-05-13 16:10:25', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8223', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 5.5, 5.3, 5, 'MEDIUM', null, '["CWE-404"]', 'A vulnerability was found in Open5GS up to 2.7.7. Affected by this vulnerability is the function pcf_sess_sbi_discover_and_send of the component sm-policies Endpoint. Performing a manipulation results in denial of service. It is possible to initiate the attack remotely. The exploit has been made public and could be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8223', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8222', 'NVD', '2026-05-10 03:16:08', '2026-05-12 17:49:04', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8222', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 5.5, 5.3, 5, 'MEDIUM', null, '["CWE-404"]', 'A vulnerability has been found in Open5GS up to 2.7.7. Affected is the function pcf_nbsf_management_handle_register of the file src/pcf/nbsf-handler.c of the component sm-policies Endpoint. Such manipulation leads to denial of service. The attack may be performed from remote. The exploit has been disclosed to the public and may be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8222', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8205', 'NVD', '2026-05-21 21:16:33', '2026-05-26 17:43:47', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8205', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 6.3, 5.3, null, 'MEDIUM', null, '["CWE-425"]', 'Concrete CMS 9.5.0 and below is vulnerable to authorization bypass in the Calendar Block since action_get_events does not check canView on the calendar which results in restricted event details being disclosed. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 6.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:N/VC:L/VI:N/VA:N/SC:N/SI:N/SA:N. Thanks lalalala5678 for reporting.', 'CVE-2026-8205', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8204', 'NVD', '2026-05-21 21:16:33', '2026-05-26 14:58:25', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8204', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 6.3, 5.3, null, 'MEDIUM', null, '["CWE-639"]', 'Concrete CMS 9.5.0 and below is vulnerable to authorization Bypass in the Calendar Event Frontend Dialog which can allow cross-calendar data disclosure. A public calendar block can be used as a pivot point to access private calendar data. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 6.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:N/VC:L/VI:N/VA:N/SC:N/SI:N/SA:N. Thanks Winston Crooker for reporting.', 'CVE-2026-8204', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8203', 'NVD', '2026-05-21 21:16:33', '2026-05-26 18:33:25', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8203', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 7.3, 5.4, null, 'HIGH', null, '["CWE-79"]', 'Concrete CMS 9.5.0 and below has Stored XSS on the height parameter. The controller does not validate or sanitize $height. Any user with editor privileges can inject malicious JavaScript that executes in the context of any visitor\'s browser, potentially leading to session hijacking, credential theft, or other malicious actions. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 7.3 with vector CVSS:4.0/AV:N/AC:H/AT:P/PR:H/UI:P/VC:H/VI:H/VA:H/SC:N/SI:N/SA:N. Thanks Alfin Joseph for reporting.', 'CVE-2026-8203', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8202', 'NVD', '2026-05-13 04:17:42', '2026-05-18 12:55:24', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8202', '["cpe:2.3:a:mongodb:mongodb:*:*:*:*:*:*:*:*"]', 5.3, 4.3, null, 'MEDIUM', null, '["CWE-770"]', 'Using a densely populated chars mask and a large input string in the MongoDB aggregation operators $trim, $ltrim, and $rtrim, an authenticated user with aggregation permissions can pin CPU utilization at 100% for an extended period of time.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8201', 'NVD', '2026-05-13 04:17:41', '2026-05-13 22:50:59', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8201', '["cpe:2.3:a:mongodb:mongodb:*:*:*:*:*:*:*:*"]', 6.1, 6.4, null, 'MEDIUM', null, '["CWE-416"]', 'A use-after-free vulnerability exists in MongoDB\'s Field-Level Encryption (FLE) query analysis component, affecting client-side uses of mongocryptd and crypt_shared. Triggering this vulnerability requires control over the structure of a client\'s FLE-related query.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8200', 'NVD', '2026-05-13 04:17:41', '2026-05-18 13:01:44', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8200', '["cpe:2.3:a:mongodb:mongodb:*:*:*:*:*:*:*:*"]', 4.8, 2.7, null, 'MEDIUM', null, '["CWE-532"]', 'When schema validation is enabled on a collection and an update or insert would violate the collection\'s schema, the local server log message generated may not have all user data redacted. 
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8199', 'NVD', '2026-05-13 04:17:41', '2026-05-13 22:31:09', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8199', '["cpe:2.3:a:mongodb:mongodb:*:*:*:*:*:*:*:*"]', 7.1, 6.5, null, 'HIGH', null, '["CWE-1325"]', 'An authenticated user can cause excess memory usage via bitwise match expression AST processing of $bitsAllSet, $bitsAnySet, $bitsAllClear, and $bitsAnyClear. This contributes to memory pressure and may lead to availability loss by OOM.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8197', 'NVD', '2026-05-21 21:16:33', '2026-05-26 18:34:40', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8197', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 7.3, 4.8, null, 'HIGH', null, '["CWE-79"]', 'Concrete CMS 9.5.0 and below is vulnerable to Stored XSS via OAuth integration name. The OAuth authorize template renders the integration name (admin-controlled) through Concrete\'s t() translation helper as a sprintf-style format. The <strong>...</strong> wrap is built by PHP string interpolation before t() runs, so the integration name lands in the translated output as raw HTML. A rogue admin could potentially snoop on login submissions.The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 7.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:H/UI:P/VC:H/VI:H/VA:H/SC:N/SI:N/SA:N  Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8197', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8187', 'NVD', '2026-05-09 11:16:28', '2026-05-13 16:08:09', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8187', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 6.9, 5.3, 5, 'MEDIUM', null, '["CWE-400", "CWE-404"]', 'A flaw has been found in Open5GS up to 2.7.7. This impacts the function _gtpv1_u_recv_cb of the file src/upf/gtp-path.c of the component UPF. Executing a manipulation can lead to resource consumption. The attack may be performed from remote. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8187', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8186', 'NVD', '2026-05-09 12:16:08', '2026-05-13 16:09:17', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8186', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 6.9, 5.3, 5, 'MEDIUM', null, '["CWE-119", "CWE-125"]', 'A vulnerability was detected in Open5GS up to 2.7.7. This affects the function ogs_sbi_client_send_via_scp_or_sepp in the library lib/sbi/client.c of the component NF. Performing a manipulation results in out-of-bounds read. The attack is possible to be carried out remotely. The patch is named d5bc487fcf9ea87d2b03f2ef95123af344773bfb. It is suggested to install a patch to address this issue.', 'CVE-2026-8186', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8180', 'NVD', '2026-05-27 14:17:38', '2026-06-05 18:56:59', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8180', '["cpe:2.3:a:ibm:aspera_high-speed_transfer_endpoint:*:*:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_endpoint:4.4.7:-:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_endpoint:4.4.7:fixpack1:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_server:4.4.7:-:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_server:4.4.7:fixpack1:*:*:*:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-476"]', 'IBM Aspera High-Speed Transfer Endpoint 3.7.4 through 4.4.7 Fix Pack 1 and IBM Aspera High-Speed Transfer Server 3.7.4 through 4.4.7 Fix Pack 1 and IBM Aspera High-Speed Transfer Endpoint are affected by a potential denial of service in the asperahttpd component. An unauthenticated user can cause the asperahttpd service to crash.', 'CVE-2026-8180', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8179', 'NVD', '2026-05-27 14:17:36', '2026-06-05 18:57:03', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8179', '["cpe:2.3:a:ibm:aspera_high-speed_transfer_endpoint:*:*:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_endpoint:4.4.7:-:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_endpoint:4.4.7:fixpack1:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_server:4.4.7:-:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_server:4.4.7:fixpack1:*:*:*:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-121"]', 'IBM Aspera High-Speed Transfer Endpoint 3.7.4 through 4.4.7 Fix Pack 1 and IBM Aspera High-Speed Transfer Server 3.7.4 through 4.4.7 Fix Pack 1 and IBM Aspera High-Speed Transfer Endpoint are affected by a buffer overflow in the asperahttpd component. This vulnerability could allow an authenticated user to execute arbitrary code on the system.', 'CVE-2026-8179', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8175', 'NVD', '2026-05-27 14:17:35', '2026-06-05 18:57:06', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8175', '["cpe:2.3:a:ibm:aspera_high-speed_transfer_endpoint:*:*:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_endpoint:4.4.7:-:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_endpoint:4.4.7:fixpack1:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_server:4.4.7:-:*:*:*:*:*:*", "cpe:2.3:a:ibm:aspera_high-speed_transfer_server:4.4.7:fixpack1:*:*:*:*:*:*"]', null, 9.8, null, 'CRITICAL', null, '["CWE-122"]', 'IBM Aspera High-Speed Transfer Endpoint 3.7.4 through 4.4.7 Fix Pack 1 and IBM Aspera High-Speed Transfer Server 3.7.4 through 4.4.7 Fix Pack 1 and IBM Aspera High-Speed Transfer Endpoint are affected by a buffer overflow in the asperahttpd component. This vulnerability could be exploited to cause a denial of service and potentially lead to authentication bypass or remote code execution.', 'CVE-2026-8175', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8140', 'NVD', '2026-05-21 21:16:33', '2026-05-26 18:43:21', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8140', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 7.5, 6.5, null, 'HIGH', null, '["CWE-352"]', 'Concrete CMS 9.5.0 and below does not validate a CSRF token before processing requests to /dashboard/extend/install/download/<remoteId>. The download() method in concrete/controllers/single_page/dashboard/extend/install.php checks only the canInstallPackages() permission before fetching a remote marketplace package and writing it to the server\'s DIR_PACKAGES directory. Because the endpoint is a state-changing GET route with no token enforcement, an attacker who can cause an authenticated administrator to visit a crafted page can force an arbitrary marketplace package to be downloaded. In order to be vulnerable, the victim must be passing canInstallPackages() and the site must be connected to the Concrete marketplace. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 7.5 with vector CVSS:4.0/AV:N/AC:H/AT:P/PR:N/UI:A/VC:H/VI:H/VA:H/SC:N/SI:N/SA:N. Thanks  https://github.com/maru1009  for reporting.', 'CVE-2026-8140', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8139', 'NVD', '2026-05-21 22:16:49', '2026-05-26 17:41:14', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8139', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2, 5.4, null, 'LOW', null, '["CWE-79"]', 'Concrete CMS 9.5.0 and below is vulnerable to Stored XSS via external-link page cvName because updateCollectionAliasExternal bypasses being sanitized. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.0 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:H/UI:P/VC:L/VI:L/VA:N/SC:N/SI:N/SA:N.  Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8139', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8135', 'NVD', '2026-05-21 21:16:32', '2026-05-26 18:44:04', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8135', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 8.9, 7.2, null, 'HIGH', null, '["CWE-502"]', 'Concrete CMS 9.5.0 and below is vulnerable to Remote Code Execution  due to insecure deserialization occurring in the ExpressEntryList block controller. An rogue administrator with privileges to add blocks to an area can bypass the intended protection mechanism (_fromCIF === true), which normally restricts malicious inputs over form POST requests, by leveraging the REST API functionality. Because the REST API parses requests using json_decode(), the string "true" is evaluated as a strict PHP Boolean(true).  This bypass allows the attacker to inject a malicious serialized payload  into the block\'s filterFields database column. The payload will subsequently be executed when the block\'s data is viewed or edited by an administrator leading to complete server takeover (RCE).The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 8.9 with a vector of CVSS:4.0/AV:N/AC:H/AT:P/PR:H/UI:N/VC:H/VI:H/VA:H/SC:H/SI:H/SA:H.  Thanks  Nguyễn Văn Thiện https://github.com/Thien225409  for reporting', 'CVE-2026-8135', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8134', 'NVD', '2026-05-21 21:16:32', '2026-05-26 19:02:40', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8134', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 9.4, 7.2, null, 'CRITICAL', null, '["CWE-23", "CWE-98", "CWE-434"]', 'Concrete CMS 9.5.0 and below fails to sanitize path traversal sequences in the ptComposerFormLayoutSetControlCustomTemplate field when saving page type composer form layouts. An authenticated rogue administrator with composer form editing rights can exploit this to include arbitrary readable files on the server. Combined with the file uploader\'s extension-only validation (which permits PHP code in files saved with image extensions like .png), this can result in authenticated remote code execution. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 9.4 with vector CVSS:4.0/AV:N/AC:L/AT:N/PR:H/UI:N/VC:H/VI:H/VA:H/SC:H/SI:H/SA:H   Thanks Yonatan Drori (Tenzai) for reporting.', 'CVE-2026-8134', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8123', 'NVD', '2026-05-08 02:16:07', '2026-05-11 13:39:21', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8123', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability was determined in Open5GS up to 2.7.7. This impacts the function ogs_sbi_discovery_option_add_snssais in the library /lib/sbi/message.c of the component NSSF. This manipulation causes denial of service. It is possible to initiate the attack remotely. The exploit has been publicly disclosed and may be utilized. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8123', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8122', 'NVD', '2026-05-08 01:16:10', '2026-05-11 14:00:25', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8122', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability was found in Open5GS up to 2.7.7. This affects the function ogs_sbi_discovery_option_add_service_names in the library /lib/sbi/message.c of the component NSSF. The manipulation results in denial of service. The attack may be performed from remote. The exploit has been made public and could be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8122', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8121', 'NVD', '2026-05-08 01:16:09', '2026-05-11 14:26:39', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8121', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability has been found in Open5GS up to 2.7.7. The impacted element is the function ogs_sbi_parse_plmn_list in the library /lib/sbi/conv.c of the component NSSF. The manipulation leads to denial of service. The attack is possible to be carried out remotely. The exploit has been disclosed to the public and may be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8121', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8120', 'NVD', '2026-05-08 01:16:09', '2026-05-11 14:28:27', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8120', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A flaw has been found in Open5GS up to 2.7.7. The affected element is the function nssf_nnrf_nsselection_handle_get_from_amf_or_vnssf of the file /src/nssf/nnssf-handler.c of the component NSSF. Executing a manipulation can lead to denial of service. The attack can be executed remotely. The exploit has been published and may be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8120', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8119', 'NVD', '2026-05-08 01:16:08', '2026-05-11 14:29:35', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8119', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 1.9, 3.3, 1.7, 'LOW', null, '["CWE-404"]', 'A vulnerability was detected in Open5GS up to 2.7.7. Impacted is the function ogs_sbi_stream_find_by_id in the library /lib/sbi/nghttp2-server.c of the component NSSF. Performing a manipulation results in denial of service. Attacking locally is a requirement. The exploit is now public and may be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-8119', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8111', 'NVD', '2026-05-12 15:16:18', '2026-05-12 19:17:48', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8111', '["cpe:2.3:a:ivanti:endpoint_manager:*:*:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:-:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su1:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su2:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su3:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su3_security_release_1:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su4:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su4_security_release_1:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su5:*:*:*:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-89"]', 'SQL injection in the web console of Ivanti Endpoint Manager before version 2024 SU6 allows a remote authenticated attacker to achieve remote code execution.', 'CVE-2026-8111', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8110', 'NVD', '2026-05-12 15:16:17', '2026-05-12 19:18:08', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8110', '["cpe:2.3:a:ivanti:endpoint_manager:*:*:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:-:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su1:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su2:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su3:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su3_security_release_1:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su4:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su4_security_release_1:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su5:*:*:*:*:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-732"]', 'Incorrect permissions assignment in the agent of Ivanti Endpoint Manager before version 2024 SU6 allows a local authenticated attacker to escalate their privileges.', 'CVE-2026-8110', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8109', 'NVD', '2026-05-12 15:16:17', '2026-05-12 19:18:29', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8109', '["cpe:2.3:a:ivanti:endpoint_manager:*:*:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:-:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su1:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su2:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su3:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su3_security_release_1:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su4:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su4_security_release_1:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager:2024:su5:*:*:*:*:*:*"]', null, 6.5, null, 'MEDIUM', null, '["CWE-749"]', 'An exposed dangerous method on the Core Server of Ivanti Endpoint Manager before version 2024 SU6 allows a remote authenticated attacker to leak access credentials.', 'CVE-2026-8109', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8106', 'NVD', '2026-05-07 22:16:37', '2026-05-11 17:12:47', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8106', '["cpe:2.3:a:github:enterprise_server:*:*:*:*:*:*:*:*"]', 5.9, 6.1, null, 'MEDIUM', null, '["CWE-79"]', 'A reflected HTML injection vulnerability was identified in the GitHub Enterprise Server Management Console login page that could allow credential theft. The redirect_to query parameter on the /setup/unlock endpoint was reflected into an HTML attribute without proper sanitization, enabling an attacker to inject a form element that could capture administrator credentials. Exploitation required an administrator to click a crafted link and enter their credentials. This vulnerability affected GitHub Enterprise Server versions 3.19.1 through 3.19.5 and 3.20.0 through 3.20.1, and was fixed in versions 3.19.6 and 3.20.2. This vulnerability was reported via the GitHub Bug Bounty program.', 'CVE-2026-8106', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8094', 'NVD', '2026-05-07 13:16:14', '2026-05-11 15:12:23', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8094', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:esr:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:*:*:*:*"]', null, 9.8, null, 'CRITICAL', null, '["CWE-94"]', 'Other issue in the WebRTC component. This vulnerability was fixed in Firefox ESR 140.10.2 and Thunderbird 140.10.2.', 'CVE-2026-8094', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8093', 'NVD', '2026-05-07 13:16:14', '2026-05-18 08:16:15', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8093', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:*:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:*:*:*:*"]', null, 8.1, null, 'HIGH', null, '["CWE-119"]', 'Memory safety bugs present in Firefox 150.0.1. Some of these bugs showed evidence of memory corruption and we presume that with enough effort some of these could have been exploited to run arbitrary code. This vulnerability was fixed in Firefox 150.0.2 and Thunderbird 150.0.2.', 'CVE-2026-8093', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8092', 'NVD', '2026-05-07 13:16:14', '2026-05-18 08:16:14', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8092', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:firefox:*:*:*:*:esr:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:-:*:*:*"]', null, 8.1, null, 'HIGH', null, '["CWE-125", "CWE-416", "CWE-787"]', 'Memory safety bugs present in Firefox ESR 115.35.1, Firefox ESR 140.10.1 and Firefox 150.0.1. Some of these bugs showed evidence of memory corruption and we presume that with enough effort some of these could have been exploited to run arbitrary code. This vulnerability was fixed in Firefox 150.0.2, Firefox ESR 140.10.2, Firefox ESR 115.35.2, Thunderbird 150.0.2, and Thunderbird 140.10.2.', 'CVE-2026-8092', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8091', 'NVD', '2026-05-07 13:16:14', '2026-05-11 15:20:21', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8091', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:esr:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:-:*:*:*"]', null, 9.8, null, 'CRITICAL', null, '["CWE-754"]', 'Incorrect boundary conditions in the Audio/Video: Playback component. This vulnerability was fixed in Firefox 150, Thunderbird 150, Firefox ESR 140.10.1, Thunderbird 140.10.1, and Firefox ESR 115.35.2.', 'CVE-2026-8091', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8090', 'NVD', '2026-05-07 13:16:13', '2026-05-08 20:08:50', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8090', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:firefox:*:*:*:*:esr:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:esr:*:*:*"]', null, 7.3, null, 'HIGH', null, '["CWE-416"]', 'Use-after-free in the DOM: Networking component. This vulnerability was fixed in Firefox 150.0.2, Firefox ESR 140.10.2, Firefox ESR 115.35.2, Thunderbird 150.0.2, and Thunderbird 140.10.2.', 'CVE-2026-8090', null);
