.3:a:checkmk:checkmk:2.5.0:b2:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:b3:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p1:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p2:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p3:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p4:*:*:*:*:*:*"]', 4.8, 4.8, null, 'MEDIUM', null, '["CWE-79"]', 'Stored cross-site scripting in the global settings change log in Checkmk <2.5.0p5, <2.4.0p31, <2.3.0p48, and all 2.2.0 versions allows an administrator who can change global settings to store malicious HTML or JavaScript in changelog messages that executes in other users\' browsers when they view the Activate Changes page or Audit log.', 'CVE-2026-8078', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8063', 'NVD', '2026-05-07 06:16:05', '2026-05-11 15:26:42', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8063', '["cpe:2.3:a:mongodb:mongodb:*:*:*:*:-:*:*:*"]', 7.1, 6.5, null, 'HIGH', null, '["CWE-476"]', 'An authenticated user can crash mongod when running $rankFusion or $scoreFusion with an empty pipeline on a view.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8053', 'NVD', '2026-05-13 04:17:41', '2026-05-18 13:06:01', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8053', '["cpe:2.3:a:mongodb:mongodb:*:*:*:*:*:*:*:*"]', 8.7, 8.8, null, 'HIGH', null, '["CWE-787"]', 'An issue in MongoDB Server\'s time-series collection implementation allows an authenticated user with database write privileges to trigger an out-of-bounds memory write in the mongod process. The issue results from an inconsistency in the internal field-name-to-index mapping within the time-series bucket catalog. Under certain conditions this can result in arbitrary code execution.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8036', 'NVD', '2026-06-02 20:16:41', '2026-06-05 15:10:35', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8036', '["cpe:2.3:a:ni:ni-pal:*:*:*:*:*:*:*:*"]', 8.4, 7.1, null, 'HIGH', null, '["CWE-1285"]', 'Improper input validation in NI-PAL may allow a local authenticated user to access arbitrary system memory, potentially leading to privilege escalation. This vulnerability affects NI-PAL 26.3.0 and prior versions on Windows and Linux.', 'CVE-2026-8036', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8035', 'NVD', '2026-06-02 20:16:41', '2026-06-05 15:11:30', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8035', '["cpe:2.3:a:ni:ni-pal:*:*:*:*:*:*:*:*"]', 6.9, 7.1, null, 'MEDIUM', null, '["CWE-476"]', 'Improper input validation in the NI-PAL kernel driver may allow a local authenticated user to cause a denial of service by triggering a crash due to a NULL pointer dereference. This vulnerability affects NI-PAL 26.3.0 and prior versions on Windows and Linux.', 'CVE-2026-8035', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8034', 'NVD', '2026-05-07 22:16:37', '2026-05-11 17:18:27', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8034', '["cpe:2.3:a:github:enterprise_server:*:*:*:*:*:*:*:*"]', 7.9, 9.8, null, 'HIGH', null, '["CWE-436", "CWE-918"]', 'A server-side request forgery (SSRF) vulnerability was identified in the GitHub Enterprise Server notebook viewer that allowed an attacker to access internal services by exploiting URL parser confusion between the validation layer and the HTTP request library. The hostname validation used a different URL parser than the request library, enabling a crafted URL to pass validation while directing the request to an unintended host. Exploitation required network access to the GitHub Enterprise Server instance. This vulnerability affected all versions of GitHub Enterprise Server prior to 3.21 and was fixed in versions 3.16.18, 3.17.15, 3.18.9, 3.19.6, and 3.20.2. This vulnerability was reported via the GitHub Bug Bounty program.', 'CVE-2026-8034', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8022', 'NVD', '2026-05-06 19:16:53', '2026-05-07 15:15:31', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8022', '["cpe:2.3:a:google:chrome:*:*:*:*:*:*:*:*"]', null, 3.1, null, 'LOW', null, '["CWE-352", "CWE-1021"]', 'Inappropriate implementation in MHTML in Google Chrome prior to 148.0.7778.96 allowed a remote attacker who convinced a user to engage in specific UI gestures to leak cross-origin data via a crafted MHTML page. (Chromium security severity: Low)', 'CVE-2026-8022', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-8021', 'NVD', '2026-05-06 19:16:53', '2026-05-07 15:18:04', 'https://nvd.nist.gov/vuln/detail/CVE-2026-8021', '["cpe:2.3:a:google:chrome:*:*:*:*:*:*:*:*"]', null, 4.2, null, 'MEDIUM', null, '["CWE-94"]', 'Script injection in UI in Google Chrome prior to 148.0.7778.96 allowed a remote attacker who convinced a user to engage in specific UI gestures to inject arbitrary scripts or HTML (UXSS) via a crafted HTML page. (Chromium security severity: Low)', 'CVE-2026-8021', null);
