INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7899', 'NVD', '2026-05-06 19:16:38', '2026-05-06 23:42:56', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7899', '["cpe:2.3:a:google:chrome:*:*:*:*:*:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-125", "CWE-787"]', 'Out of bounds read and write in V8 in Google Chrome prior to 148.0.7778.96 allowed a remote attacker to execute arbitrary code inside a sandbox via a crafted HTML page. (Chromium security severity: High)', 'CVE-2026-7899', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7898', 'NVD', '2026-05-06 19:16:38', '2026-05-06 23:43:09', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7898', '["cpe:2.3:a:google:chrome:*:*:*:*:*:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-416"]', 'Use after free in Chromoting in Google Chrome on Linux prior to 148.0.7778.96 allowed a remote attacker to execute arbitrary code via malicious network traffic. (Chromium security severity: Critical)', 'CVE-2026-7898', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7897', 'NVD', '2026-05-06 19:16:37', '2026-05-06 23:43:15', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7897', '["cpe:2.3:a:google:chrome:*:*:*:*:*:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-416"]', 'Use after free in Mobile in Google Chrome on iOS prior to 148.0.7778.96 allowed a remote attacker who convinced a user to engage in specific UI gestures to execute arbitrary code via a crafted HTML page. (Chromium security severity: Critical)', 'CVE-2026-7897', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7896', 'NVD', '2026-05-06 19:16:37', '2026-05-06 23:43:25', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7896', '["cpe:2.3:a:google:chrome:*:*:*:*:*:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-472"]', 'Integer overflow in Blink in Google Chrome prior to 148.0.7778.96 allowed a remote attacker to potentially exploit heap corruption via a crafted HTML page. (Chromium security severity: Critical)', 'CVE-2026-7896', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7890', 'NVD', '2026-05-21 22:16:49', '2026-05-22 19:12:07', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7890', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.1, 6.4, null, 'LOW', null, '["CWE-918"]', 'In Concrete CMS 9.5.0 and below, the RSS Displayer block accepts a feed URL from any page editor and fetches it server-side without validation enabling redirect-to-internal bypasses.  The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.1 with a vector CVSS:4.0/AV:N/AC:L/AT:P/PR:H/UI:N/VC:N/VI:L/VA:N/SC:L/SI:N/SA:N.', 'CVE-2026-7890', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7887', 'NVD', '2026-05-21 22:16:49', '2026-05-22 19:21:08', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7887', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 6.4, null, 'LOW', null, '["CWE-1287"]', 'For Concrete CMS 9.5.0 and below, OAuth 2.0 Authorization-Code Handler Bypasses Account Status. A user with uIsActive=0 (suspended, banned, terminated employee) can still authenticate via OAuth and receive valid API tokens. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:L/UI:N/VC:L/VI:L/VA:N/SC:L/SI:L/SA:N. Thanks 0x4c616e for reporting.', 'CVE-2026-7887', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7886', 'NVD', '2026-05-21 22:16:49', '2026-05-22 19:19:54', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7886', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 4.3, null, 'LOW', null, '["CWE-639"]', 'Concrete CMS 9.5.0 and below is vulnerable to IDOR in AddMessage/UpdateMessage via attachments[] parameter which can lead to file permission bypass. The `AddMessage` and `UpdateMessage` conversation controllers accept user-supplied file attachment IDs and load files directly via `$em->find(File::class, $attachmentID)` without checking per-file permissions (`canViewFile()`). A user who can post in any conversation can reference any file in the CMS file manager by its sequential ID, effectively bypassing the file permission system.  The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with a vector CVSS:4.0/AV:N/AC:L/AT:P/PR:L/UI:N/VC:L/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Tristan Mandani for reporting. if a site truly has private files, the owner should set up a  private storage location https://documentation.concretecms.org/user-guide/editors-reference/dashboard/system-and-maintenance/files/file-storage-locations  outside of the webroot so that permissions can be checked on view as well. That way, even if a authorized user attaches a file, or otherwise links to it, unauthorized users won\'t be able to view the file.', 'CVE-2026-7886', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7882', 'NVD', '2026-05-21 22:16:49', '2026-05-26 14:56:43', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7882', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 2.3, 4.3, null, 'LOW', null, '["CWE-352"]', 'Concrete CMS  9.5.0 and below is vulnerable to unauthorized file deletion due to an Inverted CSRF token check in the DeleteFile controller. The code throws an error when the token IS valid and proceeds with file deletion when the token is invalid or missing. This effectively disables CSRF protection for the file deletion endpoint, allowing cross-site request forgery attacks against users who have permission to edit conversation messages. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 2.3 with a vector of CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:P/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N. Thanks Tristan Mandani for reporting.', 'CVE-2026-7882', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7881', 'NVD', '2026-05-21 22:16:48', '2026-05-22 19:19:28', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7881', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 6.3, 4.3, null, 'MEDIUM', null, '["CWE-639"]', 'Concrete CMS 9.5.0 and below is subject to Insecure Direct Object Reference (IDOR) in the Express Entry Detail block via the exEntryID parameter. This IDOR leads to unauthorized access to all Express form submissions. The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 6.3 with vector CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:N/VC:L/VI:N/VA:N/SC:N/SI:N/SA:N. Thanks Tristan Madani for reporting.', 'CVE-2026-7881', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7879', 'NVD', '2026-05-21 22:16:48', '2026-05-22 19:18:46', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7879', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 6.3, 5.3, null, 'MEDIUM', null, '["CWE-862"]', 'In Concrete CMS 9.5.0 and below,  the submit_password() method in concrete/controllers/single_page/download_file.php allows unauthorized file access since downloading
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7876', 'NVD', '2026-05-27 14:17:35', '2026-05-29 21:25:29', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7876', '["cpe:2.3:a:ibm:aspera_high-speed_transfer_server_for_cloud_pak_for_integration:*:*:*:*:*:*:*:*"]', null, 9.1, null, 'CRITICAL', null, '["CWE-287"]', 'IBM Aspera HSTS for CP4I 1.5.1 through 1.5.19', 'CVE-2026-7876', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7821', 'NVD', '2026-05-07 16:16:23', '2026-05-07 20:09:25', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7821', '["cpe:2.3:a:ivanti:endpoint_manager_mobile:*:*:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager_mobile:12.7.0.0:*:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager_mobile:12.8.0.0:*:*:*:*:*:*:*"]', null, 7.4, null, 'HIGH', null, '["CWE-295"]', 'Improper certificate validation in Ivanti EPMM before versions 12.6.1.1, 12.7.0.1, and 12.8.0.1 allows a remote unauthenticated attacker to enroll a device belonging to a restricted set of unenrolled devices, leading to information disclosure about EPMM appliance and impacting on the integrity of the newly enrolled device identity.', 'CVE-2026-7821', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7807', 'NVD', '2026-05-08 20:16:32', '2026-06-04 15:37:22', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7807', '["cpe:2.3:a:smartertools:smartermail:*:*:*:*:*:*:*:*"]', 8.7, 8.1, null, 'HIGH', null, '["CWE-22"]', 'SmarterTools SmarterMail builds prior to 9560 contain a local file inclusion vulnerability in the /api/v1/report/summary/{type} API endpoint that allows authenticated users to read arbitrary .json files on the system. Attackers can exploit this vulnerability combined with weak encryption algorithms and hardcoded keys to decrypt and access stored passwords and 2FA secrets for all users.', 'CVE-2026-7807', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7765', 'NVD', '2026-06-08 13:16:33', '2026-06-09 14:49:38', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7765', '["cpe:2.3:a:checkmk:checkmk:2.5.0:-:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:b1:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:b2:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:b3:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p1:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p2:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p3:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p4:*:*:*:*:*:*"]', 6.3, 5.3, null, 'MEDIUM', null, '["CWE-863"]', 'Incorrect authorization in the User Messages dashboard widget in Checkmk <2.5.0p5 causes the message-fetching endpoints to return the dashboard creator\'s messages rather than the viewer\'s, allowing an attacker who knows a valid public dashboard share token to read the issuer\'s personal messages by sending requests to the underlying endpoint, even without a User Messages widget present.', 'CVE-2026-7765', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7587', 'NVD', '2026-05-01 17:16:25', '2026-05-07 01:47:28', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7587', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability has been found in Open5GS up to 2.7.7. This vulnerability affects the function amf_nsmf_pdusession_handle_update_sm_context of the file /src/amf/nsmf-handler.c of the component AMF. The manipulation leads to denial of service. It is possible to initiate the attack remotely. The exploit has been disclosed to the public and may be used. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-7587', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7586', 'NVD', '2026-05-01 16:16:33', '2026-05-07 01:47:39', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7586', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A weakness has been identified in Open5GS up to 2.7.7. Affected is the function ogs_id_get_value of the file /src/amf/nudm-handler.c of the component AMF. This manipulation causes denial of service. Remote exploitation of the attack is possible. The exploit has been made available to the public and could be used for attacks. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-7586', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7585', 'NVD', '2026-05-01 16:16:33', '2026-05-07 01:47:52', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7585', '["cpe:2.3:a:open5gs:open5gs:*:*:*:*:*:*:*:*"]', 2.1, 4.3, 4, 'LOW', null, '["CWE-404"]', 'A vulnerability was determined in Open5GS up to 2.7.7. The impacted element is the function amf_nudm_sdm_handle_provisioned of the file /src/amf/nudm-handler.c of the component AMF. Executing a manipulation can lead to denial of service. The attack can be launched remotely. The exploit has been publicly disclosed and may be utilized. The project was informed of the problem early through an issue report but has not responded yet.', 'CVE-2026-7585', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7573', 'NVD', '2026-05-06 03:15:59', '2026-06-01 16:58:59', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7573', '["cpe:2.3:a:rapid7:velociraptor:*:*:*:*:*:*:*:*"]', null, 5, null, 'MEDIUM', null, '["CWE-639"]', 'An authorization bypass (CWE-639) in the GetUserRoles gRPC API endpoint in Velocidex Velociraptor below version 0.76.5 allows any authenticated low-privilege user to retrieve the complete ACL policy (roles and permissions) for any user across all organizations by supplying targeted Name and Org parameters via a network request.', 'CVE-2026-7573', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7572', 'NVD', '2026-05-06 03:15:58', '2026-06-01 16:59:31', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7572', '["cpe:2.3:a:rapid7:velociraptor:*:*:*:*:*:*:*:*"]', null, 4.4, null, 'MEDIUM', null, '["CWE-193"]', 'An off-by-one error (CWE-193) in the ConsumeUnit16Array and ConsumeUnit64Array functions in Velocidex Velociraptor before version 0.76.5 on Windows and Linux allows a local attacker to cause a Denial of Service (DoS) via a process crash by providing a specially crafted .evtx file to the parse_evtx VQL plugin.', 'CVE-2026-7572', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7568', 'NVD', '2026-05-10 05:16:11', '2026-05-12 17:38:55', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7568', '["cpe:2.3:a:php:php:*:*:*:*:*:*:*:*"]', 6.3, 7.5, null, 'MEDIUM', null, '["CWE-125", "CWE-190"]', 'In PHP versions 8.2.* before 8.2.31, 8.3.* before 8.3.31, 8.4.* before 8.4.21, and 8.5.* before 8.5.6, the metaphone() function in ext/standard/metaphone.c uses a signed int variable to track the current position within the input string. If a string longer than 2,147,483,647 bytes is passed, a signed integer overflow occurs, resulting in undefined behavior. This can lead to an out-of-bounds read, causing a segmentation fault or access to unrelated memory, and may affect the availability of the PHP process.', 'CVE-2026-7568', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7541', 'NVD', '2026-05-07 22:16:36', '2026-05-11 17:19:36', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7541', '["cpe:2.3:a:github:enterprise_server:*:*:*:*:*:*:*:*"]', 6.3, 7.5, null, 'MEDIUM', null, '["CWE-770"]', 'A denial of service vulnerability was identified in GitHub Enterprise Server that allowed an unauthenticated attacker to cause service disruption by sending crafted requests with deeply nested JSON payloads to an unauthenticated API endpoint. The endpoint parsed user-controlled JSON request bodies without size or depth limits, causing excessive CPU and memory consumption. This vulnerability affected all versions of GitHub Enterprise Server prior to 3.21 and was fixed in versions 3.20.2, 3.19.6, 3.18.9, 3.17.15, and 3.16.18. This vulnerability was reported via the GitHub Bug Bounty program.', 'CVE-2026-7541', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7454', 'NVD', '2026-05-26 18:16:56', '2026-05-26 20:40:28', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7454', '["cpe:2.3:a:autodesk:3ds_max:2026:*:*:*:*:*:*:*", "cpe:2.3:a:autodesk:3ds_max:2027:*:*:*:*:*:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-120"]', 'A maliciously crafted WRL file, when parsed through Autodesk 3ds Max, can force a Memory Corruption vulnerability. A malicious actor can leverage this vulnerability to execute arbitrary code in the context of the current process.', 'CVE-2026-7454', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7453', 'NVD', '2026-05-26 18:16:56', '2026-06-03 14:16:46', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7453', '["cpe:2.3:a:autodesk:3ds_max:2026:*:*:*:*:*:*:*", "cpe:2.3:a:autodesk:3ds_max:2027:*:*:*:*:*:*:*"]', null, 5.5, null, 'MEDIUM', null, '["CWE-674"]', 'A maliciously crafted WRL file, when parsed through Autodesk 3ds Max, can cause a Stack Exhaustion vulnerability, leading to a denial-of-service condition.', 'CVE-2026-7453', null);
