INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7324', 'NVD', '2026-04-28 15:16:37', '2026-05-01 15:27:50', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7324', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:-:*:*:*"]', null, 7.3, null, 'HIGH', null, '["CWE-119"]', 'Memory safety bugs present in Thunderbird 150.0.0. Some of these bugs showed evidence of memory corruption and we presume that with enough effort some of these could have been exploited to run arbitrary code. This vulnerability was fixed in Firefox 150.0.1 and Thunderbird 150.0.1.', 'CVE-2026-7324', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7323', 'NVD', '2026-04-28 15:16:37', '2026-04-30 18:38:23', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7323', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:firefox:*:*:*:*:esr:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:esr:*:*:*"]', null, 7.3, null, 'HIGH', null, '["CWE-119", "CWE-787"]', 'Memory safety bugs present in Thunderbird ESR 140.10.0 and Thunderbird 150.0.0. Some of these bugs showed evidence of memory corruption and we presume that with enough effort some of these could have been exploited to run arbitrary code. This vulnerability was fixed in Firefox 150.0.1, Firefox ESR 140.10.1, Thunderbird 150.0.1, and Thunderbird 140.10.1.', 'CVE-2026-7323', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7322', 'NVD', '2026-04-28 15:16:37', '2026-05-01 12:30:25', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7322', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:firefox:*:*:*:*:esr:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:esr:*:*:*"]', null, 7.3, null, 'HIGH', null, '["CWE-119", "CWE-416"]', 'Memory safety bugs present in Thunderbird ESR 140.10.0 and Thunderbird 150.0.0. Some of these bugs showed evidence of memory corruption and we presume that with enough effort some of these could have been exploited to run arbitrary code. This vulnerability was fixed in Firefox 150.0.1, Firefox ESR 140.10.1, Firefox ESR 115.35.1, Thunderbird 150.0.1, and Thunderbird 140.10.1.', 'CVE-2026-7322', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7321', 'NVD', '2026-04-28 15:16:37', '2026-05-01 17:54:04', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7321', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:firefox:*:*:*:*:esr:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:esr:*:*:*"]', null, 9.6, null, 'CRITICAL', null, '["CWE-120"]', 'Sandbox escape due to incorrect boundary conditions in the WebRTC: Networking component. This vulnerability was fixed in Firefox 150, Thunderbird 150, Firefox ESR 140.10.1, and Thunderbird 140.10.1.', 'CVE-2026-7321', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7320', 'NVD', '2026-04-28 15:16:37', '2026-05-01 12:32:05', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7320', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:firefox:*:*:*:*:esr:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:esr:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-119"]', 'Information disclosure due to incorrect boundary conditions in the Audio/Video component. This vulnerability was fixed in Firefox 150.0.1, Firefox ESR 140.10.1, Firefox ESR 115.35.1, Thunderbird 150.0.1, and Thunderbird 140.10.1.', 'CVE-2026-7320', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7313', 'NVD', '2026-06-02 14:17:14', '2026-06-04 13:12:04', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7313', '["cpe:2.3:a:progress:sitefinity:*:*:*:*:*:*:*:*"]', null, 8.7, null, 'HIGH', null, '["CWE-522"]', 'CWE‑522: Insufficiently Protected Credentials in web services in Progress Sitefinity version from 8.0.5700 to 13.3.7652 allows a remote authenticated attacker to obtain plain-text credentials used connect to Sitefinity Insight service. Successful exploitation requires active integration with Sitefinity Insight, non-default site configuration and valid back-end authorization.', 'CVE-2026-7313', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7312', 'NVD', '2026-06-02 14:17:14', '2026-06-04 13:09:14', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7312', '["cpe:2.3:a:progress:sitefinity:*:*:*:*:*:*:*:*"]', null, 10, null, 'CRITICAL', null, '["CWE-522"]', 'CWE‑522: Insufficiently Protected Credentials in web services in Progress Sitefinity version from 14.0.7700 to 14.4.8152, and 15.0.8200 to 15.0.8234, and 15.1.8300 to 15.1.8335, 15.2.8400 to 15.2.8441, 15.3.8500 to 15.3.8531, and 15.4.8600 to 15.4.8630 allows a remote unauthenticated attacker to obtain plain-text credentials used connect to Sitefinity Insight service. Successful exploitation requires active integration with Sitefinity Insight and non-default site configuration.', 'CVE-2026-7312', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7309', 'NVD', '2026-04-28 13:19:24', '2026-05-07 02:16:00', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7309', '["cpe:2.3:a:redhat:openshift_container_platform:4.0:*:*:*:*:*:*:*"]', null, 4.3, null, 'MEDIUM', null, '["CWE-426"]', 'A flaw was found in the OpenShift Container Platform build system. A user with the `edit` ClusterRole can inject arbitrary environment variables, such as `LD_PRELOAD` or `http_proxy`, into `docker-build` containers through the `buildconfigs/instantiate` API. This incomplete fix for a previous vulnerability allows for information disclosure, specifically impacting the confidentiality of build traffic.', 'CVE-2026-7309', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7299', 'NVD', '2026-06-02 16:16:45', '2026-06-04 17:41:57', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7299', '["cpe:2.3:a:appsmith:appsmith:*:*:*:*:*:*:*:*"]', null, 6.3, null, 'MEDIUM', null, '["CWE-79"]', 'Appsmith’s SQL query editor’s autocomplete functionality fails to sanitize database object names before rendering them in innerHTML, allowing an authenticated Developer to inject persistent XSS by a malicious table or column names triggering arbitrary code execution in the sessions of other workspace members when they interact with the same datasource.', 'CVE-2026-7299', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7263', 'NVD', '2026-05-10 06:16:08', '2026-05-12 17:35:49', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7263', '["cpe:2.3:a:php:php:*:*:*:*:*:*:*:*"]', 6.3, 7.5, null, 'MEDIUM', null, '["CWE-404", "CWE-835"]', 'In PHP versions 8.4.* before 8.4.21 and 8.5.* before 8.5.6, DOMNode::C14N() method may process the XML data incorrectly, causing a circular linked list in the data structure representing the XML document. This may cause subsequent processing of the XML document to enter infinite loop, causing denial of service in the processing application.', 'CVE-2026-7263', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7262', 'NVD', '2026-05-10 05:16:11', '2026-05-12 17:39:15', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7262', '["cpe:2.3:a:php:php:*:*:*:*:*:*:*:*"]', 2.9, 7.5, null, 'LOW', null, '["CWE-476"]', 'In PHP versions 8.2.* before 8.2.31, 8.3.* before 8.3.31, 8.4.* before 8.4.21, and 8.5.* before 8.5.6, when a SOAP server has a typemap configured, the decoding process contains a mistake which checks the wrong variable in case of missing value element.  This leads to dereferences a NULL pointer, causing a segmentation fault. This allows a remote unauthenticated attacker to crash the PHP SOAP server process, resulting in denial of service.', 'CVE-2026-7262', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7261', 'NVD', '2026-05-10 05:16:11', '2026-05-12 17:40:03', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7261', '["cpe:2.3:a:php:php:*:*:*:*:*:*:*:*"]', 6.3, 9.8, null, 'MEDIUM', null, '["CWE-416"]', 'In PHP versions 8.2.* before 8.2.31, 8.3.* before 8.3.31, 8.4.* before 8.4.21, and 8.5.* before 8.5.6, when SoapServer is configured with SOAP_PERSISTENCE_SESSION, the handler object is persisted across requests via session storage. However, in the case SOAP requests results in an error, the persistance is handled incorrectly, resulting in freeing the object while keeping a pointer to it, which may lead to use-after-free. This may lead to memory corruption, information disclosure, or process crashes, with confidentiality, integrity, and availability impact on the vulnerable system.', 'CVE-2026-7261', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7259', 'NVD', '2026-05-10 05:16:11', '2026-05-12 17:40:38', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7259', '["cpe:2.3:a:php:php:*:*:*:*:*:*:*:*"]', 2.1, 6.5, null, 'LOW', null, '["CWE-476"]', 'In PHP versions 8.2.* before 8.2.31, 8.3.* before 8.3.31, 8.4.* before 8.4.21, and 8.5.* before 8.5.6, a mismatch between encoding lists in Oniguruma and mbfl leads to  a NULL pointer dereference, resulting in a segmentation fault and denial of service. The vulnerability is exploitable when user-controlled input can influence the encoding passed to mb_regex_encoding().', 'CVE-2026-7259', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7258', 'NVD', '2026-05-10 05:16:11', '2026-05-12 17:41:43', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7258', '["cpe:2.3:a:php:php:*:*:*:*:*:*:*:*"]', 6.3, 7.5, null, 'MEDIUM', null, '["CWE-125"]', 'In PHP versions 8.2.* before 8.2.31, 8.3.* before 8.3.31, 8.4.* before 8.4.21, and 8.5.* before 8.5.6, some functions, including urldecode(), pass signed char to ctype functions (like isxdigit()). On the systems with default signed char and optimized table-lookup ctype functions - such as NetBSD - this can lead to accessing array with negative offset, which can trigger a denial of service.', 'CVE-2026-7258', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7233', 'NVD', '2026-04-28 07:16:04', '2026-05-05 21:16:23', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7233', '["cpe:2.3:a:artifex:mupdf:*:*:*:*:*:*:*:*"]', 1.9, 3.3, 1.7, 'LOW', null, '["CWE-119", "CWE-125"]', 'A vulnerability was determined in Artifex MuPDF up to 1.28.0. The impacted element is the function fz_subset_cff_for_gids of the file subset-cff.c of the component CFF Index Handler. This manipulation causes out-of-bounds read. The attack can only be executed locally. The exploit has been publicly disclosed and may be utilized. The project was informed of the problem early through a bug report but has not responded yet.', 'CVE-2026-7233', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7210', 'NVD', '2026-05-11 18:16:42', '2026-06-10 19:16:38', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7210', '["cpe:2.3:a:python:python:*:*:*:*:*:*:*:*"]', 6.3, 9.8, null, 'MEDIUM', null, '["CWE-331"]', '`xml.parsers.expat` and `xml.etree.ElementTree` use insufficient entropy for Expat hash-flooding protection, which allows a crafted XML document to trigger hash flooding.\\r\\n\\r\\nFully mitigating this vulnerability requires both updating libexpat to 2.8.0 or later and applying this patch.', 'CVE-2026-7210', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7201', 'NVD', '2026-06-02 14:17:14', '2026-06-04 12:42:05', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7201', '["cpe:2.3:a:progress:sitefinity:*:*:*:*:*:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-639"]', 'CWE-639: Authorization Bypass Through User-Controlled Key in web services in Progress Sitefinity 15.2.x before 15.2.8441, 15.3.x before 15.3.8531, and 15.4.x before 15.4.8630 allows a remote authenticated attacker to modify account properties of other users, potentially leading to account compromise. Successful exploitation requires knowledge of values that are not generally exposed to low-privileged users.', 'CVE-2026-7201', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7198', 'NVD', '2026-06-02 14:17:14', '2026-06-04 12:43:06', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7198', '["cpe:2.3:a:progress:sitefinity:*:*:*:*:*:*:*:*"]', null, 9.8, null, 'CRITICAL', null, '["CWE-284"]', 'CWE-284: Improper Access Control in web services in Progress Sitefinity 15.4.8623 before 15.4.8630 allows a remote unauthenticated attacker to access content that should be restricted, resulting in full compromise of confidentiality, integrity, and availability of affected installations.', 'CVE-2026-7198', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-7195', 'NVD', '2026-06-02 14:17:14', '2026-06-04 12:51:51', 'https://nvd.nist.gov/vuln/detail/CVE-2026-7195', '["cpe:2.3:a:progress:sitefinity:*:*:*:*:*:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-20"]', 'CWE-20: Improper Input Validation in web services in Progress Sitefinity 14.1.x through 14.3.x, 14.4.x before 14.4.8152, 15.0.x before 15.0.8234, 15.1.x before 15.1.8335, 15.2.x before 15.2.8441, 15.3.x before 15.3.8531, and 15.4.x before 15.4.8630 allows a remote unauthenticated attacker to compromise the integrity and confidentiality of user accounts. Successful exploitation requires user interaction and a non-default site configuration.', 'CVE-2026-7195', null);
