.3:a:checkmk:checkmk:2.5.0:b2:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:b3:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p1:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p2:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p3:*:*:*:*:*:*", "cpe:2.3:a:checkmk:checkmk:2.5.0:p4:*:*:*:*:*:*"]', 8.5, 5.4, null, 'HIGH', null, '["CWE-79"]', 'Stored cross-site scripting in the URL dashboard widget in Checkmk <2.5.0p5, <2.4.0p31, <2.3.0p48, and all 2.2.0 versions allows a user with dashboard editing permissions to store a URL with a dangerous URI scheme such as javascript: that executes scripts in other users\' browsers when they view the dashboard.', 'CVE-2026-7186', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6986', 'NVD', '2026-04-25 17:16:33', '2026-04-29 19:00:39', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6986', '["cpe:2.3:a:cesanta:mongoose:*:*:*:*:*:*:*:*"]', 2.9, 3.7, 2.6, 'LOW', null, '["CWE-345", "CWE-347"]', 'A security vulnerability has been detected in Cesanta Mongoose up to 7.20. This issue affects the function mg_aes_gcm_decrypt of the file /src/tls_aes128.c of the component GCM Authentication Tag Handler. Such manipulation leads to improper verification of cryptographic signature. The attack may be performed from remote. A high complexity level is associated with this attack. The exploitability is assessed as difficult. The exploit has been disclosed publicly and may be used. Upgrading to version 7.21 is capable of addressing this issue. It is advisable to upgrade the affected component. VulDB has contacted the vendor early and they confirmed quickly, that this issue got fixed already.', 'CVE-2026-6986', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6985', 'NVD', '2026-04-25 17:16:33', '2026-04-29 19:05:12', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6985', '["cpe:2.3:a:cesanta:mongoose:*:*:*:*:*:*:*:*"]', 5.5, 5.3, 5, 'MEDIUM', null, '["CWE-404", "CWE-835"]', 'A weakness has been identified in Cesanta Mongoose up to 7.20. This vulnerability affects the function handle_opt of the file /src/net_builtin.c of the component TCP Option Handler. This manipulation of the argument optlen causes infinite loop. The attack is possible to be carried out remotely. The exploit has been made available to the public and could be used for attacks. Upgrading to version 7.21 is able to resolve this issue. Upgrading the affected component is advised. VulDB has contacted the vendor early and they confirmed quickly, that this issue got fixed already.', 'CVE-2026-6985', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6973', 'NVD', '2026-05-07 16:16:23', '2026-06-09 18:45:48', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6973', '["cpe:2.3:a:ivanti:endpoint_manager_mobile:*:*:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager_mobile:12.9.0.0:*:*:*:*:*:*:*"]', null, 7.2, null, 'HIGH', null, '["CWE-15"]', 'A configuration control vulnerability in the Ivanti Endpoint Manager Mobile before 12.9.0.1, 12.8.0.3 and 12.7.0.2 versions allows a remote authenticated attacker to inject arbitrary Apache directives, leading to remote code execution.', 'CVE-2026-6973', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6968', 'NVD', '2026-04-24 20:16:29', '2026-05-06 15:36:48', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6968', '["cpe:2.3:a:amazon:tough:*:*:*:*:*:rust:*:*", "cpe:2.3:a:amazon:tuftool:*:*:*:*:*:rust:*:*"]', 7.1, 5.9, null, 'HIGH', null, '["CWE-22"]', 'Incomplete path traversal fixes in awslabs/tough before tough-v0.22.0 allow remote authenticated users with delegated signing authority to write files outside intended output directories via absolute target names in copy_target/link_target, symlinked parent directories in save_target, or symlinked metadata filenames in SignedRole::write, because write paths trust the joined destination path without post-resolution containment verification.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6967', 'NVD', '2026-04-24 20:16:29', '2026-05-06 15:32:38', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6967', '["cpe:2.3:a:amazon:tough:*:*:*:*:*:rust:*:*", "cpe:2.3:a:amazon:tuftool:*:*:*:*:*:rust:*:*"]', 7.1, 5.9, null, 'HIGH', null, '["CWE-345"]', 'Missing expiration, hash, and length enforcement in delegated metadata validation in awslabs/tough before tough-v0.22.0 allows remote authenticated users with delegated signing authority to bypass TUF specification integrity checks for delegated targets metadata and poison the local metadata cache, because load_delegations does not apply the same validation checks as the top-level targets metadata path.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6966', 'NVD', '2026-04-24 20:16:28', '2026-05-06 15:24:56', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6966', '["cpe:2.3:a:amazon:tough:*:*:*:*:*:rust:*:*", "cpe:2.3:a:amazon:tuftool:*:*:*:*:*:rust:*:*"]', 7, 5.3, null, 'HIGH', null, '["CWE-347"]', 'Improper verification of cryptographic signature uniqueness in delegated role validation in awslabs/tough before tough-v0.22.0 allows remote authenticated users to bypass the TUF signature threshold requirement by duplicating a valid signature, causing the client to accept forged delegated role metadata.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6951', 'NVD', '2026-04-25 06:16:16', '2026-05-18 18:20:15', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6951', '["cpe:2.3:a:simple-git_project:simple-git:*:*:*:*:*:node.js:*:*"]', 8.2, 9.8, null, 'HIGH', null, '["CWE-94"]', 'Versions of the package simple-git before 3.36.0 are vulnerable to Remote Code Execution (RCE) due to an incomplete fix for [CVE-2022-25912](https://security.snyk.io/vuln/SNYK-JS-SIMPLEGIT-3112221) that blocks the -c option but not the equivalent --config form. If untrusted input can reach the options argument passed to simple-git, an attacker may still achieve remote code execution by enabling protocol.ext.allow=always and using an ext:: clone source.', 'CVE-2026-6951', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6941', 'NVD', '2026-04-23 21:16:06', '2026-04-27 14:57:19', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6941', '["cpe:2.3:a:radare:radare2:*:*:*:*:*:*:*:*"]', 6.9, 6.6, null, 'MEDIUM', null, '["CWE-59", "CWE-22"]', 'radare2 prior to 6.1.4 contains a path traversal vulnerability in its project notes handling that allows attackers to read or write files outside the configured project directory by importing a malicious .zrp archive containing a symlinked notes.txt file. Attackers can craft a .zrp archive with a symlinked notes.txt that bypasses directory confinement checks, allowing note operations to follow the symlink and access arbitrary files outside the dir.projects root directory.', 'CVE-2026-6941', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6940', 'NVD', '2026-04-23 21:16:06', '2026-04-27 14:56:28', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6940', '["cpe:2.3:a:radare:radare2:*:*:*:*:*:*:*:*"]', 6.9, 7.1, null, 'MEDIUM', null, '["CWE-22"]', 'radare2 prior to 6.1.4 contains a path traversal vulnerability in project deletion that allows local attackers to recursively delete arbitrary directories by supplying absolute paths that escape the configured dir.projects root directory. Attackers can craft absolute paths to project marker files outside the project storage boundary to cause recursive deletion of attacker-chosen directories with permissions of the radare2 process, resulting in integrity and availability loss.', 'CVE-2026-6940', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6936', 'NVD', '2026-05-27 14:17:34', '2026-05-28 15:46:09', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6936', '["cpe:2.3:a:ibm:i:*:*:*:*:*:*:*:*"]', null, 6.5, null, 'MEDIUM', null, '["CWE-674"]', 'IBM i 7.6, 7.5, 7.4, and 7.3 s vulnerable to a denial-of-service attack due to uncontrolled recursion in the Integrated Language Environment (ILE) compiler. An authenticated attacker could exploit this vulnerability by compiling specially crafted source code containing a specific combination of statements.', 'CVE-2026-6936', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6921', 'NVD', '2026-04-23 18:16:30', '2026-05-27 18:16:34', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6921', '["cpe:2.3:a:google:chrome:*:*:*:*:*:*:*:*"]', null, 8.3, null, 'HIGH', null, '["CWE-362"]', 'Race in GPU in Google Chrome on Windows prior to 147.0.7727.117 allowed a remote attacker to potentially perform a sandbox escape via a crafted video file. (Chromium security severity: Medium)', 'CVE-2026-6921', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6920', 'NVD', '2026-04-23 18:16:30', '2026-05-26 18:16:55', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6920', '["cpe:2.3:a:google:chrome:*:*:*:*:*:*:*:*"]', null, 9.6, null, 'CRITICAL', null, '["CWE-125"]', 'Out of bounds read in GPU in Google Chrome on Android prior to 147.0.7727.117 allowed a remote attacker who had compromised the renderer process to potentially perform a sandbox escape via a crafted HTML page. (Chromium security severity: High)', 'CVE-2026-6920', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6919', 'NVD', '2026-04-23 18:16:30', '2026-05-26 19:16:33', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6919', '["cpe:2.3:a:google:chrome:*:*:*:*:*:*:*:*"]', null, 9.6, null, 'CRITICAL', null, '["CWE-416"]', 'Use after free in DevTools in Google Chrome prior to 147.0.7727.117 allowed a remote attacker who had compromised the renderer process to potentially perform a sandbox escape via a crafted HTML page. (Chromium security severity: High)', 'CVE-2026-6919', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6918', 'NVD', '2026-05-05 13:16:30', '2026-05-05 20:08:58', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6918', '["cpe:2.3:a:eclipse:openj9:*:*:*:*:*:*:*:*"]', 8.7, 7.5, null, 'HIGH', null, '["CWE-125"]', 'In Eclipse Open9J versions 0.21 to 0.58, a pre-authentication remote attacker can crash JITServer by sending a 32-byte crafted TCP message.', 'CVE-2026-6918', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6915', 'NVD', '2026-04-29 17:16:41', '2026-05-06 20:08:44', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6915', '["cpe:2.3:a:mongodb:mongodb:*:*:*:*:-:*:*:*"]', 5.3, 6.3, null, 'MEDIUM', null, '["CWE-1284"]', 'An authorization flaw in the user management command could allow an authenticated user to make limited changes to authentication-related data associated with another user account. This could affect how authentication is performed for the impacted account.', 'CVE-2026-6915', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6914', 'NVD', '2026-04-29 17:16:41', '2026-05-06 20:11:08', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6914', '["cpe:2.3:a:mongodb:mongodb:*:*:*:*:-:*:*:*"]', 7.1, 6.5, null, 'HIGH', null, '["CWE-191"]', 'Computing the MD5 checksum of a malformed BSON object under specific conditions may cause loss of availability in MongoDB server.
