INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6868', 'NVD', '2026-04-30 06:16:16', '2026-05-01 19:01:36', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6868', '["cpe:2.3:a:wireshark:wireshark:*:*:*:*:*:*:*:*"]', null, 5.5, null, 'MEDIUM', null, '["CWE-121"]', 'HTTP protocol dissector crash in Wireshark 4.6.0 to 4.6.4 and 4.4.0 to 4.4.14 allows denial of service', 'CVE-2026-6868', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6867', 'NVD', '2026-04-30 07:16:41', '2026-05-01 18:15:20', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6867', '["cpe:2.3:a:wireshark:wireshark:*:*:*:*:*:*:*:*"]', null, 5.5, null, 'MEDIUM', null, '["CWE-1325"]', 'SMB2 protocol dissector crash in Wireshark 4.6.0 to 4.6.4 and 4.4.0 to 4.4.14 allows denial of service', 'CVE-2026-6867', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6861', 'NVD', '2026-04-22 14:17:07', '2026-05-06 20:27:36', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6861', '["cpe:2.3:a:gnu:emacs:*:*:*:*:*:*:*:*"]', null, 6.1, null, 'MEDIUM', null, '["CWE-193"]', 'A flaw was found in GNU Emacs. This vulnerability, a memory corruption issue, occurs when Emacs processes specially crafted SVG (Scalable Vector Graphics) CSS (Cascading Style Sheets) data. A local user could exploit this by convincing a victim to open a malicious SVG file, which may lead to a denial of service (DoS) or potentially information disclosure.', 'CVE-2026-6861', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6848', 'NVD', '2026-04-22 10:16:52', '2026-05-20 13:38:24', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6848', '["cpe:2.3:a:redhat:quay:3.0.0:*:*:*:*:*:*:*"]', null, 5.4, null, 'MEDIUM', null, '["CWE-613"]', 'A flaw was found in Red Hat Quay. When Red Hat Quay requests password re-verification for sensitive operations, such as token generation or robot account creation, the re-authentication prompt can be bypassed. This allows a user with a timed-out session, or an attacker with access to an idle authenticated browser session, to perform privileged actions without providing valid credentials. The vulnerability enables unauthorized execution of sensitive operations despite the user interface displaying an error for invalid credentials.', 'CVE-2026-6848', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6846', 'NVD', '2026-04-22 09:16:27', '2026-05-20 13:47:30', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6846', '["cpe:2.3:a:gnu:binutils:*:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:hardened_images:-:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:openshift_container_platform:4.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:10.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:6.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:8.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:9.0:*:*:*:*:*:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-122"]', 'A flaw was found in binutils. A heap-buffer-overflow vulnerability exists when processing a specially crafted XCOFF (Extended Common Object File Format) object file during linking. A local attacker could trick a user into processing this malicious file, which could lead to arbitrary code execution, allowing the attacker to run unauthorized commands, or cause a denial of service, making the system unavailable.', 'CVE-2026-6846', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6845', 'NVD', '2026-04-22 09:16:27', '2026-05-20 13:58:17', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6845', '["cpe:2.3:a:gnu:binutils:-:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:hardened_images:-:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:openshift_container_platform:4.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:10.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:6.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:7.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:8.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:9.0:*:*:*:*:*:*:*"]', null, 5, null, 'MEDIUM', null, '["CWE-476"]', 'A flaw was found in binutils, specifically within the `readelf` utility. This vulnerability allows a local attacker to cause a Denial of Service (DoS) by tricking a user into processing a specially crafted Executable and Linkable Format (ELF) file. The exploitation of this flaw can lead to the system becoming unresponsive due to excessive resource consumption or a program crash.', 'CVE-2026-6845', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6844', 'NVD', '2026-04-22 09:16:27', '2026-05-20 14:00:12', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6844', '["cpe:2.3:a:gnu:binutils:-:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:hardened_images:-:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:openshift_container_platform:4.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:10.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:7.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:8.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:9.0:*:*:*:*:*:*:*"]', null, 5.5, null, 'MEDIUM', null, '["CWE-400"]', 'A flaw was found in the `readelf` utility of the binutils package. A local attacker could exploit two Denial of Service (DoS) vulnerabilities by providing a specially crafted Executable and Linkable Format (ELF) file. One vulnerability, a resource exhaustion (CWE-400), can lead to an out-of-memory condition. The other, a null pointer dereference (CWE-476), can cause a segmentation fault. Both issues can result in the `readelf` utility becoming unresponsive or crashing, leading to a denial of service.', 'CVE-2026-6844', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6843', 'NVD', '2026-04-22 09:16:26', '2026-05-20 14:10:44', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6843', '["cpe:2.3:a:gnu:nano:8.7:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:openshift_container_platform:4.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:10.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:6.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:7.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:8.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:9.0:*:*:*:*:*:*:*"]', null, 5.5, null, 'MEDIUM', null, '["CWE-134"]', 'A flaw was found in nano. A local user could exploit a format string vulnerability in the `statusline()` function. By creating a directory with a name containing `printf` specifiers, the application attempts to display this name, leading to a segmentation fault (SEGV). This results in a Denial of Service (DoS) for the `nano` application.', 'CVE-2026-6843', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6841', 'NVD', '2026-05-21 13:16:20', '2026-06-01 14:02:21', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6841', '["cpe:2.3:a:bestpractical:request_tracker:*:*:*:*:*:*:*:*"]', 5.1, 6.1, null, 'MEDIUM', null, '["CWE-79"]', 'Request Tracker is vulnerable to a reflected cross-site scripting (XSS) vulnerability via the "Page" parameter in GET requests. An attacker can craft a URL that, when opened, results in arbitrary JavaScript execution in the victim’s browser.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6826', 'NVD', '2026-05-21 21:16:32', '2026-05-26 14:59:02', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6826', '["cpe:2.3:a:concretecms:concrete_cms:*:*:*:*:*:*:*:*"]', 6.9, 5.3, null, 'MEDIUM', null, '["CWE-200"]', 'Concrete CMS 9.5.0 and below  is vulnerable to unauthenticated file usage disclosure via missing permission check in the usage controller.  Any unauthenticated visitor can request /ccm/system/dialogs/file/usage/{fID} with any file ID and receive a list of every page that references that file, including page IDs, handles, and full URLs. This includes pages that are otherwise restricted by permissions.The Concrete CMS security team gave this vulnerability a CVSS v.4.0 score of 6.9 with vector CVSS:4.0/AV:N/AC:L/AT:N/PR:N/UI:N/VC:L/VI:N/VA:N/SC:N/SI:N/SA:N. Thanks Eldudareeno for reporting.', 'CVE-2026-6826', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6815', 'NVD', '2026-05-11 16:17:37', '2026-06-01 16:38:43', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6815', '["cpe:2.3:a:casbin:casdoor:*:*:*:*:*:*:*:*"]', null, 5.9, null, 'MEDIUM', null, '["CWE-22"]', 'An arbitrary file write vulnerability exists in Casdoor\'s Local File System storage provider. Due to insufficient path sanitization, an authenticated attacker with administrative privileges can perform a Path Traversal attack to create or overwrite arbitrary files anywhere on the host filesystem, bypassing the application\'s intended storage sandbox.', 'CVE-2026-6815', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6786', 'NVD', '2026-04-26 19:53:39', '2026-05-26 20:16:20', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6786', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:firefox:*:*:*:*:esr:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:esr:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-125", "CWE-416", "CWE-787"]', 'Memory safety bugs present in Firefox ESR 140.9, Thunderbird ESR 140.9, Firefox 149 and Thunderbird 149. Some of these bugs showed evidence of memory corruption and we presume that with enough effort some of these could have been exploited to run arbitrary code. This vulnerability was fixed in Firefox 150, Firefox ESR 140.10, Thunderbird 150, and Thunderbird 140.10.', 'CVE-2026-6786', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6785', 'NVD', '2026-04-26 19:53:39', '2026-05-27 18:16:33', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6785', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:firefox:*:*:*:*:esr:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:esr:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-125", "CWE-416", "CWE-787"]', 'Memory safety bugs present in Firefox ESR 115.34, Firefox ESR 140.9, Thunderbird ESR 140.9, Firefox 149 and Thunderbird 149. Some of these bugs showed evidence of memory corruption and we presume that with enough effort some of these could have been exploited to run arbitrary code. This vulnerability was fixed in Firefox 150, Firefox ESR 115.35, Firefox ESR 140.10, Thunderbird 150, and Thunderbird 140.10.', 'CVE-2026-6785', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6784', 'NVD', '2026-04-21 13:16:24', '2026-05-07 16:16:22', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6784', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:-:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-125", "CWE-416", "CWE-787"]', 'Memory safety bugs present in Firefox 149 and Thunderbird 149. Some of these bugs showed evidence of memory corruption and we presume that with enough effort some of these could have been exploited to run arbitrary code. This vulnerability was fixed in Firefox 150 and Thunderbird 150.', 'CVE-2026-6784', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6783', 'NVD', '2026-04-21 13:16:23', '2026-04-22 15:18:29', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6783', '["cpe:2.3:a:mozilla:firefox:*:*:*:*:-:*:*:*", "cpe:2.3:a:mozilla:thunderbird:*:*:*:*:-:*:*:*"]', null, 5.3, null, 'MEDIUM', null, '["CWE-190"]', 'Incorrect boundary conditions, integer overflow in the Audio/Video: Playback component. This vulnerability was fixed in Firefox 150 and Thunderbird 150.', 'CVE-2026-6783', null);
