INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6482', 'NVD', '2026-04-17 06:16:30', '2026-04-28 18:14:41', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6482', '["cpe:2.3:a:rapid7:insight_agent:*:*:*:*:*:*:*:*"]', 8.5, 7.8, null, 'HIGH', null, '["CWE-829"]', 'The Rapid7 Insight Agent (versions > 4.1.0.2) is vulnerable to a local privilege escalation attack that allows users to gain SYSTEM level control of a Windows host. Upon startup the agent service attempts to load an OpenSSL configuration file from a non-existent directory that is writable by standard users. By planting a crafted openssl.cnf file an attacker can trick the high-privilege service into executing arbitrary commands. This effectively permits an unprivileged user to bypass security controls and achieve a full host compromise under the agent’s SYSTEM level access.', 'CVE-2026-6482', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6418', 'NVD', '2026-05-05 07:16:00', '2026-05-12 15:53:35', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6418', '["cpe:2.3:a:papercut:papercut_mf:*:*:*:*:*:*:*:*", "cpe:2.3:a:papercut:papercut_ng:*:*:*:*:*:*:*:*"]', 4.6, 4.9, null, 'MEDIUM', null, '["CWE-36", "CWE-552"]', 'An issue was discovered in the Shared Account Synchronization component of PaperCut MF (version 25.0.4). The application allows administrative users to configure a source path for account data synchronization.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6414', 'NVD', '2026-04-16 13:16:52', '2026-04-23 19:41:18', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6414', '["cpe:2.3:a:fastify:fastify-static:*:*:*:*:*:*:*:*"]', null, 5.9, null, 'MEDIUM', null, '["CWE-177"]', '@fastify/static versions 8.0.0 through 9.1.0 decode percent-encoded path separators (%2F) before filesystem resolution, while Fastify\'s router treats them as literal characters. This mismatch allows attackers to bypass route-based middleware or guards that protect files served by @fastify/static. For example, a route guard on a protected path can be circumvented by encoding the path separator in the URL. Upgrade to @fastify/static 9.1.1 to fix this issue. There are no workarounds.', 'CVE-2026-6414', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6410', 'NVD', '2026-04-16 14:16:20', '2026-04-23 19:31:39', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6410', '["cpe:2.3:a:fastify:fastify-static:*:*:*:*:*:*:*:*"]', null, 5.3, null, 'MEDIUM', null, '["CWE-22"]', '@fastify/static versions 8.0.0 through 9.1.0 allow path traversal when directory listing is enabled via the list option. The dirList.path() function resolves directories outside the configured static root using path.join() without a containment check. A remote unauthenticated attacker can obtain directory listings for arbitrary directories accessible to the Node.js process, disclosing directory and file names. File contents are not disclosed. Upgrade to @fastify/static 9.1.1 to fix this issue. As a workaround, disable directory listing by removing the list option from the plugin configuration.', 'CVE-2026-6410', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6367', 'NVD', '2026-05-19 23:16:58', '2026-05-20 22:58:38', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6367', '["cpe:2.3:a:drupal:drupal:*:*:*:*:*:*:*:*"]', null, 6.1, null, 'MEDIUM', null, '["CWE-79"]', 'Improper Neutralization of Input During Web Page Generation ("Cross-site Scripting") vulnerability in Drupal Drupal core allows Cross-Site Scripting (XSS).
