INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6290', 'NVD', '2026-04-15 18:17:25', '2026-04-23 20:44:59', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6290', '["cpe:2.3:a:rapid7:velociraptor:*:*:*:*:*:*:*:*"]', null, 8, null, 'HIGH', null, '["CWE-863"]', 'Velociraptor versions prior to 0.76.3 contain a vulnerability in the query() plugin which allows access to all orgs with the user\'s current ACL token. This allows an authenticated GUI user with access in one org, to use the query() plugin, in a notebook cell, to run VQL queries on other orgs which they may not have access to. The user\'s permissions in the other org are
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6265', 'NVD', '2026-04-27 14:16:51', '2026-05-07 02:18:35', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6265', '["cpe:2.3:a:cerberusftp:ftp_server:*:*:*:*:*:*:*:*"]', 7.3, 8.8, null, 'HIGH', null, '["CWE-278"]', 'Insecure preserved inherited permissions vulnerability in Cerberus FTP Server on Windows allows Privilege Escalation.This issue has been resolved in Cerberus FTP Server: 2026.1', 'CVE-2026-6265', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6238', 'NVD', '2026-04-28 19:37:47', '2026-05-04 17:57:24', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6238', '["cpe:2.3:a:gnu:glibc:*:*:*:*:*:*:*:*"]', null, 6.5, null, 'MEDIUM', null, '["CWE-126"]', 'The deprecated functions ns_printrrf, ns_printrr and fp_nquery in the GNU C Library version 2.2 and newer fail to validate the RDATA content against the RDATA length in a DNS response when processing LOC, CERT, TKEY or TSIG records, which may allow an attacker to craft a DNS response, causing a target application to crash or read uninitialized memory.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6180', 'NVD', '2026-05-05 07:16:00', '2026-05-12 19:04:43', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6180', '["cpe:2.3:a:papercut:papercut_mf:*:*:*:*:*:*:*:*", "cpe:2.3:a:papercut:papercut_ng:*:*:*:*:*:*:*:*"]', 4.1, 8.1, null, 'MEDIUM', null, '["CWE-20", "CWE-367"]', 'A race condition exists in PaperCut MF when processing badge-swipe data from certain HP multifunction devices. Under specific network conditions involving dropped packets and out-of-order sequence counters, the server may incorrectly process fragmented data chunks. If a sequence reset notification fails to reach the server, the server may reject the initial data chunk while erroneously accepting subsequent chunks before a connection reset completes.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6104', 'NVD', '2026-05-10 06:16:07', '2026-05-12 17:35:59', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6104', '["cpe:2.3:a:php:php:*:*:*:*:*:*:*:*"]', 6.3, 9.1, null, 'MEDIUM', null, '["CWE-125"]', 'In PHP versions 8.4.* before 8.4.21 and 8.5.* before 8.5.6, when an encoding name containing an embedded NUL byte is passed to mb_convert_encoding() or related mbstring functions, the code incorrectly assumes that when strncasecmp() returns 0 it means the strings have the same length. This can lead to out-of-bounds read of global memory, potentially causing a crash or information disclosure or crash. Affected functions include mb_convert_encoding(), mb_detect_encoding(), mb_convert_variables(), and mb_detect_order(), as well as the mbstring.detect_order and mbstring.http_output INI settings.', 'CVE-2026-6104', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6066', 'NVD', '2026-04-20 16:16:50', '2026-04-23 14:18:09', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6066', '["cpe:2.3:a:connectwise:automate:*:*:*:*:*:*:*:*"]', null, 7.1, null, 'HIGH', null, '["CWE-319"]', 'ConnectWise has released a security update for ConnectWise Automate™ that addresses a behavior in the ConnectWise Automate Solution Center where certain client-to-server communications could occur without transport-layer encryption. This could allow network‑based interception of Solution Center traffic in Automate deployments. The issue has been resolved in Automate 2026.4 by enforcing secure communication for affected Solution Center connections.', 'CVE-2026-6066', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-6019', 'NVD', '2026-04-22 20:16:42', '2026-05-28 19:15:28', 'https://nvd.nist.gov/vuln/detail/CVE-2026-6019', '["cpe:2.3:a:python:python:*:*:*:*:*:*:*:*"]', 2.1, 6.1, null, 'LOW', null, '["CWE-150", "CWE-116"]', 'http.cookies.Morsel.js_output() returns an inline <script> snippet and only escapes " for JavaScript string context. It does not neutralize the HTML parser-sensitive sequence </script> inside the generated script element. Mitigation base64-encodes the cookie value to disallow escaping using cookie value.', 'CVE-2026-6019', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5950', 'NVD', '2026-05-20 13:16:40', '2026-05-21 15:24:34', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5950', '["cpe:2.3:a:isc:bind:*:*:*:*:-:*:*:*"]', null, 5.3, null, 'MEDIUM', null, '["CWE-606"]', 'An unbounded resend loop vulnerability exists in the BIND 9 resolver state machine during bad-server handling, enabling a remote unauthenticated attacker to cause severe resource exhaustion by sending queries that trigger specific retry conditions.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5947', 'NVD', '2026-05-20 13:16:40', '2026-05-21 15:24:32', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5947', '["cpe:2.3:a:isc:bind:*:*:*:*:-:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-362", "CWE-416"]', 'Undefined behavior may result due to a race condition leading to a use-after-free violation.  If BIND receives an incoming DNS message signed with SIG(0), it begins work to validate that signature.  If, during that validation, the "recursive-clients" limit is reached (as would occur during a query flood), and that same DNS message is discarded per the limit, there is a brief window of time while the SIG(0) validation may attempt to read the now-discarded DNS message.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5946', 'NVD', '2026-05-20 13:16:40', '2026-05-21 15:24:29', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5946', '["cpe:2.3:a:isc:bind:*:*:*:*:-:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-20", "CWE-125", "CWE-617", "CWE-754", "CWE-843"]', 'Multiple flaws have been identified in `named` related to the handling of DNS messages whose CLASS is not Internet (`IN`) — for example, `CHAOS` or `HESIOD`, or DNS messages that specify meta-classes (`ANY` or `NONE`) in the question section. Specially crafted requests reaching the affected code paths — recursion, dynamic updates (`UPDATE`), zone change notifications (`NOTIFY`), or processing of `IN`-specific record types in non-`IN` data — can cause assertion failures in `named`.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5943', 'NVD', '2026-04-27 12:16:24', '2026-04-29 17:18:04', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5943', '["cpe:2.3:a:foxit:pdf_editor:*:*:*:*:*:*:*:*", "cpe:2.3:a:foxit:pdf_reader:*:*:*:*:*:*:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-416"]', 'Document structural anomalies caused inconsistencies between page element relationships and internal index states. When scripts triggered document modifications, object reference validity was not properly maintained, leading to a crash when accessing an invalid pointer during page information queries.', 'CVE-2026-5943', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5942', 'NVD', '2026-04-27 12:16:24', '2026-04-29 17:18:37', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5942', '["cpe:2.3:a:foxit:pdf_editor:*:*:*:*:*:*:*:*", "cpe:2.3:a:foxit:pdf_reader:*:*:*:*:*:*:*:*"]', null, 5.5, null, 'MEDIUM', null, '["CWE-416"]', 'Flaws in page lifecycle management allow document structure changes to desynchronize internal component states, causing subsequent operations to access invalidated objects and crash the program.', 'CVE-2026-5942', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5941', 'NVD', '2026-04-27 12:16:24', '2026-04-29 17:24:15', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5941', '["cpe:2.3:a:foxit:pdf_editor:*:*:*:*:*:*:*:*", "cpe:2.3:a:foxit:pdf_reader:*:*:*:*:*:*:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-20"]', 'Parsing logic flaws cause non-signature data to be misidentified as valid signatures when processing malformed form field hierarchies, leading to invalid memory writes and program crashes during internal data structure construction.', 'CVE-2026-5941', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5940', 'NVD', '2026-04-27 12:16:24', '2026-04-29 17:26:50', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5940', '["cpe:2.3:a:foxit:pdf_editor:*:*:*:*:*:*:*:*", "cpe:2.3:a:foxit:pdf_reader:*:*:*:*:*:*:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-416"]', 'Calling a function that triggers a UI refresh after removing comments via a script may access an invalidated object, leading to program crashes.', 'CVE-2026-5940', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5939', 'NVD', '2026-04-27 12:16:24', '2026-04-29 17:28:10', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5939', '["cpe:2.3:a:foxit:pdf_editor:*:*:*:*:*:*:*:*", "cpe:2.3:a:foxit:pdf_reader:*:*:*:*:*:*:*:*"]', null, 5.5, null, 'MEDIUM', null, '["CWE-416"]', 'A crafted XFA PDF can trigger a use-after-free condition during calculate event processing, causing the application to crash and resulting in an arbitrary code execution.', 'CVE-2026-5939', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5938', 'NVD', '2026-04-27 12:16:24', '2026-04-29 17:29:29', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5938', '["cpe:2.3:a:foxit:pdf_editor:*:*:*:*:*:*:*:*", "cpe:2.3:a:foxit:pdf_reader:*:*:*:*:*:*:*:*"]', null, 5.5, null, 'MEDIUM', null, '["CWE-691"]', 'Improper control flow management allows a crafted document action chain to cause modal dialog reentry on the main thread, resulting in UI freeze and denial of service.', 'CVE-2026-5938', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5937', 'NVD', '2026-04-27 12:16:24', '2026-04-29 17:31:29', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5937', '["cpe:2.3:a:foxit:pdf_editor:*:*:*:*:*:*:*:*", "cpe:2.3:a:foxit:pdf_reader:*:*:*:*:*:*:*:*"]', null, 5.5, null, 'MEDIUM', null, '["CWE-248"]', 'Insufficient parameter verification leads to the occurrence of format errors in files, which will trigger an unhandled "std::invalid_argument" exception, ultimately causing the program to terminate.', 'CVE-2026-5937', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5928', 'NVD', '2026-04-20 21:16:36', '2026-04-23 15:33:43', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5928', '["cpe:2.3:a:gnu:glibc:*:*:*:*:*:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-127"]', 'Calling the ungetwc function on a FILE stream with wide characters encoded in a character set that has overlaps between its single byte and multi-byte character encodings, in the GNU C Library version 2.43 or earlier, may result in an attempt to read bytes before an allocated buffer, potentially resulting in unintentional disclosure of neighboring data in the heap, or a program crash.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5926', 'NVD', '2026-04-23 00:16:46', '2026-05-13 20:40:35', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5926', '["cpe:2.3:a:ibm:security_verify_access:*:*:*:*:*:*:*:*", "cpe:2.3:a:ibm:security_verify_access_container:*:*:*:*:*:*:*:*", "cpe:2.3:a:ibm:verify_identity_access:*:*:*:*:*:*:*:*", "cpe:2.3:a:ibm:verify_identity_access_container:*:*:*:*:*:*:*:*"]', null, 6.5, null, 'MEDIUM', null, '["CWE-327"]', 'IBM Verify Identity Access Container 11.0 through 11.0.2 and IBM Security Verify Access Container 10.0 through 10.0.9.1 and IBM Verify Identity Access 11.0 through 11.0.2 and IBM Security Verify Access 10.0 through 10.0.9.1 uses weaker than expected cryptographic algorithms that could allow an attacker to decrypt highly sensitive information.', 'CVE-2026-5926', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5921', 'NVD', '2026-04-21 23:16:22', '2026-04-28 20:43:12', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5921', '["cpe:2.3:a:github:enterprise_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:github:enterprise_server:3.20.0:*:*:*:*:*:*:*"]', 8.9, 8.9, null, 'HIGH', null, '["CWE-918"]', 'A server-side request forgery (SSRF) vulnerability was identified in GitHub Enterprise Server that allowed an attacker to extract sensitive environment variables from the instance through a timing side-channel attack against the notebook rendering service. When private mode was disabled, the notebook viewer followed HTTP redirects without revalidating the destination host, enabling an unauthenticated SSRF to internal services. By chaining this with regex filter queries against an internal API and measuring response time differences, an attacker could infer secret values character by character. Exploitation required that private mode be disabled and that the attacker be able to chain the instance\'s open redirect endpoint through an external redirect to reach internal services. This vulnerability affected all versions of GitHub Enterprise Server prior to 3.21 and was fixed in versions 3.14.26, 3.15.21, 3.16.17, 3.17.14, 3.18.8, 3.19.5, and 3.20.1. This vulnerability was reported via the GitHub Bug Bounty program.', 'CVE-2026-5921', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5845', 'NVD', '2026-04-21 23:16:22', '2026-04-29 12:30:18', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5845', '["cpe:2.3:a:github:enterprise_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:github:enterprise_server:3.20.0:*:*:*:*:*:*:*"]', 7.2, 9.6, null, 'HIGH', null, '["CWE-639"]', 'An improper authorization vulnerability in scoped user-to-server (ghu_) token authorization in GitHub Enterprise Server allows an authenticated attacker to access private repositories outside the intended installation scope, which can include write operations, via an authorization fallback that treated a revoked/deleted installation as a global installation context, which could be chained with token revocation timing and SSH push attribution to obtain and reuse a victim-scoped token. This vulnerability affected all versions of GitHub Enterprise Server prior to 3.21 and was fixed in versions 3.20.1, 3.19.5, 3.18.8, 3.17.14, 3.16.17, 3.15.21, and 3.14.26. This vulnerability was reported via the GitHub Bug Bounty program.', 'CVE-2026-5845', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5807', 'NVD', '2026-04-17 05:16:19', '2026-04-27 15:03:39', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5807', '["cpe:2.3:a:hashicorp:vault:*:*:*:*:-:*:*:*", "cpe:2.3:a:hashicorp:vault:*:*:*:*:enterprise:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-770"]', 'Vault is vulnerable to a denial-of-service condition where an unauthenticated attacker can repeatedly initiate or cancel root token generation or rekey operations, occupying the single in-progress operation slot. This prevents legitimate operators from completing these workflows. This vulnerability, CVE-2026-5807, is fixed in Vault Community Edition 2.0.0 and Vault Enterprise 2.0.0.', 'CVE-2026-5807', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5789', 'NVD', '2026-04-21 15:16:37', '2026-04-22 17:36:36', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5789', '["cpe:2.3:a:civetweb_project:civetweb:1.16:*:*:*:*:*:*:*"]', 8.5, 7.8, null, 'HIGH', null, '["CWE-428"]', 'Vulnerability related to an unquoted search path in CivetWeb v1.16. This vulnerability allows a local attacker to execute arbitrary code with elevated privileges by placing a malicious executable in a directory that is scanned before the intended application path (C:\\Program Files\\CivetWeb\\CivetWeb.exe --), due to the absence of quotes in the service configuration.', 'CVE-2026-5789', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5788', 'NVD', '2026-05-07 16:16:22', '2026-05-07 20:11:27', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5788', '["cpe:2.3:a:ivanti:endpoint_manager_mobile:*:*:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager_mobile:12.7.0.0:*:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager_mobile:12.8.0.0:*:*:*:*:*:*:*"]', null, 7, null, 'HIGH', null, '["CWE-284"]', 'An Improper Access Control in Ivanti EPMM before versions 12.6.1.1, 12.7.0.1, and 12.8.0.1 allows a remote unauthenticated attacker to invoke arbitrary methods.', 'CVE-2026-5788', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5787', 'NVD', '2026-05-07 16:16:22', '2026-05-07 20:12:18', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5787', '["cpe:2.3:a:ivanti:endpoint_manager_mobile:*:*:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager_mobile:12.7.0.0:*:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager_mobile:12.8.0.0:*:*:*:*:*:*:*"]', null, 8.9, null, 'HIGH', null, '["CWE-295"]', 'An Improper Certificate Validation in Ivanti EPMM before versions 12.6.1.1, 12.7.0.1, and 12.8.0.1 allows a remote unauthenticated attacker to impersonate registered Sentry hosts and obtain valid CA-signed client certificates.', 'CVE-2026-5787', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5786', 'NVD', '2026-05-07 16:16:22', '2026-05-07 20:12:47', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5786', '["cpe:2.3:a:ivanti:endpoint_manager_mobile:*:*:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager_mobile:12.7.0.0:*:*:*:*:*:*:*", "cpe:2.3:a:ivanti:endpoint_manager_mobile:12.8.0.0:*:*:*:*:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-284"]', 'An Improper Access Control vulnerability in Ivanti EPMM before versions 12.6.1.1, 12.7.0.1, and 12.8.0.1 allows a remote authenticated attacker to gain administrative access.', 'CVE-2026-5786', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5720', 'NVD', '2026-04-17 22:16:33', '2026-05-11 20:05:20', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5720', '["cpe:2.3:a:miniupnp_project:miniupnpd:*:*:*:*:*:*:*:*"]', 7.1, 9.1, null, 'HIGH', null, '["CWE-125", "CWE-191"]', 'miniupnpd contains an integer underflow vulnerability in SOAPAction header parsing that allows remote attackers to cause a denial of service or information disclosure by sending a malformed SOAPAction header with a single quote. Attackers can trigger an out-of-bounds memory read by exploiting improper length validation in ParseHttpHeaders(), where the parsed length underflows to a large unsigned value when passed to memchr(), causing the process to scan memory far beyond the allocated HTTP request buffer.', 'CVE-2026-5720', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5712', 'NVD', '2026-04-29 18:16:05', '2026-05-05 12:48:23', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5712', '["cpe:2.3:a:sailpoint:identityiq:*:*:*:*:*:*:*:*", "cpe:2.3:a:sailpoint:identityiq:8.3:-:*:*:*:*:*:*", "cpe:2.3:a:sailpoint:identityiq:8.3:patch1:*:*:*:*:*:*", "cpe:2.3:a:sailpoint:identityiq:8.3:patch2:*:*:*:*:*:*", "cpe:2.3:a:sailpoint:identityiq:8.3:patch4:*:*:*:*:*:*", "cpe:2.3:a:sailpoint:identityiq:8.4:-:*:*:*:*:*:*", "cpe:2.3:a:sailpoint:identityiq:8.4:patch1:*:*:*:*:*:*", "cpe:2.3:a:sailpoint:identityiq:8.4:patch2:*:*:*:*:*:*", "cpe:2.3:a:sailpoint:identityiq:8.5:-:*:*:*:*:*:*", "cpe:2.3:a:sailpoint:identityiq:8.5:patch1:*:*:*:*:*:*"]', null, 8, null, 'HIGH', null, '["CWE-863"]', 'This vulnerability impacts all versions of IdentityIQ and allows an authenticated identity that is the requestor or assignee of a work item to edit the definition of a role without having an assigned capability that would allow role editing.', 'CVE-2026-5712', null);
