INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5512', 'NVD', '2026-04-21 23:16:22', '2026-04-29 12:35:08', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5512', '["cpe:2.3:a:github:enterprise_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:github:enterprise_server:3.20.0:*:*:*:*:*:*:*"]', 5.3, 4.3, null, 'MEDIUM', null, '["CWE-201"]', 'An improper authorization vulnerability was identified in GitHub Enterprise Server that allowed an authenticated attacker to determine the names of private repositories by their numeric ID. The mobile upload policy API endpoint did not perform an early authorization check, and validation error messages included the full repository name for repositories the caller did not have access to. This vulnerability affected all versions of GitHub Enterprise Server prior to 3.21 and was fixed in versions 3.20.1, 3.19.5, 3.18.8, 3.17.14, 3.16.17, 3.15.21, and 3.14.26. This vulnerability was reported via the GitHub Bug Bounty program.', 'CVE-2026-5512', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5450', 'NVD', '2026-04-20 21:16:36', '2026-04-23 15:33:34', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5450', '["cpe:2.3:a:gnu:glibc:*:*:*:*:*:*:*:*"]', null, 9.8, null, 'CRITICAL', null, '["CWE-122", "CWE-787"]', 'Calling the scanf family of functions with a %mc (malloc\'d character match) in the GNU C Library version 2.7 to version 2.43 with a format width specifier with an explicit width greater than 1024 could result in a one byte heap buffer overflow.', 'CVE-2026-5450', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5435', 'NVD', '2026-04-28 13:19:22', '2026-05-05 17:38:37', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5435', '["cpe:2.3:a:gnu:glibc:*:*:*:*:*:*:*:*"]', null, 7.3, null, 'HIGH', null, '["CWE-787"]', 'The deprecated functions ns_printrrf, ns_printrr and fp_nquery in the GNU C Library version 2.2 and newer fail to enforce the caller-supplied buffer length, and can result in an out-of-bounds write when printing TSIG records.', 'CVE-2026-5435', null);
