INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5223', 'NVD', '2026-05-25 10:16:15', '2026-06-01 17:52:18', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5223', '["cpe:2.3:a:rust-lang:cargo:*:*:*:*:*:rust:*:*"]', 6.5, 5.3, null, 'MEDIUM', null, '["CWE-61"]', 'Cargo incorrectly handled symlinks inside of crate tarballs downloaded from third-party registries, allowing a malicious crate to override the source code of another crate from the same registry. The severity of the vulnerability is **medium** for users of third-party registries. Users of crates.io are **not affected**, as crates.io forbids uploading crates containing any symlink.', 'CVE-2026-5223', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5222', 'NVD', '2026-05-25 10:16:15', '2026-06-01 17:56:41', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5222', '["cpe:2.3:a:rust-lang:cargo:*:*:*:*:*:rust:*:*"]', 2.3, 6.5, null, 'LOW', null, '["CWE-647"]', 'Cargo between 1.68 and 1.96 incorrectly normalized the URLs of third-party registries using the sparse index protocol. If a hosting provider allowed multiple registries to be hosted with arbitrary names within the same domain, an attacker able to publish crates in a registry could obtain the credentials of others users of the same registry. The severity of the vulnerability is **low**, due to the extremely niche requirements needed to achieve the attack.', 'CVE-2026-5222', null);
