INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-5052', 'NVD', '2026-04-17 04:16:12', '2026-04-27 15:03:10', 'https://nvd.nist.gov/vuln/detail/CVE-2026-5052', '["cpe:2.3:a:hashicorp:vault:*:*:*:*:-:*:*:*", "cpe:2.3:a:hashicorp:vault:*:*:*:*:enterprise:*:*:*"]', null, 5.3, null, 'MEDIUM', null, '["CWE-918"]', 'Vault’s PKI engine’s ACME validation did not reject local targets when issuing http-01 and tls-alpn-01 challenges. This may lead to these requests being sent to local network targets, potentially leading to information disclosure. Fixed in Vault Community Edition 2.0.0 and Vault Enterprise 2.0.0, 1.21.5, 1.20.10, and 1.19.16.', 'CVE-2026-5052', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-50292', 'NVD', '2026-06-04 18:16:32', '2026-06-05 21:06:28', 'https://nvd.nist.gov/vuln/detail/CVE-2026-50292', '["cpe:2.3:a:freedesktop:libinput:*:*:*:*:*:*:*:*"]', null, 7.4, null, 'HIGH', null, '["CWE-93"]', 'In libinput before 1.30.4 and 1.31.x before 1.31.3, libinput-device-group unescaped phys output can inject udev properties leading to arbitrary root code execution', 'CVE-2026-50292', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-50259', 'NVD', '2026-06-05 12:16:39', '2026-06-08 18:28:43', 'https://nvd.nist.gov/vuln/detail/CVE-2026-50259', '["cpe:2.3:a:x.org:x_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:x.org:xwayland:*:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:10.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:7.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:8.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:9.0:*:*:*:*:*:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-121"]', 'A stack-based buffer overflow flaw was found in the X.Org X server and Xwayland. _XkbSetMapChecks() declares a fixed-size stack buffer mapWidths[256] indexed by key type index. The helper function CheckKeyTypes() writes to this buffer at a client-controlled offset, allowing a stack buffer overflow. This may be used to crash the server, or for privilege escalation if the X server runs as root.', 'CVE-2026-50259', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-50258', 'NVD', '2026-06-05 12:16:39', '2026-06-08 16:46:48', 'https://nvd.nist.gov/vuln/detail/CVE-2026-50258', '["cpe:2.3:a:x.org:x_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:x.org:xwayland:*:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:10.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:7.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:8.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:9.0:*:*:*:*:*:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-121"]', 'A stack-based buffer overflow flaw was found in the X.Org X server and Xwayland. The X server has multiple stack buffers sized XkbMaxShiftLevel * XkbNumKbdGroups but CheckKeyTypes() does not verify or clamp non-canonical key types to XkbMaxShiftLevel. A client can change key types to excessive shift levels and trigger stack overflows. This is caused by an incomplete fix of CVE-2025-26597. This may be used to crash the server, or for privilege escalation if the X server runs as root.', 'CVE-2026-50258', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-50257', 'NVD', '2026-06-05 12:16:38', '2026-06-08 16:45:56', 'https://nvd.nist.gov/vuln/detail/CVE-2026-50257', '["cpe:2.3:a:x.org:x_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:x.org:xwayland:*:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:10.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:7.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:8.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:9.0:*:*:*:*:*:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-416"]', 'A use-after-free flaw was found in the X.Org X server and Xwayland in miSyncDestroyFence(). A client that sets up multiple fence triggers can trigger a use-after-free function pointer call. An attacker would connect to the X server to set up a fence and await that fence, then a second X connection destroys the fence, causing the use-after-free. This may be used to crash the server, or for privilege escalation if the X server runs as root.', 'CVE-2026-50257', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-50256', 'NVD', '2026-06-05 12:16:38', '2026-06-08 16:45:14', 'https://nvd.nist.gov/vuln/detail/CVE-2026-50256', '["cpe:2.3:a:x.org:x_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:x.org:xwayland:*:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:10.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:7.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:8.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:9.0:*:*:*:*:*:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-121"]', 'A stack-based buffer overflow flaw was found in the X.Org X server and Xwayland. A mismatch between the X server and the libXfont2 library\'s maximum font name length can cause a stack buffer overflow during font alias resolution. The server allocates a 256 byte stack buffer but libXfont2\'s alias target name length is 1024 bytes. A font alias name between 257 and 1023 bytes causes the X server to copy that name into the undersized stack buffer without further checks. This may be used to crash the server, or for privilege escalation if the X server runs as root.', 'CVE-2026-50256', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-50219', 'NVD', '2026-06-04 06:16:25', '2026-06-04 18:39:29', 'https://nvd.nist.gov/vuln/detail/CVE-2026-50219', '["cpe:2.3:a:libexpat_project:libexpat:*:*:*:*:*:*:*:*"]', null, 4.9, null, 'MEDIUM', null, '["CWE-416"]', 'libexpat before 2.8.2 lacks handler call depth tracking for calls to XML_GetBuffer, XML_Parse, XML_ParseBuffer, XML_ParserFree, or XML_ParserReset from within handlers in cases of a policy violation. Thus, a use-after-free can occur,', 'CVE-2026-50219', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-49975', 'NVD', '2026-06-08 16:16:44', '2026-06-10 19:36:37', 'https://nvd.nist.gov/vuln/detail/CVE-2026-49975', '["cpe:2.3:a:apache:http_server:*:*:*:*:*:*:*:*", "cpe:2.3:a:f5:nginx:*:*:*:*:*:*:*:*", "cpe:2.3:o:debian:debian_linux:11.0:*:*:*:*:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-789"]', 'Memory Allocation with Excessive Size Value vulnerability in Apache HTTP Server\'s mod_http leads to denial of service via malicious HTTP requests.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-49848', 'NVD', '2026-06-09 17:17:48', '2026-06-10 15:06:53', 'https://nvd.nist.gov/vuln/detail/CVE-2026-49848', '["cpe:2.3:a:freeswitch:freeswitch:*:*:*:*:*:*:*:*"]', null, 4.3, null, 'MEDIUM', null, '["CWE-287"]', 'FreeSWITCH is a Software Defined Telecom Stack enabling the digital transformation from proprietary telecom switches to a software implementation that runs on any commodity hardware. Prior to version 1.11.1, mod_verto\'s check_auth userauth branch wrote request-supplied userVariables into the connection state before comparing the supplied password. The writes are append-only and the connection is not closed on a failed compare, so values declared on bad-password attempts persisted on the same WebSocket and carried into a subsequent successful login on that connection. This issue has been patched in version 1.11.1.', 'CVE-2026-49848', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-49847', 'NVD', '2026-06-09 17:17:48', '2026-06-10 15:06:45', 'https://nvd.nist.gov/vuln/detail/CVE-2026-49847', '["cpe:2.3:a:freeswitch:freeswitch:*:*:*:*:*:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-674"]', 'FreeSWITCH is a Software Defined Telecom Stack enabling the digital transformation from proprietary telecom switches to a software implementation that runs on any commodity hardware. Prior to version 1.11.1, a single unauthenticated WebSocket frame containing a deeply nested JSON document crashes the FreeSWITCH process via stack overflow, terminating all calls and sessions on the host. The recursion drives the worker thread\'s stack pointer into the stack guard page, raising SIGSEGV from the kernel before any usable write primitive develops. This issue has been patched in version 1.11.1.', 'CVE-2026-49847', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-49843', 'NVD', '2026-06-09 17:17:48', '2026-06-10 15:07:18', 'https://nvd.nist.gov/vuln/detail/CVE-2026-49843', '["cpe:2.3:a:freeswitch:freeswitch:*:*:*:*:*:*:*:*"]', null, 5.3, null, 'MEDIUM', null, '["CWE-287"]', 'FreeSWITCH is a Software Defined Telecom Stack enabling the digital transformation from proprietary telecom switches to a software implementation that runs on any commodity hardware. Prior to version 1.11.1, mod_verto\'s JSON-RPC handler bound the connection to the client-supplied sessid on the first frame, before the authentication gate. Binding inserts the connection into the global session hash and, on a key collision, drops the prior occupant of that slot — sending it a verto.punt, detaching its calls, and closing its socket. An unauthenticated network attacker who knows a target session UUID could therefore evict the legitimate client. This issue has been patched in version 1.11.1.', 'CVE-2026-49843', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-49842', 'NVD', '2026-06-09 17:17:48', '2026-06-10 15:06:33', 'https://nvd.nist.gov/vuln/detail/CVE-2026-49842', '["cpe:2.3:a:freeswitch:freeswitch:*:*:*:*:*:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-400"]', 'FreeSWITCH is a Software Defined Telecom Stack enabling the digital transformation from proprietary telecom switches to a software implementation that runs on any commodity hardware. Prior to version 1.11.1, mod_verto\'s WebSocket frame loop intercepts a #-prefixed speed-test protocol (#SPU / #SPB / #SPE) before any authentication check. The declared payload size in #SPU was parsed with atoi() and only rejected non-positive values, so an unauthenticated peer could request up to INT_MAX bytes. The server then wrote roughly size * 10 bytes back during the download phase, on the order of 20 GB per request, yielding strong outbound bandwidth amplification from a short request. This issue has been patched in version 1.11.1.', 'CVE-2026-49842', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-49841', 'NVD', '2026-06-09 17:17:47', '2026-06-10 15:07:23', 'https://nvd.nist.gov/vuln/detail/CVE-2026-49841', '["cpe:2.3:a:freeswitch:freeswitch:*:*:*:*:*:*:*:*"]', null, 9.8, null, 'CRITICAL', null, '["CWE-122", "CWE-131"]', 'FreeSWITCH is a Software Defined Telecom Stack enabling the digital transformation from proprietary telecom switches to a software implementation that runs on any commodity hardware. Prior to version 1.11.1, the mod_verto HTTP request handler allocates a fixed 2 MiB buffer for a POST application/x-www-form-urlencoded body but accepts Content-Length up to just under 10 MiB. The body-read loop is bounded by Content-Length rather than the buffer size, producing an attacker-controlled heap overflow of up to ~8 MiB -- before the HTTP basic-auth check runs. This issue has been patched in version 1.11.1.', 'CVE-2026-49841', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-49840', 'NVD', '2026-06-09 17:17:47', '2026-06-10 15:06:24', 'https://nvd.nist.gov/vuln/detail/CVE-2026-49840', '["cpe:2.3:a:freeswitch:freeswitch:*:*:*:*:*:*:*:*"]', null, 9.1, null, 'CRITICAL', null, '["CWE-20", "CWE-122", "CWE-195", "CWE-787"]', 'FreeSWITCH is a Software Defined Telecom Stack enabling the digital transformation from proprietary telecom switches to a software implementation that runs on any commodity hardware. Prior to version 1.11.1, esl_recv_event() parses Content-Length with atol() and passes the result straight to malloc(len + 1) with no sign or magnitude check. A malicious or man-in-the-middle ESL peer can send a frame with a negative Content-Length to corrupt the heap of, or crash, any process linked against libesl, before the client has authenticated to that peer. This issue has been patched in version 1.11.1.', 'CVE-2026-49840', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-49475', 'NVD', '2026-06-09 17:17:47', '2026-06-10 15:06:09', 'https://nvd.nist.gov/vuln/detail/CVE-2026-49475', '["cpe:2.3:a:freeswitch:freeswitch:*:*:*:*:*:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-20", "CWE-125", "CWE-787"]', 'FreeSWITCH is a Software Defined Telecom Stack enabling the digital transformation from proprietary telecom switches to a software implementation that runs on any commodity hardware. Prior to version 1.11.0, a STUN packet whose declared attribute length is shorter than the structure the parser casts to causes the parser to read and write past the end of the attribute, producing an out-of-bounds memory access on the per-leg media buffer. This issue has been patched in version 1.11.0.', 'CVE-2026-49475', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-49472', 'NVD', '2026-06-09 17:17:47', '2026-06-10 15:06:00', 'https://nvd.nist.gov/vuln/detail/CVE-2026-49472', '["cpe:2.3:a:freeswitch:freeswitch:*:*:*:*:*:*:*:*"]', null, 5.3, null, 'MEDIUM', null, '["CWE-116"]', 'FreeSWITCH is a Software Defined Telecom Stack enabling the digital transformation from proprietary telecom switches to a software implementation that runs on any commodity hardware. Prior to version 1.11.0, FreeSWITCH includes a vulnerable function, PREFIX(prologTok)(), in libs/xmlrpc-c/lib/expat/xmltok/xmltok_impl.c, which was cloned from an outdated and vulnerable version in libexpat/libexpat. The function did not receive the corresponding security patch. This issue has been patched in version 1.11.0.', 'CVE-2026-49472', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-49448', 'NVD', '2026-06-02 21:16:28', '2026-06-04 20:16:33', 'https://nvd.nist.gov/vuln/detail/CVE-2026-49448', '["cpe:2.3:a:goauthentik:authentik:*:*:*:*:*:*:*:*"]', null, 9.8, null, 'CRITICAL', null, '["CWE-287"]', 'authentik is an open-source identity provider. Prior to versions 2025.12.6, 2026.2.4, and 2026.5.1, the Source stage can be bypassed by sending an empty POST. This issue has been patched in versions 2025.12.6, 2026.2.4, and 2026.5.1.', 'CVE-2026-49448', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-49443', 'NVD', '2026-06-02 21:16:28', '2026-06-04 20:16:00', 'https://nvd.nist.gov/vuln/detail/CVE-2026-49443', '["cpe:2.3:a:goauthentik:authentik:*:*:*:*:*:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-287"]', 'authentik is an open-source identity provider. Prior to versions 2025.12.6, 2026.2.4, and 2026.5.1, an attacker with the ability to change a source connection, and an account in one of the configured sources can log into any account. This issue has been patched in versions 2025.12.6, 2026.2.4, and 2026.5.1.', 'CVE-2026-49443', null);
