INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-49238', 'NVD', '2026-05-28 14:16:24', '2026-06-01 13:26:31', 'https://nvd.nist.gov/vuln/detail/CVE-2026-49238', '["cpe:2.3:a:canonical:multipass:*:*:*:*:*:*:*:*"]', null, 8.4, null, 'HIGH', null, '["CWE-22"]', 'An issue was discovered in Canonical Multipass before version 1.16.3. The host-side SFTP server component (sshfs_server), which executes with root privileges on the host, contains a path containment bypass vulnerability within its validate_path function in src/sshfs_mount/sftp_server.cpp. The function performs a plain string prefix comparison on requested paths without path separator validation or dot-dot (..) normalization. A local attacker with root privileges inside a guest virtual machine can bypass the FUSE layer by injecting raw SFTP frames (such as an SSH_FXP_OPEN request) directly into the sshfs_server process stdin/stdout pipes via procfs. By supplying a path containing directory traversal sequences that match the allowed mount prefix, the attacker can force the host-side root process to resolve the traversal and open files outside the designated mount boundary. This allows a guest-side user to read arbitrary files on the host filesystem, resulting in a virtual machine escape.', 'CVE-2026-49238', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-49237', 'NVD', '2026-05-28 14:16:24', '2026-06-01 13:27:32', 'https://nvd.nist.gov/vuln/detail/CVE-2026-49237', '["cpe:2.3:a:canonical:multipass:*:*:*:*:*:*:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-276"]', 'An issue was discovered in Canonical Multipass for macOS before version 1.16.3 due to an incomplete fix for CVE-2025-5199. While the patch in version 1.16.0 updated the ownership of the multipassd daemon binary to root:wheel, five co-located binaries (multipass, qemu-img, qemu-system-aarch64, qemu-system-x86_64, and sshfs_server) in /Library/Application Support/com.canonical.multipass/bin/ retain ownership by the installing user and remain writable. Because the root LaunchDaemon (com.canonical.multipassd.plist) configures a PATH environment variable that prioritizes this user-writable directory and invokes these auxiliary binaries by their bare names, a local attacker can replace an auxiliary binary (such as qemu-img) with a malicious wrapper. When the root daemon subsequently triggers the binary during routine execution (e.g., via multipass launch), the malicious code executes with root privileges, leading to local privilege escalation.', 'CVE-2026-49237', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48927', 'NVD', '2026-05-27 15:16:32', '2026-05-28 16:52:13', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48927', '["cpe:2.3:a:jenkins:buildgraph-view:*:*:*:*:*:jenkins:*:*"]', null, 5.5, null, 'MEDIUM', null, '["CWE-79"]', 'Jenkins buildgraph-view Plugin 1.8 and earlier does not escape the build URL, resulting in a stored cross-site scripting (XSS) vulnerability exploitable by attackers able to configure jobs or views.', 'CVE-2026-48927', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48926', 'NVD', '2026-05-27 15:16:32', '2026-06-02 14:49:10', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48926', '["cpe:2.3:a:jenkins:job_import:*:*:*:*:*:jenkins:*:*", "cpe:2.3:a:jenkins:job_import:143.v044a_2e819b_27:*:*:*:*:jenkins:*:*"]', null, 4.3, null, 'MEDIUM', null, '["CWE-269"]', 'Jenkins Job Import Plugin 143.v044a_2e819b_27 and earlier does not perform a permission check in an HTTP endpoint, allowing attackers with Overall/Read permission to enumerate credentials IDs of credentials stored in Jenkins.', 'CVE-2026-48926', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48924', 'NVD', '2026-05-27 15:16:32', '2026-05-28 16:59:48', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48924', '["cpe:2.3:a:jenkins:bitbucket_oauth:*:*:*:*:*:jenkins:*:*"]', null, 4.3, null, 'MEDIUM', null, '["CWE-601"]', 'Jenkins Bitbucket OAuth Plugin 0.17 and earlier does not restrict the redirect URL after login, allowing attackers to perform phishing attacks.', 'CVE-2026-48924', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48923', 'NVD', '2026-05-27 15:16:31', '2026-05-28 17:01:11', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48923', '["cpe:2.3:a:jenkins:appspider:*:*:*:*:*:jenkins:*:*"]', null, 4.3, null, 'MEDIUM', null, '["CWE-269"]', 'Jenkins AppSpider Plugin 1.0.17 and earlier does not perform a permission check in a method implementing form validation, allowing attackers with Overall/Read permission to connect to an attacker-specified URL.', 'CVE-2026-48923', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48922', 'NVD', '2026-05-27 15:16:31', '2026-05-28 17:01:49', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48922', '["cpe:2.3:a:jenkins:credentials_binding:*:*:*:*:*:jenkins:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-20"]', 'Jenkins Credentials Binding Plugin 720.v3f6decef43ea_ and earlier does not properly sanitize file names for file and zip file credentials, allowing attackers able to provide credentials to a job to write files to arbitrary locations on the node filesystem, which can lead to remote code execution if Jenkins is configured to allow a low-privileged user to configure file or zip file credentials used for a job running on the built-in node.', 'CVE-2026-48922', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48920', 'NVD', '2026-05-27 15:16:31', '2026-05-28 17:14:10', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48920', '["cpe:2.3:a:jenkins:email_extension:*:*:*:*:*:jenkins:*:*", "cpe:2.3:a:jenkins:email_extension:1933.v45cec755423f:*:*:*:*:jenkins:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-73"]', 'Jenkins Email Extension Plugin 1933.v45cec755423f and earlier allows inlining images as `base64` in email content by setting the `data-inline` attribute, without restrictions on the image URLs that can be inlined, allowing attackers able to control the email content to specify `file:` URLs for images to read arbitrary files from the Jenkins controller filesystem.', 'CVE-2026-48920', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48919', 'NVD', '2026-05-27 15:16:31', '2026-05-28 17:14:34', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48919', '["cpe:2.3:a:jenkins:active_directory:*:*:*:*:*:jenkins:*:*"]', null, 6.6, null, 'MEDIUM', null, '["CWE-502"]', 'Jenkins Active Directory Plugin 2.41 and earlier deserializes data from LDAP referrals without validation.', 'CVE-2026-48919', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48918', 'NVD', '2026-05-27 15:16:31', '2026-05-28 17:17:38', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48918', '["cpe:2.3:a:jenkins:active_directory:*:*:*:*:*:jenkins:*:*"]', null, 6.6, null, 'MEDIUM', null, '["CWE-918"]', 'Jenkins Active Directory Plugin 2.41 and earlier follows LDAP referrals by default.', 'CVE-2026-48918', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48864', 'NVD', '2026-05-26 17:16:54', '2026-05-28 19:22:42', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48864', '["cpe:2.3:a:opensuse:libsolv:0.7.36:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:hardened_images:-:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:openshift_container_platform:4.0:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:satellite:6.0:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:update_infrastructure:4:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:10.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:7.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:8.0:*:*:*:*:*:*:*", "cpe:2.3:o:redhat:enterprise_linux:9.0:*:*:*:*:*:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-787"]', 'A flaw was found in libsolv. This heap buffer overflow occurs during the decompression of attacker-controlled compressed data within `.solv` files due to insufficient input validation. An attacker can provide a specially crafted `.solv` file, which, when processed by a vulnerable application, can lead to out-of-bounds memory access. This could result in information disclosure, alteration of program execution, or a denial of service.', 'CVE-2026-48864', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48840', 'NVD', '2026-05-30 02:16:19', '2026-06-05 11:16:36', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48840', '["cpe:2.3:a:exim:exim:*:*:*:*:*:*:*:*"]', null, 5.3, null, 'MEDIUM', null, '["CWE-839"]', 'Exim 4.88 before 4.99.4, in some proxy configurations, mishandles certain short payloads, leading to disclosure of uninitialized stack memory values to a client.', 'CVE-2026-48840', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48507', 'NVD', '2026-06-08 17:16:52', '2026-06-09 16:41:26', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48507', '["cpe:2.3:a:snipeitapp:snipe-it:*:*:*:*:*:*:*:*"]', null, 7.1, null, 'HIGH', null, '["CWE-863"]', 'Snipe-IT is an IT asset/license management system. A vulnerability in versions prior to 8.6.0 allows a non-admin user holding only the granular `users.edit` permission to lock every admin out of the instance  by editing the `activated` flag (which determines whether or not a user can login) and the `ldap_import` flag, which determines whether or not the user can request a password reset. Version 8.6.0 contains a patch.', 'CVE-2026-48507', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48304', 'NVD', '2026-06-09 17:17:44', '2026-06-10 14:45:58', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48304', '["cpe:2.3:a:adobe:experience_manager:*:*:*:*:-:*:*:*", "cpe:2.3:a:adobe:experience_manager:*:*:*:*:aem_cloud_service:*:*:*", "cpe:2.3:a:adobe:experience_manager:6.5:-:*:*:lts:*:*:*", "cpe:2.3:a:adobe:experience_manager:6.5:sp1:*:*:lts:*:*:*"]', null, 5.4, null, 'MEDIUM', null, '["CWE-79"]', 'Adobe Experience Manager versions 6.5.24, LTS SP1, 2026.04 and earlier are affected by a stored Cross-Site Scripting (XSS) vulnerability that could be abused by a low-privileged attacker to inject malicious scripts into vulnerable form fields. Malicious JavaScript may be executed in a victim\'s browser when they browse to the page containing the vulnerable field. Scope is changed.', 'CVE-2026-48304', null);
