INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48288', 'NVD', '2026-06-09 17:17:43', '2026-06-10 14:48:25', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48288', '["cpe:2.3:a:adobe:experience_manager:*:*:*:*:-:*:*:*", "cpe:2.3:a:adobe:experience_manager:*:*:*:*:aem_cloud_service:*:*:*", "cpe:2.3:a:adobe:experience_manager:6.5:-:*:*:lts:*:*:*", "cpe:2.3:a:adobe:experience_manager:6.5:sp1:*:*:lts:*:*:*"]', null, 3.5, null, 'LOW', null, '["CWE-20"]', 'Adobe Experience Manager versions 6.5.24, LTS SP1, 2026.04 and earlier are affected by an Improper Input Validation vulnerability that could result in a Security feature bypass. A low-privileged attacker could leverage this vulnerability to bypass security measures and gain unauthorized write access. Exploitation of this issue requires user interaction in that a victim must visit a maliciously crafted URL or interact with a compromised web page.', 'CVE-2026-48288', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-48280', 'NVD', '2026-06-09 17:17:43', '2026-06-10 14:48:42', 'https://nvd.nist.gov/vuln/detail/CVE-2026-48280', '["cpe:2.3:a:adobe:experience_manager:*:*:*:*:-:*:*:*", "cpe:2.3:a:adobe:experience_manager:*:*:*:*:aem_cloud_service:*:*:*", "cpe:2.3:a:adobe:experience_manager:6.5:-:*:*:lts:*:*:*", "cpe:2.3:a:adobe:experience_manager:6.5:sp1:*:*:lts:*:*:*"]', null, 5.4, null, 'MEDIUM', null, '["CWE-79"]', 'Adobe Experience Manager versions 6.5.24, LTS SP1, 2026.04 and earlier are affected by a DOM-based Cross-Site Scripting (XSS) vulnerability. An attacker could exploit this issue by manipulating the DOM environment to execute malicious JavaScript within the context of the victim\'s browser. Exploitation of this issue requires user interaction in that a victim must visit a crafted webpage. Scope is changed.', 'CVE-2026-48280', null);
