INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-47935', 'NVD', '2026-06-09 17:17:37', '2026-06-10 15:08:40', 'https://nvd.nist.gov/vuln/detail/CVE-2026-47935', '["cpe:2.3:a:adobe:experience_manager:*:*:*:*:-:*:*:*", "cpe:2.3:a:adobe:experience_manager:*:*:*:*:aem_cloud_service:*:*:*", "cpe:2.3:a:adobe:experience_manager:6.5:-:*:*:lts:*:*:*", "cpe:2.3:a:adobe:experience_manager:6.5:sp1:*:*:lts:*:*:*"]', null, 5.4, null, 'MEDIUM', null, '["CWE-79"]', 'Adobe Experience Manager versions 6.5.24, LTS SP1, 2026.04 and earlier are affected by a DOM-based Cross-Site Scripting (XSS) vulnerability. An attacker could exploit this issue by manipulating the DOM environment to execute malicious JavaScript within the context of the victim\'s browser. Exploitation of this issue requires user interaction in that a victim must visit a crafted webpage. Scope is changed.', 'CVE-2026-47935', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-47784', 'NVD', '2026-05-20 07:16:15', '2026-05-21 17:06:33', 'https://nvd.nist.gov/vuln/detail/CVE-2026-47784', '["cpe:2.3:a:memcached:memcached:*:*:*:*:*:*:*:*"]', null, 8.1, null, 'HIGH', null, '["CWE-208"]', 'In memcached before 1.6.42, password data for SASL password database authentication has a timing side channel because memcmp is used by sasl_server_userdb_checkpass.', 'CVE-2026-47784', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-47783', 'NVD', '2026-05-20 07:16:15', '2026-05-21 17:06:40', 'https://nvd.nist.gov/vuln/detail/CVE-2026-47783', '["cpe:2.3:a:memcached:memcached:*:*:*:*:*:*:*:*"]', null, 8.1, null, 'HIGH', null, '["CWE-208"]', 'In memcached before 1.6.42, username data for SASL password database authentication has a timing side channel because a loop exits as soon as a valid username is found by sasl_server_userdb_checkpass.', 'CVE-2026-47783', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-47713', 'NVD', '2026-05-28 22:17:01', '2026-06-03 16:51:22', 'https://nvd.nist.gov/vuln/detail/CVE-2026-47713', '["cpe:2.3:a:mintplexlabs:anythingllm:*:*:*:*:*:*:*:*"]', null, 2, null, 'LOW', null, '["CWE-285", "CWE-639"]', 'AnythingLLM is an application that turns pieces of content into context that any LLM can use as references during chatting. Prior to 1.13.0, an approved mobile device token created in single-user mode can survive single-user -> multi-user migration even when the device record has userId = null. In multi-user mode, that stale token is still accepted by the mobile authentication middleware. Because no user is attached to the request, downstream mobile handlers fall back to unscoped data-access branches and return workspaces and workspace content without per-user filtering. This permits a pre-migration mobile token to enumerate a workspace assigned only to another user and retrieve victim-owned thread metadata and chat content in multi-user mode. This vulnerability is fixed in 1.13.0.', 'CVE-2026-47713', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-47696', 'NVD', '2026-05-29 14:16:32', '2026-06-01 18:38:28', 'https://nvd.nist.gov/vuln/detail/CVE-2026-47696', '["cpe:2.3:a:wwbn:avideo:*:*:*:*:*:*:*:*"]', 7.1, 4.3, null, 'HIGH', null, '["CWE-345"]', 'WWBN AVideo is an open source video platform. In 29.0 and earlier, plugin/AuthorizeNet/processPayment.json.php credits the logged-in user\'s wallet based only on the attacker-controlled amount POST parameter. The endpoint contains a TODO for real Authorize.Net charging, hardcodes $paymentSuccess = true, and then calls YPTWallet::addBalance() without validating
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-47694', 'NVD', '2026-05-29 14:16:31', '2026-06-01 18:38:37', 'https://nvd.nist.gov/vuln/detail/CVE-2026-47694', '["cpe:2.3:a:wwbn:avideo:*:*:*:*:*:*:*:*"]', null, 5.4, null, 'MEDIUM', null, '["CWE-79"]', 'WWBN AVideo is an open source video platform. In 29.0 and earlier, AVideo stores category descriptions from user input and later renders category_description as raw HTML in the Gallery view. A user who can create or edit categories can store JavaScript in a category description, which executes when another user views the affected Gallery/category page. This is a stored XSS in the category description field, separate from previously fixed XSS issues in video titles or comments.', 'CVE-2026-47694', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-47641', 'NVD', '2026-06-09 17:17:36', '2026-06-10 15:59:52', 'https://nvd.nist.gov/vuln/detail/CVE-2026-47641', '["cpe:2.3:a:microsoft:sharepoint_server:*:*:*:*:subscription:*:*:*", "cpe:2.3:a:microsoft:sharepoint_server:2016:*:*:*:enterprise:*:*:*", "cpe:2.3:a:microsoft:sharepoint_server:2019:*:*:*:*:*:*:*"]', null, 4.6, null, 'MEDIUM', null, '["CWE-20"]', 'Improper neutralization of input during web page generation (\'cross-site scripting\') in Microsoft Office SharePoint allows an authorized attacker to perform spoofing over a network.', 'CVE-2026-47641', null);
