INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-47294', 'NVD', '2026-06-01 19:16:53', '2026-06-03 18:42:52', 'https://nvd.nist.gov/vuln/detail/CVE-2026-47294', '["cpe:2.3:a:microsoft:sharepoint_server:*:*:*:*:subscription:*:*:*", "cpe:2.3:a:microsoft:sharepoint_server:2016:*:*:*:enterprise:*:*:*", "cpe:2.3:a:microsoft:sharepoint_server:2019:*:*:*:*:*:*:*"]', null, 8, null, 'HIGH', null, '["CWE-78"]', 'Deserialization of untrusted data in Microsoft Office SharePoint allows an authorized attacker to execute code over a network.', 'CVE-2026-47294', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-47265', 'NVD', '2026-06-02 20:16:37', '2026-06-05 13:39:20', 'https://nvd.nist.gov/vuln/detail/CVE-2026-47265', '["cpe:2.3:a:aiohttp:aiohttp:*:*:*:*:*:*:*:*"]', 6.6, 7.5, null, 'MEDIUM', null, '["CWE-346"]', 'AIOHTTP is an asynchronous HTTP client/server framework for asyncio and Python. Prior to version 3.14.0, cookies set with the `cookies` parameter on requests are sent after following a cross-origin redirect. If a developer uses the `cookies` parameter on a per-request basis then sensitive data might be leaked to an attacker if they manage to control a redirect. Version 3.14.0 patches the issue. If unable to upgrade, using a `Cookie` header in the `headers` parameter is not vulnerable.', 'CVE-2026-47265', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-47201', 'NVD', '2026-06-02 21:16:27', '2026-06-04 20:14:17', 'https://nvd.nist.gov/vuln/detail/CVE-2026-47201', '["cpe:2.3:a:goauthentik:authentik:*:*:*:*:*:*:*:*"]', null, 8.5, null, 'HIGH', null, '["CWE-20", "CWE-347"]', 'authentik is an open-source identity provider. Prior to versions 2025.12.5, 2026.2.3, and 2026.5.1, authentik\'s SAML Source ACS endpoint is vulnerable to XML Signature Wrapping when validating upstream SAML responses. An attacker with any account at the upstream IdP can reuse a valid signed assertion to authenticate as another federated user. This issue has been patched in versions 2025.12.5, 2026.2.3, and 2026.5.1.', 'CVE-2026-47201', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-46837', 'NVD', '2026-05-28 21:16:33', '2026-06-04 13:46:40', 'https://nvd.nist.gov/vuln/detail/CVE-2026-46837', '["cpe:2.3:a:oracle:e-business_suite:*:*:*:*:*:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-269"]', 'Vulnerability in the Oracle Flow Manufacturing product of Oracle E-Business Suite (component: Security).  Supported versions that are affected are 12.2.9-12.2.15. Easily exploitable vulnerability allows low privileged attacker with network access via SQL to compromise Oracle Flow Manufacturing.  Successful attacks of this vulnerability can result in takeover of Oracle Flow Manufacturing. CVSS 3.1 Base Score 8.8 (Confidentiality, Integrity and Availability impacts).  CVSS Vector: (CVSS:3.1/AV:N/AC:L/PR:L/UI:N/S:U/C:H/I:H/A:H).', 'CVE-2026-46837', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-46835', 'NVD', '2026-05-28 21:16:33', '2026-06-03 19:00:41', 'https://nvd.nist.gov/vuln/detail/CVE-2026-46835', '["cpe:2.3:a:oracle:database_server:*:*:*:*:*:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-400"]', 'Vulnerability in the Net Service component of Oracle Database Server.  Supported versions that are affected are 23.4.0-23.26.2. Easily exploitable vulnerability allows unauthenticated attacker with network access via TLS to compromise Net Service.  Successful attacks of this vulnerability can result in unauthorized ability to cause a hang or frequently repeatable crash (complete DOS) of Net Service. CVSS 3.1 Base Score 7.5 (Availability impacts).  CVSS Vector: (CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:N/A:H).', 'CVE-2026-46835', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-46834', 'NVD', '2026-05-28 21:16:33', '2026-06-03 18:57:48', 'https://nvd.nist.gov/vuln/detail/CVE-2026-46834', '["cpe:2.3:a:oracle:database_server:*:*:*:*:*:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-400"]', 'Vulnerability in the Net Service component of Oracle Database Server.  Supported versions that are affected are 23.4.0-23.26.2. Easily exploitable vulnerability allows unauthenticated attacker with network access via TLS to compromise Net Service.  Successful attacks of this vulnerability can result in unauthorized ability to cause a hang or frequently repeatable crash (complete DOS) of Net Service. CVSS 3.1 Base Score 7.5 (Availability impacts).  CVSS Vector: (CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:N/A:H).', 'CVE-2026-46834', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-46833', 'NVD', '2026-05-28 21:16:33', '2026-06-03 18:12:21', 'https://nvd.nist.gov/vuln/detail/CVE-2026-46833', '["cpe:2.3:a:oracle:database_server:*:*:*:*:*:*:*:*"]', null, 9, null, 'CRITICAL', null, null, 'Vulnerability in the Net Service component of Oracle Database Server.  Supported versions that are affected are 23.4.0-23.26.2. Difficult to exploit vulnerability allows unauthenticated attacker with network access via TLS to compromise Net Service.  While the vulnerability is in Net Service, attacks may significantly impact additional products (scope change).  Successful attacks of this vulnerability can result in takeover of Net Service. CVSS 3.1 Base Score 9.0 (Confidentiality, Integrity and Availability impacts).  CVSS Vector: (CVSS:3.1/AV:N/AC:H/PR:N/UI:N/S:C/C:H/I:H/A:H).', 'CVE-2026-46833', null);
