INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-46727', 'NVD', '2026-05-22 18:16:22', '2026-05-26 14:22:08', 'https://nvd.nist.gov/vuln/detail/CVE-2026-46727', '["cpe:2.3:a:ruby-lang:ruby:*:*:*:*:*:*:*:*"]', null, 8.1, null, 'HIGH', null, '["CWE-362"]', 'An issue was discovered in Ruby 4 before 4.0.5. A race condition leading to a use-after-free in the pthread-based getaddrinfo timeout handler (rb_getaddrinfo in ext/socket/raddrinfo.c) allows a remote attacker who can delay DNS responses near the user-specified timeout to crash a Ruby process that calls Addrinfo.getaddrinfo(..., timeout:) or Socket.tcp(..., resolv_timeout:). Memory-corruption-based exploitation is theoretically possible. The attack could, for example, be carried out through a crafted authoritative DNS server or recursive resolver.', 'CVE-2026-46727', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-4670', 'NVD', '2026-04-30 16:16:44', '2026-05-04 18:20:39', 'https://nvd.nist.gov/vuln/detail/CVE-2026-4670', '["cpe:2.3:a:progress:moveit_automation:*:*:*:*:*:*:*:*"]', null, 9.8, null, 'CRITICAL', null, '["CWE-305"]', 'Authentication bypass by primary weakness vulnerability in Progress Software MOVEit Automation allows Authentication Bypass.
