INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-46597', 'NVD', '2026-05-22 04:16:26', '2026-05-28 14:44:17', 'https://nvd.nist.gov/vuln/detail/CVE-2026-46597', '["cpe:2.3:a:golang:crypto:*:*:*:*:*:go:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-704"]', 'An incorrectly placed cast from bytes to int allowed for server-side panic in the AES-GCM packet decoder for well-crafted inputs.', 'CVE-2026-46597', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-46595', 'NVD', '2026-05-22 04:16:25', '2026-05-28 14:44:43', 'https://nvd.nist.gov/vuln/detail/CVE-2026-46595', '["cpe:2.3:a:golang:crypto:*:*:*:*:*:go:*:*"]', null, 10, null, 'CRITICAL', null, '["CWE-863"]', 'Previously, CVE-2024-45337 fixed an authorization bypass for misused ssh server configurations; if any other type of callback is passed other than public key, then the source-address validation would be skipped.', 'CVE-2026-46595', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-46586', 'NVD', '2026-05-19 10:16:24', '2026-05-20 17:16:25', 'https://nvd.nist.gov/vuln/detail/CVE-2026-46586', '["cpe:2.3:a:apache:ofbiz:*:*:*:*:*:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-94", "CWE-95"]', 'Improper Control of Generation of Code (\'Code Injection\'), Improper Neutralization of Directives in Dynamically Evaluated Code (\'Eval Injection\') vulnerability in Apache OFBiz.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-46579', 'NVD', '2026-05-29 11:16:17', '2026-06-08 14:23:54', 'https://nvd.nist.gov/vuln/detail/CVE-2026-46579', '["cpe:2.3:a:redhat:openshift_container_platform:4.0:*:*:*:*:*:*:*", "cpe:2.3:a:redhat:openshift_router:-:*:*:*:*:*:*:*"]', null, 7.4, null, 'HIGH', null, '["CWE-287"]', 'A flaw was found in the OpenShift Router. When a Route has `insecureEdgeTerminationPolicy` set to Allow, the HTTP frontend does not remove `X-SSL-Client-*` headers from incoming requests. This allows an unauthenticated attacker to send plain HTTP requests with crafted `X-SSL-Client-*` headers. As a result, backends relying on these headers for mutual TLS (Transport Layer Security) authentication can be bypassed, enabling the attacker to impersonate client certificate identities.', 'CVE-2026-46579', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-46490', 'NVD', '2026-06-08 19:16:45', '2026-06-09 16:48:56', 'https://nvd.nist.gov/vuln/detail/CVE-2026-46490', '["cpe:2.3:a:samlify_project:samlify:*:*:*:*:*:*:*:*"]', 8.7, 8.8, null, 'HIGH', null, '["CWE-91"]', 'samlify is a Node.js library for SAML single sign-on. Prior to version 2.13.0, samlify’s template substitution only escapes attribute contexts. Values inserted into element text (e.g., <saml:AttributeValue>) are not escaped. A normal user can inject XML markup into an attribute value (e.g., email, name) and add new <saml:Attribute> elements inside the signed assertion. The IdP then signs the tampered assertion and the SP accepts the injected attributes as trusted. This allows privilege escalation when attributes are used for authorization (roles/groups). This issue has been patched in version 2.13.0.', 'CVE-2026-46490', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-46376', 'NVD', '2026-05-29 14:16:31', '2026-06-01 18:38:48', 'https://nvd.nist.gov/vuln/detail/CVE-2026-46376', '["cpe:2.3:a:sangoma:freepbx:*:*:*:*:*:*:*:*"]', 9.3, 9.8, null, 'CRITICAL', null, '["CWE-798"]', 'FreePBX is an open source IP PBX. From 15.0.42 to before 16.0.45 and 17.0.7, unauthenticated users may be able to access the User Control Panel (UCP) using hard-coded initial template credentials if these were not immediately changed by the Administrator who enabled UCP. Authenticated access to ACP is required for the initial setup of UCP generic templates, but after that, without further steps by the admin, unauthenticated users may be able to gain access. This vulnerability is fixed in 16.0.45 and 17.0.7.', 'CVE-2026-46376', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-46337', 'NVD', '2026-05-29 14:16:31', '2026-06-01 18:39:10', 'https://nvd.nist.gov/vuln/detail/CVE-2026-46337', '["cpe:2.3:a:wwbn:avideo:*:*:*:*:*:*:*:*"]', 6.9, 5.3, null, 'MEDIUM', null, '["CWE-22"]', 'WWBN AVideo is an open source video platform. In 29.0 and earlier, an unauthenticated remote attacker can read arbitrary image files anywhere on disk that the PHP user can open — including private user-profile photos that the application\'s normal serving wrappers gate behind ACLs, admin-uploaded thumbnails, encrypted-video poster frames, and image content under sibling-app directories reachable via .. traversal. The endpoint requires no authentication.', 'CVE-2026-46337', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45779', 'NVD', '2026-06-05 20:17:33', '2026-06-10 21:04:01', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45779', '["cpe:2.3:a:buffalo:open_xdmod:*:*:*:*:*:*:*:*"]', 9.3, 9.8, null, 'CRITICAL', null, '["CWE-89"]', 'OpenXDMoD is an open framework for collecting and analyzing HPC metrics. An SQL injection vulnerability exists in Open XDMoD versions prior to 10.0.3 that allows an unauthenticated remote attacker to execute arbitrary SQL statements. Exploitation requires no authentication or user interaction and can result in complete compromise of the underlying database. All deployments of Open XDMoD prior to 10.0.3 are impacted. This issue was discovered on 2023-08-03 and patched on 2023-08-04. At this time there is no evidence that this vulnerability has been exploited in the wild. The vulnerability was patched in Open XDMoD 10.0.3 on 2023-08-04. As a workaround, apply the patch manually.', 'CVE-2026-45779', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45778', 'NVD', '2026-06-05 20:17:32', '2026-06-10 21:05:23', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45778', '["cpe:2.3:a:buffalo:open_xdmod:*:*:*:*:*:*:*:*"]', 8.6, 5.4, null, 'HIGH', null, '["CWE-79"]', 'OpenXDMoD is an open framework for collecting and analyzing HPC metrics. Prior to version 11.0.3, an authenticated attacker can inject malicious JavaScript into their Open XDMoD user profile and abuse the password reset functionality to email a link to an HTML page, which when visited by the victim, reflects and executes the unsanitized payload in the victim\'s browser, potentially leading to credential capture and Open XDMoD account takeover. All deployments of Open XDMoD prior to 11.0.3 are impacted. This issue was reported privately on 2026-04-06, and at this time there is no evidence that this vulnerability has been exploited in the wild. The vulnerability was patched in Open XDMoD 11.0.3 on 2026-05-12. As a workaround, apply the patch manually.', 'CVE-2026-45778', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45777', 'NVD', '2026-06-05 20:17:32', '2026-06-10 21:06:27', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45777', '["cpe:2.3:a:buffalo:open_xdmod:*:*:*:*:*:*:*:*"]', 9.3, 9.8, null, 'CRITICAL', null, '["CWE-78"]', 'OpenXDMoD is an open framework for collecting and analyzing HPC metrics. Starting in version 9.5.0 and prior to version 11.0.3, an attacker can remotely execute arbitrary system commands on the web server hosting Open XDMoD with the privileges of the web server process. This could allow an attacker to read or modify application data, alter system configuration, or disrupt service availability. All deployments of Open XDMoD versions 9.5.0 through 11.0.2 (inclusive) are impacted. This issue was reported privately on 2026-04-06, and at this time there is no evidence that this vulnerability has been exploited in the wild. The vulnerability was patched in Open XDMoD 11.0.3 on 2026-05-12. As a workaround, apply the patch manually.', 'CVE-2026-45777', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45776', 'NVD', '2026-06-05 20:17:32', '2026-06-10 21:07:23', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45776', '["cpe:2.3:a:buffalo:open_xdmod:*:*:*:*:*:*:*:*"]', 5.3, 4.3, null, 'MEDIUM', null, '["CWE-284"]', 'OpenXDMoD is an open framework for collecting and analyzing HPC metrics. Prior to version 11.0.3, a flaw in Open XDMoD\'s access control logic allows an attacker to submit a crafted HTTPS POST request that sets a session variable used for authorization decisions. If an installation of Open XDMoD includes the optional Job Performance (SUPReMM) module, an attacker could bypass intended data access restrictions and view other users\' compute job efficiency metrics. All deployments of Open XDMoD prior to version 11.0.3 that contain the optional Job Performance (SUPReMM) module are impacted. This issue was reported privately on 2026-04-06, and at this time there is no evidence that this vulnerability has been exploited in the wild. The vulnerability was patched in Open XDMoD 11.0.3 on 2026-05-12. As a workaround, apply the patch manually.', 'CVE-2026-45776', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45771', 'NVD', '2026-06-09 17:17:33', '2026-06-10 15:04:37', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45771', '["cpe:2.3:a:freeswitch:freeswitch:*:*:*:*:*:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-776"]', 'FreeSWITCH is a Software Defined Telecom Stack enabling the digital transformation from proprietary telecom switches to a software implementation that runs on any commodity hardware. Prior to version 1.11.0, FreeSWITCH\'s bundled XML parser expands nested <!ENTITY> declarations without a depth or count bound, so a small DTD can describe a body that expands exponentially ("billion laughs"). The PIDF body of a SIP PUBLISH is fed to this parser before any digest check, letting an unauthenticated network attacker force unbounded CPU and memory consumption with a single request. This issue has been patched in version 1.11.0.', 'CVE-2026-45771', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45740', 'NVD', '2026-05-13 16:17:00', '2026-05-13 20:50:15', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45740', '["cpe:2.3:a:protobufjs_project:protobufjs:*:*:*:*:*:node.js:*:*"]', null, 5.3, null, 'MEDIUM', null, '["CWE-674"]', 'protobufjs compiles protobuf definitions into JavaScript (JS) functions. Prior to 7.5.8 and 8.2.0, protobufjs could recurse without a depth limit while expanding nested JSON descriptors through Root.fromJSON() and Namespace.addJSON(). A crafted JSON descriptor with deeply nested namespace definitions could cause the JavaScript call stack to be exhausted during descriptor loading. This vulnerability is fixed in 7.5.8 and 8.2.0.', 'CVE-2026-45740', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45736', 'NVD', '2026-05-15 15:16:54', '2026-05-19 14:39:20', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45736', '["cpe:2.3:a:ws_project:ws:*:*:*:*:*:node.js:*:*"]', null, 4.4, null, 'MEDIUM', null, '["CWE-908"]', 'ws is an open source WebSocket client and server for Node.js. Prior to 8.20.1, the websocket.close() implementation is vulnerable to uninitialized memory disclosure when a TypedArray is passed as the reason argument. This vulnerability is fixed in 8.20.1.', 'CVE-2026-45736', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45731', 'NVD', '2026-05-29 14:16:31', '2026-06-01 18:39:21', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45731', '["cpe:2.3:a:wwbn:avideo:*:*:*:*:*:*:*:*"]', 6.9, 4.9, null, 'MEDIUM', null, '["CWE-22"]', 'WWBN AVideo is an open source video platform. In 29.0 and earlier, view/update.php reads $_POST[\'updateFile\'] as a relative path under updatedb/ and passes it to PHP\'s file() for line-by-line execution as part of a database migration. An authenticated administrator can abuse this to read arbitrary text files reachable from the web-server process.', 'CVE-2026-45731', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45700', 'NVD', '2026-05-29 20:16:27', '2026-06-01 17:23:57', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45700', '["cpe:2.3:a:freerdp:freerdp:*:*:*:*:*:*:*:*"]', 7.7, 9.8, null, 'HIGH', null, '["CWE-787"]', 'FreeRDP is a free implementation of the Remote Desktop Protocol. Prior to 3.26.0, FreeRDP\'s planar bitmap decoder has an out-of-bounds heap write when decoding RLE planar data. In libfreerdp/codec/planar.c, freerdp_bitmap_decompress_planar() validates the X destination coordinate nXDst against the caller-provided destination stride (nDstStep) even when it is writing into the internal temp buffer pTempData. An attacker can bypass the check with a large nDstStep and a large nXDst, causing planar_decompress_plane_rle() to write past the end of pTempData. This vulnerability is fixed in 3.26.0.', 'CVE-2026-45700', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45659', 'NVD', '2026-05-22 23:16:56', '2026-05-27 18:32:54', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45659', '["cpe:2.3:a:microsoft:sharepoint_server:*:*:*:*:subscription:*:*:*", "cpe:2.3:a:microsoft:sharepoint_server:2016:*:*:*:enterprise:*:*:*", "cpe:2.3:a:microsoft:sharepoint_server:2019:*:*:*:*:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-502"]', 'Deserialization of untrusted data in Microsoft Office SharePoint allows an authorized attacker to execute code over a network.', 'CVE-2026-45659', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45620', 'NVD', '2026-05-29 14:16:31', '2026-06-01 18:39:48', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45620', '["cpe:2.3:a:wwbn:avideo:*:*:*:*:*:*:*:*"]', null, 5.3, null, 'MEDIUM', null, '["CWE-204", "CWE-285"]', 'WWBN AVideo is an open source video platform. In 29.0 and earlier, objects/mention.json.php has no User::loginCheck() or admin gate. It only has an entry guard: preg_match(\'/^@/\', $_REQUEST[\'term\']) and hard-coded rowCount=10. This enables unauthenticated user enumeration.', 'CVE-2026-45620', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45619', 'NVD', '2026-05-29 14:16:30', '2026-06-01 18:40:21', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45619', '["cpe:2.3:a:wwbn:avideo:*:*:*:*:*:*:*:*"]', null, 6.5, null, 'MEDIUM', null, '["CWE-367", "CWE-918"]', 'WWBN AVideo is an open source video platform. In 29.0 and earlier, EpgParser.php, plugin/AI/receiveAsync.json.php, and other locations do not use the $resolvedIP out-param of isSSRFSafeURL() for DNS pinning via CURLOPT_RESOLVE, opening DNS-rebinding TOCTOU.', 'CVE-2026-45619', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45610', 'NVD', '2026-05-29 14:16:30', '2026-06-01 18:40:48', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45610', '["cpe:2.3:a:wwbn:avideo:*:*:*:*:*:*:*:*"]', null, 5.7, null, 'MEDIUM', null, '["CWE-306", "CWE-352"]', 'WWBN AVideo is an open source video platform. In 29.0 and earlier, there is a cross-site request forgery vulnerability on the 2FA toggle. plugin/LoginControl/set.json.php accepts POST type=set2FA value=false, calls LoginControl::setUser2FA(User::getId(), false) on the session-authenticated user, and returns. There is no forbidIfIsUntrustedRequest() call, no isTokenValid() check, no X-CSRF-Token/SameSite enforcement, and no re-authentication step. A cross-origin page that the victim visits while logged into the AVideo dashboard issues the POST via a hidden form (or fetch without credentials:"omit") and disables the victim\'s 2FA in one request.', 'CVE-2026-45610', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45584', 'NVD', '2026-05-20 13:16:37', '2026-05-20 18:56:32', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45584', '["cpe:2.3:a:microsoft:malware_protection_engine:*:*:*:*:*:*:*:*"]', null, 8.1, null, 'HIGH', null, '["CWE-122"]', 'Heap-based buffer overflow in Microsoft Defender allows an unauthorized attacker to execute code over a network.', 'CVE-2026-45584', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45580', 'NVD', '2026-05-29 14:16:30', '2026-06-01 18:41:10', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45580', '["cpe:2.3:a:wwbn:avideo:*:*:*:*:*:*:*:*"]', null, 5.4, null, 'MEDIUM', null, '["CWE-79"]', 'WWBN AVideo is an open source video platform. In 29.0 and earlier, there is a stored cross-site scripting vulnerability. The Live plugin\'s "YouTube-style" view renders the live transmission\'s stream key into an HTML class attribute by raw echo, without htmlspecialchars(). A canStream user can persist a key containing " plus an event handler via plugin/Live/saveLive.php, and any visitor (logged in or anonymous) opening the stream\'s live page executes attacker JavaScript in the platform origin.', 'CVE-2026-45580', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45578', 'NVD', '2026-05-29 14:16:30', '2026-06-01 18:41:19', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45578', '["cpe:2.3:a:wwbn:avideo:*:*:*:*:*:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-78"]', 'WWBN AVideo is an open source video platform. In 29.0 and earlier, there is a classic shell-metacharacter injection. The YPTSocket notification branch in plugin/Live/on_publish.php builds an execAsync() command line by string concatenation, single-quoting each argument but never calling escapeshellarg(). A \' in any of the three interpolated values ($users_id, $m3u8, $obj->liveTransmitionHistory_id) closes the quoted token and lets the attacker append arbitrary commands.', 'CVE-2026-45578', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45495', 'NVD', '2026-05-18 18:17:38', '2026-05-26 17:16:47', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45495', '["cpe:2.3:a:microsoft:edge_chromium:*:*:*:*:-:*:*:*"]', null, 8.8, null, 'HIGH', null, '["CWE-35", "CWE-20", "CWE-94", "CWE-119"]', 'Microsoft Edge (Chromium-based) Remote Code Execution Vulnerability', 'CVE-2026-45495', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45494', 'NVD', '2026-05-18 18:17:38', '2026-05-19 15:06:38', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45494', '["cpe:2.3:a:microsoft:edge_chromium:*:*:*:*:-:*:*:*"]', null, 5.4, null, 'MEDIUM', null, '["CWE-79"]', 'Microsoft Edge (Chromium-based) Spoofing Vulnerability', 'CVE-2026-45494', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45492', 'NVD', '2026-05-18 18:17:37', '2026-05-19 15:03:24', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45492', '["cpe:2.3:a:microsoft:edge_chromium:*:*:*:*:-:*:*:*"]', null, 5.4, null, 'MEDIUM', null, '["CWE-20"]', 'Improper input validation in Microsoft Edge (Chromium-based) allows an unauthorized attacker to bypass a security feature over a network.', 'CVE-2026-45492', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45479', 'NVD', '2026-06-09 17:17:22', '2026-06-10 19:42:22', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45479', '["cpe:2.3:a:microsoft:sharepoint_server:*:*:*:*:subscription:*:*:*", "cpe:2.3:a:microsoft:sharepoint_server:2016:*:*:*:enterprise:*:*:*", "cpe:2.3:a:microsoft:sharepoint_server:2019:*:*:*:*:*:*:*"]', null, 4.6, null, 'MEDIUM', null, '["CWE-79"]', 'Improper neutralization of input during web page generation (\'cross-site scripting\') in Microsoft Office SharePoint allows an authorized attacker to perform spoofing over a network.', 'CVE-2026-45479', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45468', 'NVD', '2026-06-09 17:17:21', '2026-06-11 02:43:12', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45468', '["cpe:2.3:a:microsoft:sharepoint_server:*:*:*:*:subscription:*:*:*", "cpe:2.3:a:microsoft:sharepoint_server:2016:*:*:*:enterprise:*:*:*", "cpe:2.3:a:microsoft:sharepoint_server:2019:*:*:*:*:*:*:*"]', null, 4.6, null, 'MEDIUM', null, '["CWE-79"]', 'Improper neutralization of input during web page generation (\'cross-site scripting\') in Microsoft Office SharePoint allows an authorized attacker to perform spoofing over a network.', 'CVE-2026-45468', null);
