INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45411', 'NVD', '2026-05-13 18:16:19', '2026-05-14 18:19:40', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45411', '["cpe:2.3:a:vm2_project:vm2:*:*:*:*:*:node.js:*:*"]', null, 9.8, null, 'CRITICAL', null, '["CWE-668"]', 'vm2 is an open source vm/sandbox for Node.js. Prior to 3.11.3, it is possible to catch a host exception using the yield* expression inside an async generator. When the generator is closed using the return function, the value is awaited on and exceptions thrown in the then call will be caught by the runtime and passed to the yield* iterator as the next value. This allows attackers to write code which can escape from the VM2 sandbox and execute arbitrary commands on the host system. This vulnerability is fixed in 3.11.3.', 'CVE-2026-45411', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45403', 'NVD', '2026-05-28 22:17:00', '2026-06-02 14:48:13', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45403', '["cpe:2.3:a:mintplexlabs:anythingllm:*:*:*:*:*:*:*:*"]', null, 2, null, 'LOW', null, '["CWE-59"]', 'AnythingLLM is an application that turns pieces of content into context that any LLM can use as references during chatting. Prior to 1.13.0, the AnythingLLM agent filesystem copy tool validates only the top-level source and destination paths. The recursive copy helper then descends into child entries using fs.stat() and copies files with fs.copyFile() without validating each child or rejecting symlinks. Because both APIs follow symlinks, a symlink nested inside an allowed source directory can point outside the allowed filesystem root and cause outside file contents to be copied into an allowed destination as a regular file. This vulnerability is fixed in 1.13.0.', 'CVE-2026-45403', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45286', 'NVD', '2026-06-01 19:16:50', '2026-06-03 20:35:59', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45286', '["cpe:2.3:a:nextcloud:calendar:*:*:*:*:*:*:*:*"]', null, 4.3, null, 'MEDIUM', null, '["CWE-200"]', 'Nextcloud is an open source content collaboration platform. From versions 5.5.13 to before 5.5.17, and 6.2.0 to before 6.2.3, an authenticated user can enumerate users on the same Nextcloud instance by using the Calendar app\'s endpoint for suggesting attendees. The sharing restrictions, applied to other endpoints, were not effective here. This issue has been patched in versions 5.5.17 and 6.2.3.', 'CVE-2026-45286', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45284', 'NVD', '2026-06-01 19:16:50', '2026-06-03 20:28:42', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45284', '["cpe:2.3:a:nextcloud:user_oidc:*:*:*:*:*:*:*:*"]', null, 4.6, null, 'MEDIUM', null, '["CWE-284"]', 'Nextcloud is an open source content collaboration platform. From version 1.3.6 to before version 8.4.0, an improper check allowed users that where provided by LDAP to still authenticate towards user OIDC after they where deleted. This issue has been patched in version 8.4.0.', 'CVE-2026-45284', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45278', 'NVD', '2026-06-01 19:16:49', '2026-06-03 17:34:59', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45278', '["cpe:2.3:a:nextcloud:user_oidc:*:*:*:*:*:*:*:*"]', null, 3.3, null, 'LOW', null, '["CWE-601"]', 'Nextcloud is an open source content collaboration platform. From version 6.1.0 to before version 8.2.2, an attacker can craft links that would redirect users to another website, when the victim uses the attackers link to log in via user OIDC. This issue has been patched in version 8.2.2.', 'CVE-2026-45278', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-4525', 'NVD', '2026-04-17 04:16:09', '2026-04-27 15:02:47', 'https://nvd.nist.gov/vuln/detail/CVE-2026-4525', '["cpe:2.3:a:hashicorp:vault:*:*:*:*:-:*:*:*", "cpe:2.3:a:hashicorp:vault:*:*:*:*:enterprise:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-201"]', 'If a Vault auth mount is configured to pass through the "Authorization" header, and the "Authorization" header is used to authenticate to Vault, Vault forwarded the Vault token to the auth plugin backend. Fixed in 2.0.0, 1.21.5, 1.20.10, and 1.19.16.', 'CVE-2026-4525', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45232', 'NVD', '2026-05-20 02:16:36', '2026-05-21 20:52:56', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45232', '["cpe:2.3:a:samba:rsync:*:*:*:*:*:*:*:*"]', 2.1, 3.1, null, 'LOW', null, '["CWE-193"]', 'Rsync versions before 3.4.3 contain an off-by-one out-of-bounds stack write vulnerability in the establish_proxy_connection() function in socket.c that allows network attackers to corrupt stack memory by sending a malformed HTTP proxy response. Attackers can exploit this by positioning themselves between the client and proxy or controlling the proxy server to send a response line of 1023 or more bytes without a newline terminator, causing a null byte to be written to an out-of-bounds stack address when the RSYNC_PROXY environment variable is set.', 'CVE-2026-45232', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45208', 'NVD', '2026-05-21 14:16:48', '2026-05-22 15:48:19', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45208', '["cpe:2.3:a:trendmicro:apex_one:*:*:*:*:on-premises:windows:*:*", "cpe:2.3:a:trendmicro:apex_one:*:*:*:*:saas:windows:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-367"]', 'A time-of-check time-of-use vulnerability in the Apex One/SEP agent could allow a local attacker to escalate privileges on affected installations.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45207', 'NVD', '2026-05-21 14:16:48', '2026-05-22 15:48:57', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45207', '["cpe:2.3:a:trendmicro:apex_one:*:*:*:*:on-premises:windows:*:*", "cpe:2.3:a:trendmicro:apex_one:*:*:*:*:saas:windows:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-346"]', 'An origin validation vulnerability in the Apex One/SEP agent could allow a local attacker to escalate privileges on affected installations. This is similar to CVE-2026-45206 but exists in a different process protection communication mechanism.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45206', 'NVD', '2026-05-21 14:16:47', '2026-05-22 15:49:22', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45206', '["cpe:2.3:a:trendmicro:apex_one:*:*:*:*:on-premises:windows:*:*", "cpe:2.3:a:trendmicro:apex_one:*:*:*:*:saas:windows:*:*"]', null, 7.8, null, 'HIGH', null, '["CWE-346"]', 'An origin validation vulnerability in the Apex One/SEP agent could allow a local attacker to escalate privileges on affected installations. This is similar to CVE-2026-45207 but exists in a different process protection communication mechanism.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45187', 'NVD', '2026-05-19 10:16:24', '2026-05-19 19:16:50', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45187', '["cpe:2.3:a:apache:ofbiz:*:*:*:*:*:*:*:*"]', null, 6.5, null, 'MEDIUM', null, '["CWE-285"]', 'Improper Authorization vulnerability in Apache OFBiz Webtools.
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45186', 'NVD', '2026-05-10 07:16:07', '2026-05-14 17:20:32', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45186', '["cpe:2.3:a:libexpat_project:libexpat:*:*:*:*:*:*:*:*"]', null, 2.9, null, 'LOW', null, '["CWE-407"]', 'In libexpat before 2.8.1, the computational complexity of attribute name collision checks allows a denial of service via moderately sized crafted XML input.', 'CVE-2026-45186', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45185', 'NVD', '2026-05-12 20:16:46', '2026-05-28 18:46:27', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45185', '["cpe:2.3:a:exim:exim:*:*:*:*:*:*:*:*"]', null, 9.8, null, 'CRITICAL', null, '["CWE-416"]', 'Exim before 4.99.3, in certain GnuTLS configurations, has a remotely reachable use-after-free in the BDAT body parsing path. It is triggered when a client sends a TLS close_notify mid-body during a CHUNKING transfer, followed by a final cleartext byte on the same TCP connection. This can lead to heap corruption. An unauthenticated network attacker exploiting this vulnerability could execute arbitrary code.', 'CVE-2026-45185', null);
INSERT INTO osscore.tmp_vul (source_id, source_name, source_publish_date, source_update_date, source_link, affected_version, cvss_score_v4, cvss_score_v3, cvss_score_v2, severity, type, cwe_id, description, cve_id, title) VALUES ('CVE-2026-45104', 'NVD', '2026-05-27 20:16:38', '2026-06-02 18:19:41', 'https://nvd.nist.gov/vuln/detail/CVE-2026-45104', '["cpe:2.3:a:osgeo:mapserver:*:*:*:*:*:*:*:*"]', null, 7.5, null, 'HIGH', null, '["CWE-129", "CWE-476"]', 'MapServer is a system for developing web-based GIS applications. From 6.4.0 to before 8.6.3, msSLDParseUserStyle always calls _SLDApplyRuleValues(psRule, psLayer, 1); for any <Rule> carrying <ElseFilter/> — it assumes msSLDParseRule added one class. When the rule has no symbolizer (a structurally valid SLD), msSLDParseRule adds zero, and _SLDApplyRuleValues ends up indexing _class[-1], resulting in a NULL pointer dereference. A 200-byte well-formed SLD via the WMS SLD_BODY= parameter is enough to trigger this, no auth required. This vulnerability is fixed in 8.6.3.', 'CVE-2026-45104', null);
